//   higuchi = 日口教官（2026.8.8 模擬オーラル。実地試験そのものの記録ではない）
//   fuka    = Fuka先生（飛行規程の講習。実地試験そのものの記録ではない）
// note: 原典を確認できていない箇所の注意書き（模範解答とは別枠で表示し、読み上げには含めない）
// imp: 3=複数の試験官・複数の回で繰り返し出ている定番　2=特定の試験官の定番　1=標準
