const JITCHI_QA_DATA = [

// ── 法規・書類 ──────────────────────────────────────────────
{cat:"law", imp:2, examiner:["konno"],
 q:"自家用操縦士の業務範囲を説明してください。報酬を受けて運航することはできますか。",
 a:"自家用操縦士の業務範囲は、航空法第28条及び別表第1において「報酬を受けないで航空機の運航を行うこと」と定められています。したがって、報酬を受ける目的で航空機を運航してはならず、体験搭乗のような形であっても、対価として金銭を受け取ることは認められません。",
 s:"できません。自家用操縦士は報酬を受けて航空機を運航することはできません。",
 hint:"「報酬を受ける目的での運航は禁止」という点が言えているか。"},

{cat:"law", imp:1, examiner:["konno"],
 q:"技能証明がなくても操縦できる航空機はありますか。",
 a:"重量100g未満のドローン・ラジコン機は「模型航空機」に分類され、免許や機体登録なしで飛行させることができます（ただし、小型無人機等飛行禁止法や自治体の条例の遵守は必要です）。また、超軽量動力機や一般航空機であっても、有資格者の監督下で行う操縦練習中であれば、技能証明を持たない人でも操縦できます。100g以上の無人航空機（ドローン）の基本飛行についても、特定の禁止空域や危険な飛行方法（レベル4飛行など）を除けば、資格がなくても機体登録や必要な許可申請を行うことで飛行させることが可能です。なお、滑空機（グライダー）自体は航空法上の航空機に該当するため、技能証明が必要です。",
 s:"100g未満の模型航空機（ドローン）は技能証明なしで飛行できます。有資格者の監督下での操縦練習や、登録・許可を得た100g以上のドローンの基本飛行も技能証明は不要です。滑空機自体は航空機に該当するため技能証明が必要です。",
 hint:"100g未満の模型航空機、有資格者監督下の操縦練習、登録・許可を得たドローンの基本飛行が技能証明不要である点、滑空機自体は技能証明が必要である点が言えているか。"},

{cat:"law", imp:2, examiner:["konno"],
 q:"滑空機の等級にはどのようなものがありますか。上級滑空機の技能証明で他の等級にも乗れますか。",
 a:"滑空機の等級は4種類です。初級・中級・上級滑空機に加え、動力滑空機（MG）があります。上級滑空機の技能証明を持っていれば初級・中級の滑空機にも搭乗できますが、動力滑空機を操縦するには、上級滑空機の資格とは別に限定変更を受ける必要があります。",
 hint:"等級が4種類（初級・中級・上級・動力滑空機）であること、上級は下位等級を包含すること、MGは別限定が必要なことに触れているか。"},

{cat:"law", imp:2, examiner:["konno"],
 q:"航空身体検査証明の種類と有効期間について説明してください。",
 a:"航空身体検査証明には第1種と第2種があります。第1種は定期運送用操縦士や事業用操縦士など、報酬を得て運航する場合に必要な区分で、基準がより厳しく定められています。第2種は自家用操縦士に必要な区分で、第1種より基準が緩やかです。自家用操縦士に必要なのは第2種航空身体検査証明です。有効期間は年齢により異なり、40歳未満は5年、40歳以上50歳未満は2年、50歳以上は1年です。",
 s:"航空身体検査証明には第1種と第2種があり、自家用操縦士には第2種が必要です。有効期間は50歳以上は1年です。",
 hint:"第1種と第2種の違い（対象・基準の厳しさ）に触れられるか。自家用操縦士には第2種が必要であること、年齢区分ごとの有効期間（5年／2年／1年）が言えているか。「一律5年」と答えると誤りになる点に注意。"},

{cat:"law", imp:1, examiner:["konno"],
 q:"飛行の際に携行しなければならないライセイセンス類は何ですか。",
 a:"飛行の際に携行しなければならないのは、技能証明書、航空身体検査証明書、航空特殊無線技士の免許証の3つです。加えて、航空法第71条の3により、有効な特定操縦技能審査に合格していなければ滑空機を操縦することはできません。この審査結果は独立した証明書ではなく、技能証明書の裏面に記載・印字される形で管理されます。特定操縦技能審査は2年ごとに実施され、技能の確認に加えて、法規の改正や新たな通報に関する口述試験も行われます。",
 s:"携行が必要なのは、技能証明書、航空身体検査証明書、航空特殊無線技士の免許証の3つです。加えて航空法第71条の3により、有効な特定操縦技能審査に合格している必要があり、その結果は技能証明書の裏面に記載されます。",
 hint:"携行が必要な3点（技能証明書・航空身体検査証明書・航空特殊無線技士免許証）を挙げられるか。特定操縦技能審査（航空法71条の3）の結果は独立の証明書ではなく技能証明書裏面に記載されること、2年ごとに技能確認と法規改正・新たな通報の口述試験が行われることに触れられるか。"},

{cat:"law", imp:1, examiner:["konno"],
 q:"視力が基準に合わなくなった場合はどうすればよいですか。",
 a:"視力が基準に合わなくなった場合は、まず眼鏡やコンタクトレンズで矯正します。そのうえで、自己判断で終わらせず、航空身体検査を受けて基準を満たしていることを確認する必要があります。眼鏡を新しく作った場合なども同様で、航空身体検査による確認が必要です。航空身体検査証明の条件として眼鏡等の使用が指定されている場合は、飛行中も必ず着用します。",
 s:"視力が基準に合わなくなった場合は、眼鏡やコンタクトレンズで矯正したうえで、航空身体検査を受けて基準を満たしていることを確認します。眼鏡を新調した場合も同様です。",
 hint:"矯正で対応できること、航空身体検査での確認が必要な点（眼鏡を新調した場合も含む）、条件として指定されれば飛行中の着用義務があることに触れているか。"},

{cat:"departure", imp:3, examiner:["nonaka"],
 q:"耐空証明書があれば、どんな整備・運用状態でも耐空性を有するといえますか。",
 a:"いいえ。耐空証明書には「指定した用途及び運用限界に従って整備し、運用するときは耐空性を有する」と書かれており、その用途・運用限界を指定しているのが、耐空証明書とセットで発行される運用限界等指定書です。用途は耐空類別の滑空機実用U、運用限界は飛行規程第2章として指定されており、この2枚がそろって初めて耐空性が証明されます。飛行規程第2章の運用限界を守らずに飛べば、耐空性を失い違法となります。",
 s:"いいえ。耐空証明書は「指定した用途及び運用限界に従って整備し、運用するとき」に耐空性を有するとしています。その用途と限界を定めるのが運用限界等指定書で、2枚そろって初めて耐空性が証明されます。",
 hint:"「条約並びに指定した用途及び運用限界に従って整備・運用するとき」という条件付きである点が言えているか。"},

{cat:"departure", imp:2, examiner:["nonaka"],
 q:"耐空検査証（耐空証明）は誰が発行しますか。",
 a:"耐空証明そのものは国土交通大臣が行うものですが、滑空機については耐空検査員が検査を行い、証明書を交付します。JA20HCの耐空証明書にも、耐空検査員の氏名と押印があります。あわせて押さえておきたいのは、証明書の本文が「指定した用途及び運用限界に従って整備し運用するときは耐空性を有することを証明する」となっていることです。無条件の証明ではなく、用途と運用限界に従うことが条件になっています。",
 s:"耐空証明そのものは国土交通大臣が行いますが、滑空機については耐空検査員が検査を行い、証明書を交付します。JA20HCの証明書番号は第2026-55-06号、発行は2026年4月10日、有効期間は2027年4月25日までです。",
 rel:["耐空証明書があれば、どんな整備・運用状態でも耐空性を有するといえますか。", "飛行規程承認書とは何ですか。"],
 hint:"滑空機は耐空検査員が検査・交付することが言えているか。証明書の「用途及び運用限界に従って運用するときは」という条件付きである点に触れられるか。"},

{cat:"departure", imp:1, examiner:["nonaka"],
 q:"ノータム（NOTAM）はどこで確認しますか。",
 a:"SWIM（航空情報共有システム）のウェブサイトで確認します。具体的には、デジタルノータムリクエストサービスまたはデジタルノータム検索を使って、飛行場や空域に関する最新のノータムを確認します。",
 hint:"SWIMという公式な情報源と、デジタルノータムリクエストサービス／デジタルノータム検索という具体的な確認手段の両方が言えているか。"},

{cat:"departure", imp:1, examiner:["nonaka"],
 q:"航空図（航空路図・チャート）が最新かどうかはどのように判断しますか。",
 a:"チャートに記載されている発行日・改訂サイクルを確認し、最新版が発行されていないか、AISの情報と照らし合わせて確認します。古い版のまま使用してはいけません。",
 hint:"発行日の確認と最新版への更新の必要性に触れているか。"},

{cat:"law", imp:2, examiner:["nonaka","sakai","konno"],
 q:"フライトプランはどのような場合に必要ですか。どこに、どのように提出しますか。オープンやクローズを忘れるとどうなりますか。",
 a:"滑空場から9km以上離れて飛行する場合に必要です。提出先は東京FAIBへの電話、またはSWIMシステムのウェブです。手順はファイル（提出）→オープン（出発前の開設通報）→クローズ（着陸後の終了通報）の順です。ファイルした時点でプランは生きているため、クローズを忘れると、想定される到着時刻を一定時間過ぎた段階で捜索救難の各段階（不確実の段階→警戒の段階→遭難の段階）に移行し、捜索が開始されるおそれがあります。クローズまでが自分の責任です。逆に言えば、滑空場から9km圏内のフィールドへの離着陸を繰り返すだけの運航であれば、フライトプランの提出は不要です。",
 s:"滑空場から9km以上離れて飛ぶ場合に必要です。提出先は東京FAIBへの電話かSWIMのウェブで、ファイル、オープン、クローズの順です。クローズを忘れると、到着予定時刻を過ぎた段階で捜索救難の段階が進んでしまいます。9km圏内のみの運航なら提出は不要です。",
 hint:"9kmという提出義務の基準、ファイル→オープン→クローズという用語、クローズ忘れが捜索救難につながる流れが言えているか。9km圏内のみの運航なら提出不要と即答できるか。"},

{cat:"departure", imp:2, examiner:["nonaka"],
 q:"固定バラストの重量とアーム（モーメント）の関係を説明してください。",
 a:"モーメントは重量とアームの積で表されます。固定バラストは機首側の、重心から前方に離れた位置に装着されるため、実際の重さよりも大きな効き方をします。ASK21 JA20HCの飛行規程では、バラスト0枚のとき前席最小重量70.00kg、1枚で68.75kg、以下1枚ごとに1.25kgずつ下がり、12枚で55.00kgとなります。差の15.00kgを12枚で割ると、ちょうど1.25kgです。つまりバラスト1枚が搭乗者重量1.25kg分に相当する、というのは飛行規程の表がそう定めているということで、これは概数ではなく厳密な値です。効き方を決めるのは重量そのものではなく、重量とアームの積です。",
 s:"モーメントは重量とアームの積です。固定バラストは重心から前方に離れた位置に付くので、実際の重さより大きく効きます。飛行規程の表では、1枚が搭乗者1.25kg分にあたります。",
 rel:["固定バラスト1枚が搭乗者重量1.25kg分として効くのは、なぜですか。", "重量限界にはどのようなものがありますか。", "ASK21の許容重心位置範囲を答えてください。"],
 hint:"モーメント＝重量×アームという関係と、「1枚＝搭乗者重量1.25kg相当」が飛行規程の表から厳密に出る値であることが言えているか。"},

{cat:"departure", imp:2, examiner:["fuka"],
 q:"前席最小重量70kgは、パラシュートを含めた重量ですか。",
 a:"含めた重量と読むのが自然です。飛行規程の項目名が「操縦席搭載重量」であり、「以上の搭載制限内であれば、重心位置は許容限界内に収まる」と結ばれているためです。ただし同じ頁の注意書きには「1枚のバラストは搭乗者重量1.25kgに相当する」ともあり、用語は完全には統一されていません。実務上は、パラシュートを含めた重量で判定するのが安全です。",
 s:"はい。含まれています。",
 rel:["固定バラスト1枚が搭乗者重量1.25kg分として効くのは、なぜですか。", "重量限界にはどのようなものがありますか。", "今日の離陸重量と重心位置を計算して示してください。"],
 hint:"「操縦席搭載重量」という項目名を根拠に挙げられているか。「以上の搭載制限内であれば重心位置は許容限界内に収まる」という一文に触れられるか。用語が揺れている点を認めたうえで、実務上の判定方法まで言えるか。"},

{cat:"departure", imp:2, examiner:["fuka"],
 q:"固定バラスト1枚が搭乗者重量1.25kg分として効くのは、なぜですか。鉛ディスクの実際の重さは何kgですか。",
 a:"てこの原理（モーメントの釣り合い）が働くためです。効き方を決めるのは重量とアームの積で、バラストを積むことと前席に1.25kg乗せることが等価になる条件は、バラストの実重量かけるバラストのアームが、1.25かける前席のアームに見合うことです。鉛ディスクの実際の重さは1枚あたり1.0kgで、JA20HCの前席アーム基準点前方1180mmから1250mmに当てはめると、取付位置は基準点前方およそ1.5mから1.6mになります。",
 s:"てこの原理（モーメントの釣り合い）が働くためです。鉛ディスクの実際の重さは1枚あたり1.0kgです。",
 note:"重量重心シートでは固定錘のアームを1250mmとしていますが、これは前席アームと同じ値です。実際の取付位置がこれと異なる場合、重心計算はわずかにずれます。ただし4枚積んだ場合でアームを1250mmから1600mmに直しても重心の差は約2.5mmで、判定は変わりません。",
 rel:["固定バラストの重量とアーム（モーメント）の関係を説明してください。", "ASK21の許容重心位置範囲を答えてください。"],
 hint:"「アームが前方だから」で止めず、重量とアームの積で決まること、実重量1.0kgに対しアームは約1.5〜1.6m必要になることまで言えているか。"},

// ── 空域・通信 ──────────────────────────────────────────────
{cat:"airspace", imp:3, examiner:["nonaka","sakai","konno","higuchi","yuda"],
 q:"VFRで飛行する際のVMC（有視界気象状態）の条件について説明してください。滝川の飛行エリアではどうなりますか。",
 a:"高度と空域で3つに分かれます。1つ目、高度3,000m以上。飛行視程8,000m以上で、雲から水平1,500m、上下それぞれ300mです。2つ目、高度3,000m未満。雲からの距離は上方150m、下方300m、水平600mで、飛行視程は管制区・管制圏・情報圏の内側なら5,000m以上、その外側なら1,500m以上です。3つ目、そのうち地表または水面から300m以下で、管制区等の外側の空域。ここだけは雲から離れて飛行できればよく、飛行視程1,500m以上です。滝川では、300m未満がクラスGなので3つ目にあたり、雲から離れて視程1,500m。300m以上は管制区に入るので2つ目に切り替わり、雲から上方150m・下方300m・水平600m、飛行視程5,000m以上になります。同じ300mの線が管制区の下限でもあるので、そこで基準が一段厳しくなる、と覚えます。説明するときは区分航空図で滝川の位置と空域を指しながら話し、視程は周辺の目標物の見え方で判断して、基準を下回るなら飛ばない、と続けます。",
 s:"高度と空域で3つです。3,000m以上は飛行視程8,000m、雲から水平1,500m・上下300m。3,000m未満は雲から上方150m・下方300m・水平600mで、飛行視程は管制区等の内側5,000m、外側1,500m。そのうち地表から300m以下で管制区等の外なら、雲から離れて視程1,500mです。滝川は300m未満がクラスGでこの3つ目、300m以上は管制区なので視程5,000mに切り替わります。",
 rel:["高度3,000m以上におけるVMCの気象条件を", "高度3,000m未満におけるVMCの気象条件を", "クラスGの空域、高度300m以下でのVMC基準を", "滝川滑空場では、何m以上が航空交通管制区に", "視程1,500mというと、実際にはどれくらいの見え方ですか"],
 hint:"3つの高度帯・空域区分を整理して言えるか。300m以下だけ「雲から離れて」でよいことに触れられるか。滝川では300mの線を境に1,500mから5,000mへ切り替わることを説明でき、区分航空図で空域を指せるか。"},

{cat:"airspace", imp:3, examiner:["sakai"],
 q:"クラスGの空域、高度300m以下でのVMC基準を説明してください。",
 a:"雲から離れて飛行できること、そして飛行視程が1,500m以上あることが基準です。",
 hint:"「雲から離れて」と「視程1,500m以上」の2点、高度300m以下という条件が正確に言えているか。"},

{cat:"airspace", imp:3, examiner:["nonaka","sakai","konno"],
 q:"高度3,000m未満におけるVMCの気象条件を説明してください。",
 a:"雲からの距離は上方150m・下方300m・水平600mです。飛行視程は、管制区・管制圏・情報圏の内側では5,000m以上、それ以外の外側では1,500m以上が必要です。",
 hint:"上150m・下300m・水平600mという雲との距離、視程が内側5,000m／外側1,500mという使い分けが正確に言えているか。"},

{cat:"airspace", imp:2, examiner:["nonaka","sakai","konno"],
 q:"高度3,000m以上におけるVMCの気象条件を説明してください。",
 a:"雲からの距離は上方・下方とも300m、水平に1,500mです。飛行視程は8,000m以上が必要です。",
 hint:"上下とも300m・水平1,500mという雲との距離、視程8,000m以上という数値が正確に言えているか。"},

{cat:"airspace", imp:2, examiner:["nonaka","sakai","konno"],
 q:"管制圏・情報圏内の飛行場付近でのVMCはどのような基準ですか。",
 a:"視程5,000m以上、雲高300m以上であることが基準です。",
 hint:"視程5,000m・雲高300mという数値が正確に言えているか。"},

{cat:"airspace", imp:3, examiner:["nonaka","sakai","konno","higuchi"],
 q:"管制区と管制圏の違いを説明してください。",
 a:"最も大きな違いは管制承認（クリアランス）の有無です。有視界飛行方式では、管制圏に入るには承認が必要ですが、管制区は承認なしで飛行できます。ただし計器飛行方式では、管制区・管制圏のどちらにも承認が必要です。空域そのものの違いとしては、管制圏はクラスDで、空港の周囲5NM（9km）の範囲、地表面から原則3,000ftMSLまでの空域です（旭川空港は4,000ft）。管制区はクラスEで、管制圏の外側に広がり、底は原則2,000ftAGLですが、空港から20NM以内では700ft、40NM以内では1,000ftに下がります。ほかにも、高度の指定が管制圏の上限はMSL・管制区の底はAGLであること、管制圏には上限高度があるが管制区にはないこと、設定の目的が管制圏は飛行場周辺の交通整理・管制区は航空路の保護であることが違いとして挙げられます。",
 s:"管制承認が要るかどうかです。有視界飛行方式なら、管制圏は承認が必要、管制区は承認なしで入れます。管制圏はクラスDで空港の周囲9km・原則3,000ftまで、管制区はクラスEでその外側です。",
 rel:["情報圏とは何ですか。", "管制圏にあって情報圏にはないものは何ですか。", "管制圏には無許可で進入できますか。"],
 hint:"まずクリアランスの有無（VFRとIFRで違う）が言えているか。加えて5NM・3,000ftMSL、底2,000ftAGL、MSLとAGLの違いのいずれかに触れられているか。"},

{cat:"airspace", imp:2, examiner:["nonaka","sakai"],
 q:"情報圏とは何ですか。管制圏との違いは何ですか。",
 a:"情報圏は、管制業務が行われていない空港等の周辺に設定され、飛行場での運航に必要な情報を提供する空域です。管制圏のような進入の承認は不要ですが、飛行場対空無線局への連絡等が求められます。",
 hint:"情報圏には管制承認が不要な点、情報提供が目的である点が言えているか。"},

{cat:"airspace", imp:2, examiner:["sakai"],
 q:"特別管制区（特管区）とは何ですか。滑空機は自由に飛行できますか。",
 a:"特別管制区（特管区）は、航空法第94条の2に基づき、航空交通が極めて混雑する主要空港周辺に設定された、原則としてIFR機しか飛行できない最も規制の厳しい空域です。滑空機はVFRで運航するため自由には飛行できず、通過するには事前に管制官の許可を得たうえで、常時交信できるVHFとトランスポンダーの装備が必須です。実際には安全上の理由から、滑空機への飛行許可が下りることはほとんどありません。",
 hint:"根拠条文（航空法第94条の2）、原則IFR機のみという規制の厳しさ、滑空機がVFR運航のため進入には管制官の許可とVHF・トランスポンダーの装備が必須であること、実際には許可がほぼ下りないことまで言えているか。"},

{cat:"airspace", imp:1, examiner:["sakai"],
 q:"管制圏内で天気が悪化した場合、特別有視界飛行方式（SVFR）とはどのような制度ですか。",
 a:"管制圏内の天気が悪化して通常の有視界気象状態（VMC）を満たさなくなった場合でも、管制官から特別な許可（クリアランス）を得ることで、有視界のまま管制圏内を飛行・離着陸できる救済措置としての制度です。",
 hint:"通常のVMCを満たさなくなった場合の救済措置であること、管制官からの特別な許可（クリアランス）が前提であることに触れているか。"},

{cat:"lookout", imp:3, examiner:["sakai","konno"],
 q:"滑空機の進路権について説明してください。進路権がある場合、何をすればよいですか。",
 a:"見張り義務は航空法第71条の2、進路権は航空法第83条と施行規則に定められています。進路権の順位は、1番が滑空機、2番が物件を曳航している航空機、3番が飛行船、4番が飛行機・回転翼航空機・動力滑空機です。進路権を有していても、そのままの速度・進路を維持していれば無条件によいわけではなく、他機との衝突を避けるために必要な速度・進路の維持と見張りの義務があります。「進路権があるからこのまま進む」というのは大きな勘違いで、まず回避することが大切です。",
 s:"進路権の順位は、1番が滑空機、2番が物件を曳航している航空機、3番が飛行船、4番が飛行機などです。進路権があっても速度・進路を維持しつつ見張りを続ける義務があり、そのまま進んでよいという意味ではなく、まず回避することが大切です。",
 hint:"進路権の順位（滑空機が1番、動力滑空機は飛行機・回転翼と同じ4番）、速度・進路を維持しつつ見張りを続ける義務があること、進路権があっても回避が優先という注意点のすべてに触れているか。"},

{cat:"lookout", imp:2, examiner:["konno"],
 q:"航空機同士がコリジョンコース（衝突コース）にある場合、どちらが優先されますか。",
 a:"航空法上の進路権の順位は、1番が滑空機、2番が物件を曳航している航空機、3番が飛行船、4番が飛行機・回転翼航空機・動力滑空機（同順位）です。正面で接近する同順位同士は互いに右へ避け、追い越しは前の機体の右側を通過し、最終進入経路にある機体が優先されます。",
 hint:"滑空機が最優先（1番）であること、同順位同士は互いに右へ避けるという原則が言えているか。"},

{cat:"airspace", imp:2, examiner:["sakai","konno"],
 q:"トランスポンダーはどのような時に使用しますか。VFRで飛行する際のコードは何番ですか。",
 a:"トランスポンダーは、①航空法施行規則第146条・告示で指定された義務空域（管制区のうち高度10,000ft以上や特別管制区など）を飛行するとき、②進入管制区のような管制機関の管轄空域を通過し、管制官からスコークコード（4桁の識別符号）を指示されたとき、に使用します。VFRで飛行する場合、10,000ft未満は1200、10,000ft以上は1400をセットします。",
 hint:"1200／1400というコードの高度による使い分けが言えているか。義務空域と管制官の指示という2つの使用場面を整理できているか。"},

{cat:"airspace", imp:1, examiner:["nonaka"],
 q:"緊急事態が発生した場合、トランスポンダーはどのコードにセットしますか。",
 a:"7700にセットします。",
 hint:"7700＝緊急状態という対応関係が言えているか。"},

{cat:"airspace", imp:2, examiner:["nonaka","konno","yuda"],
 q:"捜索救難の段階区分について説明してください。着陸予定時刻を過ぎるとどうなりますか。",
 a:"不確実の段階、警戒の段階、遭難の段階の3段階です。国際的にはINCERFA、ALERFA、DETRESFAと呼ばれ、AIMの捜索救難のページに載っています。大事なのは、段階ごとに行う捜索がセットで決まっていることです。まず不確実の段階に入るのは、位置通報または運航状態通報が予定時刻から30分過ぎてもないとき、あるいは目的地に予定時刻から30分を過ぎても到着しないときで、ここで第一段通信捜索（パイロットへの電話など）が始まります。それでも消息がつかめないか、第一段通信捜索の開始から30分たつと警戒の段階に上がり、拡大通信捜索（空港など）に移ります。着陸許可を受けたのに5分たっても着陸せず、連絡もとれないという場合もここです。拡大通信捜索でも分からないか、その開始から1時間たつと遭難の段階となり、本格的な捜索救難活動に入ります。燃料が尽きたと推定されるとき、不時着しようとしている、あるいはしたという情報が入ったときも遭難の段階です。取り仕切るのは救難調整本部、RCCです。ですからフライトプランを出して飛んだ場合、着陸後にクローズし忘れると、着陸予定時刻から30分で不確実の段階が始まってしまいます。",
 s:"不確実の段階、警戒の段階、遭難の段階の3段階で、それぞれ行う捜索がセットになっています。目的地に予定時刻から30分過ぎても到着しないと不確実の段階で、第一段通信捜索（パイロットへの電話など）。その開始から30分で警戒の段階に上がって拡大通信捜索（空港など）。さらに1時間で遭難の段階となり、本格的な捜索救難活動です。フライトプランのクローズを忘れると、30分で不確実の段階が始まります。",
 note:"段階に入る条件（30分、着陸許可後5分、第一段通信捜索から30分、拡大通信捜索から1時間）は公開されている運用資料で確認したもので、協定や実施細目の本文そのものには当たれていない。手元にAIMがあれば捜索救難のページで照合を。",
 hint:"3段階の名称と順序（不確実→警戒→遭難）が言えているか。3つ目を「非常」と言ってしまわないこと。段階ごとに第一段通信捜索→拡大通信捜索→捜索救難活動と措置が決まっていること、30分→30分→1時間というつながりまで言えると加点。"},

{cat:"airspace", imp:1, examiner:["konno"],
 q:"昼間の障害標識にはどのようなものがありますか。",
 a:"高さ60m以上で、昼間に航行する航空機から見えにくい煙突や鉄塔、送電線などには、赤白の縞模様の塗装や、球形の標識（マーカーボール）などが取り付けられ、視認しやすくする工夫がされています。",
 hint:"対象となる基準（高さ60m以上で昼間の航空機から見えにくいもの）と、赤白の縞模様・マーカーボールなど具体的な例が挙げられているか。"},

{cat:"airspace", imp:1, examiner:["konno"],
 q:"曲技飛行を行う上での基準にはどのようなものがありますか。",
 a:"航空法施行規則第197条の3により、曲技飛行は宙返り、横転、反転、背面、きりもみ、ヒップストールなど、姿勢や速度の急激な変化を伴う一連の飛行と定義されています。人や家屋が密集している地域の上空、航空交通管制区、航空交通管制圏内では原則として禁止され、行う場合は国土交通大臣の許可が必要です。実施条件として、高度3,000m未満では視程5,000m以上を確保し、周囲の最高障害物から300m以上の高度を保たなければならず、搭乗者全員分の落下傘の装備が義務付けられています。機体面では、耐空性審査要領等に基づく「曲技A」の強度・構造基準に適合している必要があり、主に最大離陸重量750kg以下の機体が対象です。",
 hint:"根拠条文（施行規則第197条の3）と曲技飛行の定義、原則禁止空域（人家密集地域・管制区・管制圏）とその許可、実施条件（視程5,000m以上・障害物から300m以上・落下傘装備）、機体基準（曲技A・最大離陸重量750kg以下）のいずれかに具体的に触れられているか。"},

{cat:"airspace", imp:1, examiner:["nonaka"],
 q:"20,000ft以上を飛行する場合、どのような制限がありますか。",
 a:"主に3つの制限があります。1つ目は空域・管制で、18,000ft以上はクラスAの管制空域にあたり、ATCとの交信・飛行承認（クリアランス）が必要です。2つ目は生理面で、低酸素症を防ぐため、高高度用の酸素供給装置による継続的な酸素吸入が絶対条件です。3つ目は機体・装備面で、トランスポンダー（またはADS-B Out）の搭載・作動が義務づけられるほか、氷点下20〜30℃という極寒に対応するため、キャノピーの凍結対策や防寒装備が必要になります。",
 s:"空域・管制（クラスA進入にATCの承認が必要）、生理面（酸素供給装置による継続的な吸入）、機体・装備（トランスポンダーの搭載、耐寒対策）の3つの制限があります。",
 hint:"空域・管制、生理面、機体・装備の3つに整理できているか。クラスA・酸素供給・トランスポンダー・耐寒対策のいずれかに具体的に触れられているか。"},

{cat:"airspace", imp:1, examiner:["konno"],
 q:"着陸時に見る4つ並んだ標識（パス指示灯）で、赤赤白白の場合はパス角がどうなっていることを示しますか。",
 a:"赤赤白白（手前2つが赤、奥2つが白）は、正しい進入角度（適正なパス角）で飛行していることを示します。",
 hint:"赤赤白白が適正な進入角であるという対応関係が言えているか。白の数が多いほど高すぎ、赤の数が多いほど低すぎることも合わせて言えるとなお良い。"},

// ── 機体・ASK21 ──────────────────────────────────────────────
{cat:"aircraft", imp:2, examiner:["nonaka","sakai","konno","yuda"],
 q:"ASK21はどのような航空機ですか。基本的な諸元を説明してください。",
 a:"ASK21は複座の練習用グライダーで、FRPサンドイッチのモノコック構造です。T型尾翼、ノーズ車輪、主翼上面展開式のエアブレーキを備え、主脚には緩衝装置が付いています。初等練習から記録飛行、曲技飛行までができる機体です。諸元は翼幅17.00m、全長8.35m、全高1.55m、翼面積17.95平方メートル、アスペクト比16.1、最大離陸重量600kg、最大翼面荷重33.4kg毎平方メートルです。JA20HCは2002年2月14日製造で、耐空類別は滑空機 実用Uです。",
 s:"複座の練習用グライダーで、FRPサンドイッチのモノコック構造、T型尾翼です。翼幅17.00m、全長8.35m、翼面積17.95平方メートル、アスペクト比16.1、最大離陸重量600kg。JA20HCの耐空類別は滑空機 実用Uです。",
 rel:["ASK21の耐空類別は何ですか。", "重量限界にはどのようなものがありますか。"],
 hint:"複座・T尾翼・FRPモノコックという構造の特徴に加え、翼幅17m／全長8.35m／全高1.55m／最大離陸重量600kg あたりの数値が言えているか。"},

{cat:"aircraft", imp:1, examiner:["nonaka","konno"],
 q:"ASK21の組み立てには何人、どのくらいの時間が必要ですか。",
 a:"4〜5名の人員と、約30分〜1時間の時間が必要です。熟練度や補助器具の有無により前後します。",
 hint:"複数人（4〜5人程度）で行う共同作業であることが言えているか。"},

{cat:"aircraft", imp:2, examiner:["nonaka","konno"],
 q:"主翼の組立要領について説明してください。",
 a:"主翼を胴体に差し込み、翼根の接合部を確実に合わせてから、主ピンを挿入して固定します。ピンが確実にロックされているか、抜け止めがかかっているかを必ず確認するとともに、ロッドの接続確認も行います。",
 hint:"ピンの挿入と、確実にロックされているかの確認、ロッドの接続確認が言えているか。"},

{cat:"aircraft", imp:2, examiner:["nonaka","konno"],
 q:"水平尾翼の取り付け要領と点検のポイントは何ですか。やってはいけないことはありますか。",
 a:"水平尾翼を所定の位置に差し込み、固定ピンを挿入して確実にロックします。取り付け後は前後に動かして固定を確認しますが、無理に力をかけて動かしすぎるとリンケージや取り付け部を傷める恐れがあるため、確認は必要最小限の力で行います。また、尾翼が少しでも傾いていたり、砂などの異物が噛んでいたりするとピンは入りません。無理な力でピンやボルトを押し込むと、内部の構造（グラスファイバーや受け側の金属）を破断・変形させ、飛行中に尾翼が脱落する原因になります。すんなり入らないときは、必ず角度や異物を確認します。",
 hint:"固定ピンの確認と、力を入れすぎて動かさないという注意点に加え、ピンが入りにくいときは無理に押し込まず角度や異物を確認するという点まで言えているか。"},

{cat:"aircraft", imp:2, examiner:["nonaka","konno"],
 q:"組立時のリンケージ（操縦索・コネクション）の点検要領を説明してください。",
 a:"翼と胴体をつなぐ操縦系統のコネクションが確実に接続されているか、目視と手で引っ張って抜けがないかを確認します。舵面を実際に動かし、コックピットの操縦桿・ペダルの動きと舵面の動きが正しく一致しているかも確認します。",
 hint:"目視・引張確認に加えて、実際に操作して舵面の動きと一致するか確認する点が言えているか。"},

{cat:"aircraft", imp:2, examiner:["nonaka","sakai"],
 q:"操縦系統は舵面とどのようにつながっていますか。",
 a:"操縦桿やペダルの動きは、索（ワイヤー）とプッシュロッドを介して舵面に伝えられます。分解・組立時に切り離す部分と、機体に固定されたまま分解しない部分があります。",
 hint:"索とプッシュロッドの組み合わせで動力を伝えている点が言えているか。"},

{cat:"aircraft", imp:1, examiner:["sakai"],
 q:"ラダーのワイヤーはなぜ組立・分解時にジャム（引っかかり）しにくい構造になっていますか。",
 a:"ワイヤーの端末にS字フックのような形状の接続金具を使用しており、着脱がしやすく、また誤った経路に入り込みにくい構造になっているためです。",
 hint:"S字フック状の接続金具が使われている点が言えているか。"},

{cat:"aircraft", imp:2, examiner:["nonaka","konno"],
 q:"TEチューブ（TEシステム）とは何ですか。何のためについていますか。バリオメーター（昇降計）は何を表示していますか。降下すると針はどう動きますか。",
 a:"バリオメーターは機体の垂直方向の速度（m/s）を表示する計器で、上昇でプラス、降下でマイナス側に針が振れます。TEチューブ（Total Energy＝全エネルギー補償チューブ）は、機首の上げ下げによる速度変化のせいで生じる見かけの上昇・下降（スティック・サーマル）を打ち消し、大気そのものの上昇・下降気流だけをバリオメーターに表示させるための装置です。機首を上げ下げすると速度が変わり、それに伴って静圧も変化するため、気流自体は変わっていなくても昇降計に見かけの変化が出てしまいます。TEチューブは飛行速度に応じて生じる動圧を利用し、静圧ラインから速度変化分の圧力を差し引くことでこの影響を打ち消しています。これにより、操縦による偽の上昇に惑わされず、本当の上昇気流（サーマル）を正確に見つけることができます。",
 s:"バリオメーターは機体の垂直方向の速度（m/s）を表示する計器で、上昇でプラス、降下でマイナス側に針が振れます。TEチューブは、速度変化に伴う静圧の変化を動圧を使って打ち消し、機首の上げ下げによる見かけの上昇・下降を消して、大気そのものの上昇気流だけを表示させるための装置です。",
 hint:"バリオメーターが表示する内容（垂直方向の速度、上昇でプラス・降下でマイナス）、TEチューブの仕組み（動圧を利用して静圧の変化分を打ち消す）、一般的な昇降計との違いが言えているか。"},

{cat:"aircraft", imp:2, examiner:["nonaka","konno"],
 q:"ダイブブレーキは何をするための装置ですか。連動して動く部品はありますか。",
 a:"ダイブブレーキは主翼上面に展開し、揚力を減らして沈下率を増やし、降下角や速度を調整するための装置です。連動して動く部品はブレーキです。",
 hint:"減速・降下率増加という機能が言えているか。"},

{cat:"aircraft", imp:1, examiner:["nonaka"],
 q:"スリップランディング（横滑り降下）を行う際、速度計が0（またはおかしな値）を示さないようにするにはどうすればよいですか。",
 a:"横滑りによってピトー管が正対気流から外れると速度計の指示が乱れることがあるため、横滑りの角度を過大にしすぎず、速度計の指示に頼りすぎず姿勢や機速感で速度を維持することが大切です。",
 hint:"横滑りでピトー管への気流が乱れて指示が不正確になり得るという点に触れているか。"},

{cat:"aircraft", imp:3, examiner:["nonaka"],
 q:"ウインチ曳航（WT）のヒューズはなぜ2枚ついていますか。それぞれの値は同じですか。",
 a:"理由は2つあります。1つは冗長性で、1枚が切れてももう1枚が残るため、いきなり索が切れる可能性が減ります。もう1つが重要で、2枚は穴の大きさが違います。小さい穴のほうが先に伸びるので、その穴の伸び具合を見ることで、破断が近いかどうかを事前に知ることができます。ASK21のウインチ曳航用の曳航索安全装置は最大1000プラスマイナス100daNで、トストの黒にあたります。なお2枚とするかは運航者の運用によるもので、1枚のところもあります。",
 s:"理由は2つです。1枚が切れてももう1枚が残るという冗長性と、2枚の穴の大きさが違うことです。小さい穴が先に伸びるので、伸び具合を見れば破断が近いかどうかを事前に知ることができます。",
 rel:["ヒューズの点検では具体的に何を確認しますか。", "航空機曳航（AT）のロープにはヒューズが付いていませんが"],
 hint:"冗長性だけで終わらず、「2枚は穴の大きさが違い、小さい穴の伸びで破断の兆候が分かる」という点まで言えているか。1000±100daNという数値も。"},

{cat:"aircraft", imp:2, examiner:["nonaka"],
 q:"航空機曳航（AT）のロープにはヒューズが付いていませんが、問題ありませんか。",
 a:"問題ありません。曳航索そのものの破断強度が、航空機曳航用の曳航索安全装置に求められる値と同程度だからです。ASK21の飛行規程では航空機曳航用の曳航索安全装置は最大600プラスマイナス60daNとされており、索自体がその役目を果たしています。「緩衝材のようなもの」といった曖昧な言い方はせず、「破断強度が同程度なので」と答えるのが正確です。",
 s:"問題ありません。曳航索そのものの破断強度が、航空機曳航用の曳航索安全装置に求められる値と同程度だからです。飛行規程では最大600プラスマイナス60daNとされており、索自体がその役目を果たしています。",
 rel:["ウインチ曳航（WT）のヒューズはなぜ2枚ついていますか。"],
 hint:"「破断強度が同程度だから」と言い切れているか。600±60daNという数値まで言えれば十分。"},

{cat:"aircraft", imp:1, examiner:["nonaka"],
 q:"航空機曳航（AT）とウインチ曳航（WT）で、レリーズの位置（どちらが機首側か）に違いはありますか。",
 a:"機首側（ノーズ）にあるのが航空機曳航（AT）用、それよりも後ろの機体下部（主脚付近・重心近く）にあるのがウインチ曳航（WT）用です。",
 hint:"ノーズにあるのが航空機曳航（AT）用、後方（主脚付近・重心近く）にあるのがウインチ曳航（WT）用と言えているか。"},

{cat:"aircraft", imp:1, examiner:["nonaka"],
 q:"ウインチ曳航のレリーズは、上昇限度になると自然に離脱しますか。航空機曳航のレリーズはどうですか。",
 a:"ウインチ曳航ではロープの角度や張力の関係で上昇限度に近づくと自然に離脱しやすい特性がありますが、航空機曳航ではそうした自然離脱は前提とされておらず、機長が意図的にレリーズを操作して離脱します。",
 hint:"WTとATで自然離脱のしやすさに違いがある点が言えているか。"},

{cat:"aircraft", imp:1, examiner:["nonaka"],
 q:"レリーズの使用回数には制限がありますか。",
 a:"あります。発航回数で2,000回です。ただし飛行規程には回数の定めはありません。飛行規程は第2章の2-5に使えるレリーズの形式を挙げているだけです。回数が書かれているのは耐空検査準備作業報告書の装備品の名称・形式の表で、航空機曳航用レリーズも、ウインチ曳航用レリーズも、どちらも2,000回と記載されています。もうひとつ、レリーズには操作回数10,000回という数字もあります。これはメーカーが決めている数字で、寿命を決めているのは中の戻しばねで、その寿命がおよそ10,000回の操作です。通常は1発航あたり5回ほど操作するので、10,000割る5で2,000発航という目安になっており、1発航あたりの操作回数が多い運用ではこの目安は短くなります。ですから、機体そのものの限界事項ではなく、レリーズという装備品の整備上の期限として管理されている数字だ、という整理になります。",
 s:"あります。発航回数で2,000回です。飛行規程には回数の定めはなく、2,000回と書かれているのは耐空検査準備作業報告書の装備品の表です。もとをたどると、メーカーが定める戻しばねの寿命10,000回の操作を、1発航5回で割った数字です。",
 rel:["装備品の使用期限はどのように管理していますか。", "グライダーの定期交換部品（いわゆるカレンダー部品）には"],
 hint:"「発航回数で2,000回」と即答できているか。出典が飛行規程ではなく耐空検査準備作業報告書の装備品表であることを区別できているか。操作回数10,000回はメーカーが定める数字であること、この2,000回との関係まで言えると加点。"},

{cat:"aircraft", imp:1, examiner:["nonaka"],
 q:"レリーズの使用回数制限について、2,000回と10,000回はそれぞれ何を指しますか。",
 a:"10,000回が操作回数、2,000回が発航回数です。10,000回はメーカーであるTOSTが定めている数字で、この2つは別々の制限ではなく、10,000回のほうが本体、2,000回はそれを現場で数えやすい形に直したものです。レリーズの寿命を決めているのは中の戻しばねで、その寿命がおよそ10,000回の操作とされています。ところが1回飛ぶあいだにばねが何回動くかは、レリーズハンドルを何回引いたかで決まります。通常の運用では1発航あたりおよそ5回操作するので、10,000割る5で2,000発航。これがオーバーホールまでの目安として定められている数字です。ですから場周を繰り返す訓練のように操作が多くなる運用では、2,000という数字は短くなります。1発航あたり8回引く運用なら10,000割る8で1,250発航、逆に2回で済むなら5,000発航という関係です。JA20HCの耐空検査準備作業報告書に記載があるのは2,000回のほうで、飛行機曳航用のTOST E75もウインチ曳航用のTOST G73も2,000回です。",
 s:"10,000回が操作回数、2,000回が発航回数です。10,000回はメーカー（TOST）が定めている数字で、寿命を決めているのはレリーズの中の戻しばねです。通常は1発航あたり5回ほど操作するので、10,000割る5で2,000発航という目安になっています。操作が多い訓練運用では、この2,000は短くなります。",
 rel:["レリーズの使用回数には制限がありますか。", "装備品の使用期限はどのように管理していますか。"],
 note:"操作回数10,000回（戻しばねの寿命）と、1発航あたり約5回という換算は、レリーズの製造元TOSTの技術資料による。JA20HCの書類に記載があるのは2,000回のほうだけ。",
 hint:"10,000回＝操作回数（戻しばねの寿命、メーカーTOSTが定める数字）、2,000回＝発航回数、という区別ができているか。2,000は10,000を1発航5回で割った換算値で、操作が多い運用では短くなる、という関係まで言えると加点。"},

{cat:"aircraft", imp:1, examiner:["nonaka"],
 q:"グライダーの定期交換部品（いわゆるカレンダー部品）にはどのようなものがありますか。",
 a:"飛行時間や使用回数に関わらず、設置・製造からの経過年数（暦月・暦年寿命）によって定期交換が義務付けられている部品のことです。シートベルトやゴム・樹脂系の部品、一部のホースやシール類などが該当します。",
 hint:"時間・回数ではなく経過年数（暦月・暦年寿命）で交換が決まる部品、という定義が言えているか。"},

{cat:"aircraft", imp:2, examiner:["nonaka","higuchi","yuda"],
 q:"速度計のマーキングについて説明してください。97ktや黄色い三角の印は何を意味しますか。",
 a:"速度計には常用運用範囲を示す緑色弧線、警戒範囲を示す黄色弧線、超過禁止速度の赤色放射線、推奨最小進入速度の黄色三角があります。飛行規程2-1では、緑色弧線が43から97kt、黄色弧線が97から151ktです。97ktは運動速度VAにあたり、緑と黄の境目になります。舵面をフルに操作しても機体に過大な荷重をかけない上限の速度で、ここから上は慎重に操舵します。黄色い三角の印は推奨最小進入速度の48.5kt、90km/hです。",
 rel:["速度計の常用運用範囲（緑の弧線）の下限", "ASK21の速度限界にはどのようなものが", "悪気流とは何ですか", "加速度計（Gメーター）の標識について"],
 hint:"97kt＝運動速度（VA）であること、黄色三角＝推奨最小進入速度であることの両方に触れているか。"},

{cat:"aircraft", imp:1, examiner:["sakai"],
 q:"Gメーター（加速度計）は曲技以外の飛行でも必要ですか。針が動いていない計器があった場合、何が考えられますか。",
 a:"曲技飛行以外では必須ではありません。ASK21の飛行規程では、通常飛行の最少装備品にGメーターは含まれておらず、曲技飛行を行う場合の追加装備品として、前席のGメーター、前後席のフロアハーネス、前後席のラダーペダルストラップ、パラシュートの4つが指定されています。したがってGメーターとボトムストラップが装備されていない状態では、プラカードのとおり曲技飛行は禁止で、耐空類別U（実用）としての運用になります。装備されていれば荷重倍数の目安として活用できます。指示が動いていない場合は故障が考えられます。",
 s:"曲技飛行以外では必須ではありません。通常飛行の最少装備品には含まれず、曲技飛行を行う場合の追加装備品として、Gメーター、フロアハーネス、ラダーペダルストラップ、パラシュートの4つが指定されています。針が動いていなければ故障が考えられます。",
 rel:["この機体（ASK21）の荷重制限（制限荷重倍数）", "曲技飛行を行うために追加で必要な装備品"],
 hint:"「曲技以外では必須でない」と言い切ったうえで、曲技時の追加装備品4つ、およびGメーター有無でプラカードの表示（U類／A類）が変わることに触れられているか。"},

{cat:"aircraft", imp:2, examiner:["sakai","konno"],
 q:"この機体（ASK21）の荷重制限（制限荷重倍数）について説明してください。",
 a:"飛行規程では3つの状態について定められています。運動速度VAにおいてプラス6.5、マイナス4.0。超過禁止速度VNEにおいてプラス5.3、マイナス3.0。エアブレーキ展開時はプラス3.5で、マイナス側はゼロです。VAまでは、どれだけ舵をいっぱいに使っても制限荷重倍数に達する前に失速してしまうため、この値に達することはありません。VAを超えると大きく舵を使ったときに達し得るので、VAが制限荷重倍数を使い切れる最大の速度になります。",
 s:"3つの状態で定められています。運動速度VAでプラス6.5、マイナス4.0。超過禁止速度VNEでプラス5.3、マイナス3.0。エアブレーキ展開時はプラス3.5で、マイナス側はゼロです。VAまでは舵をいっぱいに使っても先に失速するので、この値に達することはありません。",
 rel:["ASK21の速度限界にはどのようなものがありますか。", "加速度計（Gメーター）の標識について説明してください。"],
 hint:"VAで+6.5/−4.0、VNEで+5.3/−3.0、エアブレーキ展開時+3.5/±0という3つが言えているか。VAまでは先に失速するため制限荷重倍数に達しない、という理由が説明できているか。"},

{cat:"aircraft", imp:2, examiner:["konno","higuchi","yuda"],
 q:"ASK21の速度限界にはどのようなものがありますか。",
 a:"超過禁止速度VNEは151kt、悪気流速度VRAは108kt、運動速度VAは97kt、最大航空機曳航速度VTは97kt、最大ウインチ曳航速度VWは81ktです。",
 hint:"VNE151・VRA108・VA97・VT97・VW81（kt）という数値がおおむね正確に言えているか。"},

{cat:"aircraft", imp:1, examiner:["konno","yuda"],
 q:"重量限界にはどのようなものがありますか。",
 a:"ASK21では4つあります。最大離陸重量600kg、揚力発生部を除いた部分の最大重量410kg、操縦席の搭載重量として前席は最小70kg・最大110kg、後席は最大110kg、そして翼根部の荷物室が左右それぞれ最大10kgです。前席に最小重量があるのは、軽すぎると重心が後方に寄りすぎるためで、足りない分は固定バラストで補います。",
 s:"4つです。最大離陸重量600kg、揚力発生部を除いた部分の最大重量410kg、操縦席の搭載重量が前席は最小70kg・最大110kg、後席は最大110kg、そして翼根部の荷物室が左右それぞれ最大10kgです。",
 rel:["「揚力発生部を除いた部分の最大重量410kg」", "固定バラストの重量とアーム（モーメント）の関係"],
 hint:"最大離陸重量600kg、揚力発生部を除いた最大重量410kg、座席の最小・最大重量の3系統が言えているか。"},

{cat:"aircraft", imp:1, examiner:["konno"],
 q:"アドバースヨーとは何ですか。なぜ起こりますか。防ぐにはどうすればよいですか。",
 a:"エルロンを操作した際に、下がる側の翼の誘導抗力が増えることで、旋回方向と逆向きに機首が振られる現象です。ラダーを適切に使って釣り合いを取ることで防ぐことができます。",
 hint:"下げ翼側の抗力増加が原因であること、ラダーで補正するという対策の両方に触れているか。"},

{cat:"aircraft", imp:2, examiner:["konno"],
 q:"最小沈下速度と最良滑空比速度の違い、使い分けを説明してください。",
 a:"最小沈下速度は単位時間あたりの高度損失が最も少ない速度で、滞空時間を伸ばしたいときに使います。最良滑空比速度は一定の高度から最も遠くまで飛べる速度で、距離を稼ぎたいときに使います。",
 hint:"それぞれの定義（滞空重視／距離重視）と使い分けの目的が言えているか。"},

{cat:"aircraft", imp:1, examiner:["konno"],
 q:"地上でグライダーを移動させる際に注意することは何ですか。経験の浅い人にやらせない方がよい作業はありますか。",
 a:"地上でグライダーを移動させる際は、機体が大きく繊細なため、事故や損傷を防ぐための注意が必要です。主な注意点は、①十分な人員の確保（翼端、機首または尾輪、指揮者の3〜4名）、②風向きへの警戒（追い風・横風では機体が浮き上がったり反転したりする危険があるため、常に風上側の翼を低く保つ）、③キャノピーを閉めてロックする、④速度は人が歩く速度（微速）に保つ、⑤翼端が滑走路標識や他機、フェンス等に接触しないよう周囲を見張ることです。経験の浅い人に単独で任せるべきではない作業としては、車両での牽引の運転・リリースのタイミングの判断、強風時の風上側翼端の保持、尾部の持ち上げや方向転換の指揮、機体の組み立て・解体（リギング・デリギング）の主操作が挙げられます。いずれも判断を誤ると機体の損傷や重大事故につながるため、経験者や資格者が担当し、初心者は補助的な役割にとどめます。",
 s:"機体が大きく繊細なため、①十分な人員の確保、②風向きへの警戒（風上側の翼を低く保つ）、③キャノピーのロック、④歩く速度での移動、⑤周囲の障害物の見張りが注意点です。車両での牽引運転、強風時の風上側翼端保持、尾部の方向転換の指揮、組み立て・解体の主操作は、経験の浅い人には任せず経験者が担当します。",
 hint:"人員確保・風向き・キャノピーロック・速度・周囲確認の5点のいずれかに触れているか。牽引運転・強風時の翼端保持・方向転換の指揮・組み立て解体は経験者が担当すべき、と言えているか。"},

// ── 気象・身体 ──────────────────────────────────────────────
{cat:"weather", imp:3, examiner:["nonaka","sakai","konno"],
 q:"低酸素症（ハイポキシア）とは何ですか。どのような高度から、どのような症状が出ますか。",
 a:"低酸素症（ハイポキシア）とは、高高度で気圧が下がることで体や脳に十分な酸素が行き渡らなくなり、精神的・身体的な機能が低下する状態です。長時間飛行や夜間飛行では10,000ft程度から影響が出始め、12,000〜15,000ftになると判断力・記憶力・計算能力などがはっきり低下し、頭痛・眠気・めまいなども起こります。15,000ftを超えるとより早く深刻な症状や操縦ミスの危険が生じます。初期には気分の高揚（多幸感）を覚えることもあり、本人が酸欠に気づきにくいのが特徴です。進行すると視野の狭窄やチアノーゼ、意識の喪失に至ることもあります。確実な防止策は、早めの酸素マスクの使用と、10,000ft以下への降下です。",
 s:"高高度で酸素が不足し、判断力などの機能が低下する状態です。10,000ft程度から影響が出始め、12,000〜15,000ftではっきり低下し、頭痛・眠気なども起こります。初期は多幸感を覚えることもあり自覚しにくいのが特徴で、防止策は早めの酸素マスク使用と10,000ft以下への降下です。",
 hint:"10,000ft程度から影響が出始め、12,000〜15,000ftではっきり低下するという高度感覚、自覚しにくい（初期は多幸感）という特徴、酸素マスクと10,000ft以下への降下という対策の3点に触れているか。"},

{cat:"weather", imp:1, examiner:["sakai"],
 q:"チアノーゼはどのように確認しますか。",
 a:"チアノーゼとは、血液中の酸素が不足して、皮膚や粘膜が青紫色に変色する状態のことです。確認には2つの方法があります。1つは目視で、唇や舌、爪先や指先などの皮膚や粘膜が青紫色に変わっていないかを見ます。もう1つはパルスオキシメーターで、酸素飽和度（SpO2）を数値で確認します。目視の際は、唇や舌、口腔粘膜が青紫色になる中心性チアノーゼと、爪先や指先、耳たぶが紫っぽくなる末梢性チアノーゼを区別することが大切です。中心性チアノーゼは体全体で酸素が不足している重症度の高いサインですが、末梢性チアノーゼは寒さや血流の悪さによるもので、手を温めて色が戻るようなら一時的な冷えの可能性があります。",
 s:"血液中の酸素が不足して皮膚や粘膜が青紫色に変色する状態です。唇や舌、爪先や指先などの変色を目視で確認します。唇や舌が青紫色になる中心性チアノーゼは重症度が高いサインで、爪先や指先など末梢性チアノーゼは寒さによる一時的なものの場合もあります。",
 hint:"チアノーゼが血液中の酸素不足による皮膚・粘膜の青紫色変化であるという定義、目視（唇・舌・爪先・指先の変色）とパルスオキシメーターでのSpO2測定という2つの確認方法、中心性チアノーゼ（重症）と末梢性チアノーゼ（寒さによる一時的なもの）の区別のいずれかに触れているか。"},

{cat:"weather", imp:1, examiner:["sakai"],
 q:"パルスオキシメータはどのような仕組みで何を測定していますか。",
 a:"指先などに光を当て、血液（ヘモグロビン）による光の吸収の違いを利用して、動脈血の酸素飽和度（SpO2）を測定しています。",
 hint:"光の吸収の違いを利用して酸素飽和度を測る、という仕組みに触れているか。"},

{cat:"weather", imp:1, examiner:["sakai"],
 q:"錯覚にはどのようなものがありますか。滑走路の幅や無物標地帯、疑似水平線について説明してください。",
 a:"滑走路の幅が通常より広い、または狭いと、実際の高度を誤って知覚しやすくなります。無物標地帯（目標物のない地形）の上空では距離感や高度感がつかみにくくなります。傾いた雲の層などを水平線と錯覚する疑似水平線の錯覚もあります。",
 hint:"滑走路幅・無物標地帯・疑似水平線という3種類の錯覚の内容が言えているか。"},

{cat:"weather", imp:2, examiner:["konno"],
 q:"低体温症とはどのような状態ですか。気温が低くなるとパイロットにどのような影響がありますか。",
 a:"低体温症とは、寒冷な環境で体温が奪われ、直腸温などの中心体温が35℃以下に低下した状態です。進行度によって症状が変わります。軽度（32〜35℃）では激しい震えが起き、認知・判断力が低下して計器チェックの漏れや他機の見落とし、操縦操作のミスが増えます。中等度（28〜32℃）になると震えが止まって筋肉が硬直し、強い眠気や意識の混濁が起こり、無線交信もできなくなります。重度（28℃以下）では意識を失い、操縦不能や心肺停止に至ります。パイロットにとって特に危険なのは、脳の機能低下によって自分の判断力が落ちていること自体に気づけなくなる「自覚の遅れ」です。上空で激しい震えや操作の鈍さを感じたら低体温症の初期サインなので、無理をせず早めに高度を下げて暖かい地表へ戻る、また事前に防風・防寒着を重ね着するなどの対策が必要です。",
 s:"寒冷な環境で中心体温が下がり、震え・判断力低下から始まって、進行すると意識障害や心肺停止にまで至る状態です。恐ろしいのは、判断力の低下自体に自分で気づけなくなることです。震えや操作の鈍さを感じたら早めに高度を下げ、防寒対策を徹底します。",
 hint:"中心体温35℃以下という定義、軽度・中等度・重度の3段階（震え→硬直・意識混濁→意識喪失）、自分では判断力低下に気づけない「自覚の遅れ」という危険性、早期降下・防寒対策という対処のいずれかに触れているか。"},

{cat:"weather", imp:2, examiner:["konno"],
 q:"視程には「飛行視程」と「卓越視程」がありますが、パイロットが実際の飛行判断に使うのはどちらですか。卓越視程とはどのように求めるものですか。",
 a:"パイロットが飛行中の可否判断に用いるのは飛行視程です。卓越視程（Prevailing Visibility）は、空港などの気象観測通報（METARなど）で使われる地上側のデータで、全方位の視程を観測しそのうち180°以上の範囲で見通せる最大の視程のことです。離着陸の判断や事前のフライトプラン作成の参考に用いられますが、滑空場でパイロット自身が飛行中に観測しているものではなく、あくまで地上での視程です。",
 s:"飛行中の判断に使うのは飛行視程です。卓越視程は、空港の気象観測通報（METARなど）で使われる地上側のデータで、全方位を観測して180度以上の範囲で見通せる最大の視程です。離着陸の判断や事前のフライトプラン作成の参考に用いられます。",
 hint:"「飛行視程」と「卓越視程」を混同せず、飛行中の判断には飛行視程を使うと明確に言えているか。卓越視程は地上側のデータで、離着陸判断やフライトプラン作成の参考に使われる点も言えると加点。"},

{cat:"weather", imp:1, examiner:["konno","higuchi"],
 q:"雨の中を飛行してもよいのですか。注意することは何ですか。",
 a:"飛行そのものは可能です。ASK21の飛行規程では、雨中の飛行は非常操作の章の3-3に定められています。主翼への水滴の付着、軽微な氷結、昆虫の付着等は飛行特性には殆ど影響を与えないが、飛行性能の低下については考慮する必要がある、とされています。そのうえで安全マージンとして、着陸進入速度を約5kt（10km/h）だけ増加させることが求められています。",
 s:"飛行はできます。安全マージンとして、着陸進入速度を約5kt増やします。",
 rel:["降水（雨）の中でのフライトはなぜ避けるべきですか。", "視程には「飛行視程」と「卓越視程」が", "推奨進入速度は何ktですか。"],
 hint:"「飛行は可能」と言い切ったうえで、飛行特性ではなく飛行性能が落ちるという区別と、進入速度を約5kt（10km/h）増やすという具体的な数値が言えているか。"},

{cat:"weather", imp:1, examiner:["nonaka","konno"],
 q:"ソアリングにはどのような種類がありますか。サーマルが発生しやすい気象条件・場所の特徴は何ですか。",
 a:"ソアリングには主に4種類あります。1つ目がサーマルソアリングで、日射で温められた地表の空気が上昇する熱上昇気流を利用するもので、最も一般的です。2つ目がリッジ（斜面）ソアリングで、斜面に吹きつけた風が地形に沿って強制的に押し上げられる気流を利用し、山の風上斜面に沿って往復飛行します。3つ目がウェーブソアリングで、強い風が山脈を越えた風下側に発生する山岳波を利用し、成層圏近くまで達する高高度飛行に使われます。4つ目がコンバージェンスソアリングで、異なる方向から来た空気同士が衝突して上昇する気流を利用し、海風と陸風の境界（シアーライン）などで長い帯状の上昇気流ができます。サーマルが発生しやすい気象条件は、日射が強い晴天で、上空に冷たい空気が入って大気が不安定なとき、特に雨上がりの翌日の晴天は塵が洗い流されて日射が強く上空に寒気も残りやすいため強いサーマルが出やすくなります。ただし風が強すぎる（概ね5〜6m/s以上）とサーマルがちぎれて乗りにくくなります。場所としては、アスファルトや黒土、岩場など熱を吸収しやすい場所、周囲より乾燥した区域、日当たりの良い斜面、尾根の先端や山頂、森と畑の境界などの地形の境界線が、熱源やトリガーポイントとして狙い目になります。",
 s:"サーマル、リッジ、ウェーブ、コンバージェンスの4種類があります。サーマルは日射が強い晴天、特に雨上がりの翌日で上空に寒気が残る日に発生しやすく、風が強すぎるとちぎれてしまいます。場所は、アスファルトや黒土など熱を吸収しやすい所、乾燥した区域、日当たりの良い斜面、尾根や山頂、地形の境界線などが狙い目です。",
 hint:"サーマル・リッジ・ウェーブ・コンバージェンスの4種類とそれぞれの発生メカニズムのいずれかが言えているか。サーマル発生条件（日射・大気不安定・風が強すぎない）と、発生しやすい場所（熱源・乾燥地・斜面・尾根/山頂・地形境界）のいずれかに触れているか。"},

// ── 緊急処置 ──────────────────────────────────────────────
{cat:"emergency", imp:3, examiner:["nonaka","sakai"],
 q:"航空機曳航中、曳航索が切れました。あなたはどうしますか。",
 a:"滑走路に着陸できる高度・位置であれば、滑走路上空に戻ってから曳航索を離脱します。滑走路に戻れない場合は、地上をよく見て危険のない地点に索を落下させるように離脱し、不整地着陸を行います。",
 hint:"高度・位置に応じて「滑走路帰投」と「不整地着陸」を使い分ける判断が言えているか。"},

{cat:"emergency", imp:2, examiner:["sakai"],
 q:"上空で無線が故障したら、どのように対応しますか。",
 a:"まず一方送信を試み、応答がなければダウンウインドで翼を振るなどして自機の存在を周囲に知らせ、他機がいないことを確認しながら安全な間隔を保ってアプローチします。滑空場のローカルルールがあれば、それに従います。",
 hint:"一方送信の試行、翼を振るなどの合図、他機がいないことの確認という一連の対応が言えているか。"},

{cat:"emergency", imp:1, examiner:["sakai"],
 q:"飛行中にピトー管が虫などで詰まった場合、どうしますか。",
 a:"速度計の指示が信頼できなくなるため、ピッチ姿勢や舵の重さ、風切り音、景色の流れといった感覚的な目安を使って速度を判断します。安全マージンをとった高めの速度をキープしたまま、直ちに滑空場に戻り、ランディングパターンに入ります。",
 hint:"速度計に頼らず姿勢・風切り音などの代替手段で速度を判断する点、安全マージンをとった高めの速度を保って直ちに帰投する点が言えているか。"},

{cat:"emergency", imp:2, examiner:["nonaka"],
 q:"上空で高度計がスタック（固着）してしまったら、どうしますか。高度計が故障した場合の対処方法を説明してください。",
 a:"まず高度計自体を軽くたたいてみます。単に引っかかっているだけの可能性があるためです。それでも直らなければ、直ちに滑空場に戻ります。高度計の指示が信頼できない前提で、視覚的な目標物や場周経路上の目安高度、他の計器の情報と併せて高度を推測しながら、安全に着陸できるよう慎重に判断します。通常より余裕を持ったアプローチと接地を心がけます。",
 s:"まず高度計を軽くたたいてみます。引っかかっているだけの可能性があるためです。だめなら直ちに滑空場に戻り、視覚的な目標物や他の計器で高度を推測しながら、余裕を持ったアプローチと接地を心がけます。",
 hint:"まず高度計を軽くたたいて引っかかりを確認すること、だめなら直ちに滑空場に戻ること、視覚的な目安で高度を推測し余裕を持った接地を心がけることのいずれかに触れているか。"},

{cat:"emergency", imp:1, examiner:["sakai"],
 q:"バードストライク（鳥との衝突）が発生した場合の処置要領を説明してください。",
 a:"まず機体の状態と操縦性を確認し、異常があれば速やかに滑空場に着陸します。飛行後は機体の損傷を点検するとともに、必要に応じて関係機関への報告・届出を行います。",
 hint:"機体状態の確認、安全な着陸、点検・届出という一連の流れに触れているか。"},

{cat:"emergency", imp:3, examiner:["nonaka","sakai","konno","yuda"],
 q:"スピンはどのような状況で起こりやすいですか。回復要領を説明してください。",
 a:"第3・第4旋回（ベース・ファイナルレグ）でセンターラインを行き過ぎそうになり、低速のままラダーを踏み込みすぎて逆側にエルロンを切るクロスコントロールの状態になると、内側の翼が急激に失速してスピンに入りやすくなります。ASK21の飛行規程では回復要領は4段階です。1つ目、逆ラダーを踏む。2つ目、そのまま少し待つ。逆ラダーを約2分の1旋転の間維持します。待たないとかえって回復が遅くなります。3つ目、操縦桿に加えた力を抜き、旋転が止まるまでそのままにする。ここで前方いっぱいに操作すると、かえって回復が遅れるか妨げになります。4つ目、ラダーを中立に戻し、急降下姿勢から通常姿勢へ引き起こす。スピンが止まった直後は機首を下げた姿勢にあるので、そこからの引き起こしになります。スピンの開始から通常飛行姿勢の回復までに失う高度は約80m、約260ftです。なお飛行規程には、ASK21のスピンはピッチングを伴うが、機首を下げた深い姿勢のスピンからでも回復までには最大1旋転、機首下げが大きくない場合は1旋転以下で回復できる、とも書かれています。",
 s:"第3・第4旋回でセンターラインを行き過ぎそうになり、低速でラダーを踏み込みすぎて逆エルロンを切るクロスコントロールになると、内側の翼が急に失速してスピンに入りやすくなります。回復は4段階です。逆ラダーを踏む、約半旋転そのまま待つ、操縦桿の力を抜いて旋転が止まるまで待つ、ラダーを中立に戻して急降下姿勢から通常姿勢へ引き起こす。高度損失は約80m、260ftです。",
 rel:["重心位置が後方限界に近いと、スピンに入りやすくなりますか。", "ウィングドロップに遭遇したときの回復操作"],
 hint:"発生条件に加え、飛行規程の4段階（逆ラダー→約1/2旋転待つ→操縦桿の力を抜く→ラダー中立・急降下姿勢からの引き起こし）が順に言えているか。「待つ」と「桿を前いっぱいにしない」の2点は落としやすい。4段階目は「引き起こす」で止めず、急降下姿勢からの引き起こしだと言えるか。高度損失約80m（約260ft）まで言えれば十分。"},

{cat:"emergency", imp:1, examiner:["konno"],
 q:"トップラダーとは何ですか。トップラダーの状態から旋回は止まりますか。ラダーを戻さなかったらどうなりますか。",
 a:"トップラダーは旋回の内側と逆方向（旋回を止める方向）にラダーを踏みすぎている状態です。トップラダーをかけると旋回は止まりますが、そのままラダーを戻さずにいると、外側の翼が失速に近づき、二次失速に入るおそれがあります。",
 hint:"旋回を止める方向のラダー操作であること、戻さないと二次失速につながることの両方に触れているか。"},

{cat:"emergency", imp:2, examiner:["nonaka","yuda"],
 q:"重心位置が後方限界に近いと、スピンに入りやすくなりますか。",
 a:"はい。飛行規程では重心位置によって3段階に分けて書かれています。基準点後方315mmより前方であれば、ASK21はスピンに入ることはありません。複座で搭乗者が2名とも重い場合がこれにあたります。315mmを超えて320mmから385mmの間ではスピンに入りやすくなりますが、最大4回半の旋転で自然に回復します。複座で前席の重量が小さい場合です。400mmよりも後方ではスピンは回復操作を取らない限り持続しますが、操縦者により充分に制御できる範囲にあります。単座で搭乗者の重量が小さい場合です。",
 s:"はい。飛行規程では3段階に分けて書かれています。基準点後方315mmより前方ならスピンに入りません。320mmから385mmでは入りやすくなりますが、最大4回半の旋転で自然に回復します。400mmより後方では、回復操作を取らない限り持続します。",
 rel:["重心位置が前方限界の近くにあったら、スピンには入らない", "スピンはどのような状況で起こりやすいですか", "ASK21の許容重心位置範囲を答えてください。", "固定バラストの重量とアーム（モーメント）の関係"],
 hint:"「はい」と答えたうえで、315mm／320〜385mm／400mmという3段階と、それぞれがどんな搭乗形態にあたるかを説明できているか。"},

{cat:"emergency", imp:1, examiner:["konno"],
 q:"場周飛行の中で特に危険なポイントはどこですか。",
 a:"低高度で旋回半径や高度処理を誤りやすい第3〜第4旋回（ベースからファイナルへの旋回）が特に危険です。低高度は風の影響を受けやすく、過度な旋回操作は失速・スピンにつながるおそれがあります。",
 hint:"第3・第4旋回付近が特に危険であるという点に触れているか。"},

{cat:"emergency", imp:1, examiner:["sakai"],
 q:"背風（追い風）での着陸要領について説明してください。",
 a:"追い風では対地速度が上がり接地距離が伸びるため、通常より進入速度・接地点の設定に余裕を持ち、滑走距離が延びることを見込んで場周を計画します。",
 hint:"対地速度上昇・接地距離延伸を見込んだ余裕ある計画という点が言えているか。"},

// ── 飛行中の判断（坂井試験官特有：実際のフライト中に無線で問われる形式）───
{cat:"inflight", imp:2, examiner:["sakai"],
 q:"（実技中、曳航上昇中の低高度で）「いまここで曳航索が切れたらどうしますか」と聞かれました。何を基準に着陸先を判断しますか。",
 a:"高度と滑走路までの距離を瞬時に見積もり、滑走路に戻れなければ、進行方向の地形（川・空き地・田畑など）の中から障害物が少なく、着水・着陸しても被害が少ない場所を選びます。判断の理由（土手の広さ、木の有無など）まで説明できるようにしておきます。",
 hint:"高度・距離の見積もりと、具体的な地形選定理由（障害物の有無等）まで説明できているか。"},

{cat:"inflight", imp:1, examiner:["sakai"],
 q:"（実技中）「変電所の鉄塔の手前で索が切れたらどうしますか」と聞かれました。どう答えますか。",
 a:"鉄塔などの障害物を避けられる方向を選び、直進または緩旋回で、電線などの障害物を越えてから着陸できる広い場所（空き地など）に降ります。索は着陸前に離脱します。",
 hint:"障害物（鉄塔・電線）を避ける方向選びと、索を着陸前に離脱するという点に触れているか。"},

{cat:"inflight", imp:1, examiner:["sakai"],
 q:"（実技中、ベースレグで）「高さはどうですか」と聞かれました。高めだと感じた場合、どう答え、どう対応しますか。",
 a:"高めであっても調節の範囲内であればそのままアプローチを継続すると答え、ダイブブレーキの開度を通常より大きめに使うなどして降下角を調整し、安定した進入を維持します。",
 hint:"高さの自己評価（調節可能かどうか）と、ダイブブレーキ等での具体的な修正手段の両方に触れているか。"},

// ═══════════════════════════════════════════════════════════════════
// 追加分：報告書の質問をより網羅的にカバー（第2弾。上の74問と合わせて全体）
// ═══════════════════════════════════════════════════════════════════

// ── #1 2019.10.15／野中試験官／Mさん より ──────────────────────
{cat:"law", imp:1, examiner:["nonaka"],
 q:"最低安全高度について説明してください。",
 a:"人又は家屋の密集する地域の上空では、その航空機を中心として水平距離600m以内の最も高い障害物の上端から300mの高度、それ以外の地域では地表又は水面から150mの高度が最低安全高度です。ただし離着陸のための飛行はこの限りではありません。",
 hint:"人口密集地域は300m、それ以外は150mという2区分と、離着陸時は例外である点が言えているか。"},

{cat:"weather", imp:1, examiner:["nonaka"],
 q:"降水（雨）の中でのフライトはなぜ避けるべきですか。",
 a:"大きく2つ理由があります。1つは視程が悪化して他機や地形が見えにくくなること、もう1つは翼面が水滴で濡れて失速速度が上がり、安全余裕が小さくなることです。",
 s:"視程が悪化することと、翼面が濡れて失速速度が上がることの2つが理由です。",
 hint:"視程悪化と失速速度上昇の2点が言えているか。"},

{cat:"law", imp:1, examiner:["nonaka"],
 q:"O/L（アウトランディング）とはどのような状態ですか。どこに降りてもよいのですか。",
 a:"O/L（アウトランディング）とは、上昇気流が見つからず出発した飛行場に戻れなくなったグライダーが、飛行場以外の開けた安全な場所（畑や河川敷など）に着陸することです。クロスカントリー飛行では事故ではなく、日常的に起こり得る通常の運用の一部として扱われます。降りる場所は、法律上・安全上「航空機の着陸に安全で、かつ第三者に迷惑をかけない場所」であれば、原則として航空法違反にはなりません。航空法では航空機は原則として飛行場以外に離着陸してはならないと定められていますが、グライダーが高度を維持できなくなった場合は緊急やむを得ない措置として認められています。実務では、刈り取りが終わった平坦な畑・休耕田、広い河川敷や草地、他団体の滑空場や農道離着陸場などを選び、作物が育っている畑、電線・杭・溝・樹木がある場所、住宅地や道路、学校の校庭などは避けます。着陸後は、地主に事情を説明してお詫びをし、仲間がトレーラーで駆けつけて機体を分解・収納し、陸路で飛行場へ持ち帰ります。なお、滑走路を止まりきれずにはみ出す「オーバーラン」とは別の概念で、オーバーランは機体や滑走路設備を損壊する航空事故・重大インシデントとして扱われ、どこであっても認められません。",
 s:"O/L（アウトランディング）とは、上昇気流が見つからず飛行場に戻れなくなったグライダーが、畑や河川敷など飛行場以外の安全な場所に着陸することです。クロスカントリー飛行では事故ではなく通常の運用の一部とされ、着陸に安全で第三者に迷惑をかけない場所であれば航空法違反にはなりません。着陸後は地主にお詫びをし、仲間が機体を回収します。",
 hint:"O/L＝アウトランディング（場外着陸）であり、上昇気流が見つからず飛行場に戻れない場合に行う、クロスカントリー飛行における通常の運用の一部であるという点が言えているか。着陸場所の選定基準（安全・第三者への配慮）、着陸後の地主への対応と機体回収の流れ、「オーバーラン」とは別概念であることに触れられるか。"},

{cat:"law", imp:1, examiner:["nonaka"],
 q:"場外離着陸場とは何ですか。",
 a:"航空法第79条でいう「空港等」以外の場所で、大臣の許可を受けて離着陸に使う場所のことです。第79条は、航空機は空港等以外の場所で離陸・着陸してはならない、ただし国土交通大臣の許可を受けた場合はこの限りでない、と定めていて、このただし書の許可を受けた場所が場外離着陸場です。空港等というのは、空港その他の飛行場を指します。注意したいのは、滑空場だから場外離着陸場ではない、とは限らないことです。滝川も、曳航機のような飛行機にとっては、場外離着陸場としての許可があって初めて離着陸できる場所です。滑空機のほうは施行規則第172条で第79条の適用から除外されているので、そもそもこの許可の話になりません。つまり場外離着陸場かどうかは、場所の呼び名ではなく、その航空機にとって第79条の許可が要るかどうかで決まります。あわせて、緊急時の不整地着陸とは違い、あらかじめ手続きを経て計画的に使う場所である、という点も押さえておきます。",
 s:"航空法第79条でいう「空港等」（空港その他の飛行場）以外の場所で、国土交通大臣の許可を受けて離着陸に使う場所です。",
 rel:["飛行機（曳航機）は滝川滑空場に着陸してよいのですか。"],
 hint:"基準が「空港等（空港その他の飛行場）」であること、根拠が第79条ただし書の許可であることを言えているか。「滑空場以外」と答えてしまわないこと。滑空機は規則第172条で除外、滝川も曳航機にとっては場外離着陸場、まで言えると加点。"},

{cat:"airspace", imp:1, examiner:["nonaka"],
 q:"巡航高度とは何ですか。地上からの高さ（AGL）とQNH高度のどちらで表されますか。",
 a:"巡航高度とは、上昇を終えた航空機が目的地に向けて水平飛行を続けるときの高さのことです。全機が共通の基準で高度を保てるよう、QNH高度（高高度では標準気圧によるQNE）で表され、地上からの高さ（AGL）ではありません。AGLは離着陸時の目安として使われますが、巡航高度には使いません。",
 hint:"AGLとQNH/QNE基準の違いを区別できているか。共通の基準を保つためにQNH/QNEが使われる点、AGLは離着陸時の目安である点まで言えるか。"},

{cat:"airspace", imp:1, examiner:["nonaka"],
 q:"滑走路の末端に表示される標識（R/W標識）にはどのような情報がありますか。",
 a:"滑走路の末端に大きく書かれた2桁の数字（滑走路番号）は、進入方向から見た滑走路の磁方位（コンパスの方角）を表す数字で、磁北（0度）を基準に時計回りで測った角度を10分の1にし、1の位を四捨五入したものです。ほかに、必要に応じて中心線・着陸帯の境界を示す標識も表示され、パイロットは方位や着陸帯の範囲を確認できます。",
 s:"滑走路番号は、進入方向から見た滑走路の磁方位を10分の1にした2桁の数字です。",
 hint:"滑走路番号が磁方位を示す数字であることに触れているか。"},

{cat:"weather", imp:1, examiner:["nonaka"],
 q:"ウインドソック（吹き流し）で風速はどのように判断しますか。真横になったら何ノットの目安ですか。",
 a:"吹き流しの垂れ下がり方や向きから風向・風速の目安を読み取ります。一般的な目安として、吹き流しが真横まで水平になるのはおよそ15kt前後の風速とされています。",
 hint:"吹き流しの角度から風速を目安として読む、真横でおよそ15kt前後という目安の両方が言えているか。"},

{cat:"law", imp:1, examiner:["nonaka"],
 q:"フライトプランのオープン（開設通報）が飛行後にずれた場合、あるいは正しく伝わらなかった場合はどうなりますか。",
 a:"オープン通報（開設通報）がなくても、地上側ではフライトプランどおりに出発し、オープンしているものとして取り扱われます。したがって、実際の離陸が予定より遅れたり、オープン通報が正しく伝わっていない場合、パイロット本人は「まだ飛んだばかり」あるいは「まだ飛んでいない」と思っていても、地上では計画上の着陸予定時刻をもとに「もう着陸時間を過ぎているのに連絡がない」と判断され、致命的な認識のズレが生じます。オープンした際は、その通報が確実に相手に伝わったことを必ず確認することが重要です。",
 hint:"オープン通報がなくても地上側はオープン扱いになるという点、そのため出発の遅れや通報の不達がそのまま「連絡なき延着」という致命的な認識のズレにつながるという因果関係が言えているか。"},

{cat:"weather", imp:1, examiner:["nonaka"],
 q:"サーマルはどのように見つけますか。",
 a:"鳥やほかのグライダーの旋回、積雲の発生位置、地表の状態（乾いた地面や舗装面、日当たりの良い斜面）など、上昇気流が発生しやすい目印を手がかりに探します。バリオメーターの反応も重要な手がかりです。",
 hint:"視覚的な目印（鳥・雲・地表の状態）とバリオの反応の両方に触れているか。"},

{cat:"aircraft", imp:1, examiner:["nonaka"],
 q:"最小沈下速度は、バンク（旋回）を付けると変化しますか。",
 a:"はい。バンクを付けて旋回すると荷重倍数が増えるため、同じ揚力を得るのに必要な速度が上がり、最小沈下速度も直線飛行時より高くなります。",
 hint:"バンクによる荷重倍数の増加が最小沈下速度を上げるという関係が言えているか。"},

{cat:"emergency", imp:1, examiner:["nonaka"],
 q:"ウインチ曳航中、パイロットが索を離脱しなかった場合はどうなりますか。",
 a:"曳航索が一定の角度・張力に達すると、レリーズ機構の特性上、自然に離脱することがあります。ただし自然離脱に頼るのではなく、規定の離脱高度・角度で自ら意図的に離脱することが基本です。",
 hint:"自然離脱する可能性はあるが、自ら意図的に離脱するのが基本という点が言えているか。"},

{cat:"aircraft", imp:1, examiner:["nonaka"],
 q:"ダイブブレーキの上部にあるバネの役割は何ですか。",
 a:"ダイブブレーキ板を格納位置に確実に戻し、飛行中に不用意に開いてしまわないよう保持する役割があります。",
 hint:"格納位置への保持・不用意な展開の防止という役割が言えているか。"},

{cat:"airspace", imp:1, examiner:["sakai","higuchi"],
 q:"VFR（有視界飛行方式）で飛行する際に守るべきルールにはどのようなものがありますか。",
 a:"VMC（有視界気象状態）を維持すること、最低安全高度を守ること、視認と回避に努めることなどが基本です。",
 hint:"VMC維持・最低安全高度・視認と回避のいずれかに触れられているか。"},

{cat:"law", imp:2, examiner:["sakai"],
 q:"人又は家屋が密集している地域とは、具体的にどのような場所を指しますか。滝川周辺ではどこが該当しますか。",
 a:"都市部の市街地や住宅密集地など、人家が建て込んでいる区域を指します。滝川周辺では、滝川市街地と新十津川町の市街地がこれに該当します。密集地域上空では障害物の上端から300m、それ以外は地表から150mが最低安全高度となり、滝川市街地上空の下限高度は約1,300ftです。",
 hint:"密集地域上空の最低安全高度が300m基準になるという点、滝川周辺では滝川市街地と新十津川市街地の両方が該当することが言えているか。"},

{cat:"airspace", imp:1, examiner:["sakai"],
 q:"管制圏にあって情報圏にはないものは何ですか。",
 a:"管制圏にあって情報圏にはないものは、航空交通管制（ATC）による指示です。管制圏では管制官が配置され、離着陸の順序・時機・飛行経路などについて指示（管制）が行われます。情報圏には管制官がおらず、管制は行われません。飛行場対空援助業務（レディオなど）として、運航に必要な情報の提供や連絡受付のみが行われます。",
 hint:"「航空交通管制（ATC）による指示」の有無が違いであること、管制圏では離着陸の順序・時機・経路の指示（管制）が行われること、情報圏では飛行場対空援助業務による情報提供・連絡受付にとどまることが言えているか。"},

{cat:"airspace", imp:1, examiner:["sakai"],
 q:"滝川滑空場と新千歳空港のような大規模空港とでは、運用上どのような違いがありますか。",
 a:"新千歳のような大規模空港では、管制官が常駐しレーダーですべての航空機の間隔・着陸順序を厳格に指示する管制空港で、無線指示に従うことが絶対条件です。滝川のような滑空場は、管制官による強制力のある指示がない非管制飛行場（場外離着陸場）で、運用者が無線で気象情報や他機の位置をサポート（フライトサービス）しますが、最終的な回避や着陸の判断はパイロット自身の見張りに委ねられます。",
 s:"新千歳は管制官が常駐し無線指示に従う管制空港ですが、滝川は非管制飛行場で、最終的な判断はパイロット自身の見張りに委ねられます。",
 hint:"新千歳は管制官常駐で無線指示が絶対、滝川は非管制でパイロット自身の見張りに委ねられる、という違いが言えているか。"},

{cat:"airspace", imp:1, examiner:["sakai"],
 q:"大きな（管制されている）空港に着陸する必要が生じた場合、どのように対応しますか。",
 a:"管制塔へVHFで緊急連絡し、グライダーであること、動力がなくやり直し（ゴーアラウンド）ができないこと、緊急状態であることを伝えて優先権を得ます。無線が通じない場合は、そのまま場周経路に入り、管制官のライトガン信号（緑色＝着陸許可）に従います。エアブレーキで降下率を調整し、確実に滑走路上へ着陸します。着陸後は自力で移動できないため、その場で救援（牽引車）を待ちます。着陸後は航空局への事実関係の報告と書類提出が必要です。",
 hint:"グライダーはやり直しができない一発勝負であることを踏まえた緊急連絡・優先権の要求、無線不通時のライトガン信号への対応、着陸後の救援待ちと航空局への報告義務、という流れが言えているか。"},

{cat:"aircraft", imp:1, examiner:["sakai"],
 q:"ASK21のT尾翼にはどのような特性がありますか。",
 a:"後流の影響を受けにくく安定した効きが得られる一方、深い失速（ディープストール）姿勢になった場合に昇降舵の効きが低下するリスクが指摘される形式でもあります。",
 hint:"後流の影響を受けにくいという利点と、ディープストール時のリスクの両方に触れているか。"},

{cat:"aircraft", imp:1, examiner:["sakai"],
 q:"この機体に搭載されているVHF無線機にはどのような特性がありますか。",
 a:"VHF電波は光と同じように直進する性質があるため、見通し線（Line of Sight）内でしか通信できないという特性があります。地平線の陰や高い山の裏側に入ると電波が届かなくなり、逆に機体の高度が高いほど見通し距離が伸びるので、より遠くの地上局や航空機と通信できるようになります。",
 s:"VHF電波は光のように直進するため、見通し線内でしか通信できず、高度が高いほど到達距離が伸びます。地平線や山の陰では届かなくなります。",
 rel:["無線機のバッテリーにはどのような特性がありますか。"],
 hint:"VHFが見通し線（Line of Sight）内でしか通信できないこと、その理由（電波が光のように直進する）、高度が高いほど到達距離が伸びる点が言えているか。"},

{cat:"aircraft", imp:2, examiner:["sakai","higuchi"],
 q:"実地試験で急旋回を実施する際の速度、および低速飛行の速度はどのように決めますか。",
 a:"どちらもその日の全備重量から自分で計算して決めます。急旋回は45度バンクで行いますが、バンクを付けると荷重倍数が増え、その分だけ失速速度が上がるので、そこから逆算します。まず飛行規程の失速速度40ktは最大全備重量600kgでの値なので、実際の全備重量555kgに換算します。失速速度は重量の平方根に比例するので、40kt掛けるルート555割る600で約38.5kt。次に45度バンクの荷重倍数は1割るコサイン45度で1.41、失速速度はその平方根の1.19倍になるので、38.5kt掛ける1.19で約46kt。最後に失速させない余裕として5パーセントを見て約48kt。実際には約50ktで実施し、許容差はプラスマイナス10ktです。低速飛行は同じ考え方から、バンクの分だけがない形になります。555kgに換算した38.5ktに5パーセントの余裕を見て、開始時は約40ktにセットし、課目が終わったら約50ktに戻します。許容差はプラス5kt、マイナス3ktで、失速、つまりバフェットを起こさない範囲に収めます。なお50ktは飛行規程4-9の推奨進入速度であって、最小沈下速度ではありません。最小沈下速度はポーラー曲線から読むと約40から43ktです。いずれも数値そのものより、事前に自分で計算し、宣言してから実施するという手順が見られています。",
 s:"その日の全備重量から自分で計算して決めます。急旋回は45度バンクなので荷重倍数が1.41、失速速度はその平方根の1.19倍になります。全備重量555kgに換算した失速速度38.5ktに1.19を掛けて約46kt、さらに5パーセントの余裕を見て約48kt。実際には約50ktで実施し、許容差はプラスマイナス10ktです。低速飛行はバンクの分がないので、38.5ktに5パーセントを見て開始時約40kt、終了後は約50ktに戻します。許容差はプラス5kt、マイナス3ktです。",
 rel:["低速飛行（操縦可能な最小速度）は何ノットで行いますか。", "最小沈下速度と最良滑空比速度の違い", "最小沈下速度は、バンク（旋回）を付けると変化しますか。"],
 hint:"「45度バンクで荷重倍数1.41、失速速度はその平方根の1.19倍」という決め方を説明できているか。急旋回 約50kt（±10kt）、低速飛行は開始 約40kt・終了 約50kt（＋5kt／−3kt）という数値が言えているか。50ktを「最小沈下速度」と説明してしまわないこと。50ktは推奨進入速度で、最小沈下速度は約40〜43ktです。"},

{cat:"aircraft", imp:1, examiner:["sakai"],
 q:"場周経路のベースレグでの高度の目安はどのように判断しますか。",
 a:"滑走路末端からの距離と現在高度の関係、風の影響、その後のファイナルターンとアプローチに必要な高度を考慮し、経験的な目安高度とパス角を合わせて判断します。",
 hint:"距離と高度の関係、見え方の角度を目安に判断するという点が言えているか。"},

{cat:"aircraft", imp:2, examiner:["sakai"],
 q:"最良滑空比速度は、風や沈下率の状況に応じてどのように調整しますか。",
 a:"ASK21は49kt（90km/h）と55kt（100km/h）でほぼ滑空比が変わらないため、通常は増速しても損失の少ない55kt（100km/h）を目安にします。強い正対風や強い沈下があるときは60ktまで増速することもあります。逆に追い風や上昇気流の場合には、最小沈下速度に近づけます。速度は先にセットしてから「正対風が強いので、速度を55ktとしました」のように申告します。根拠を聞かれたら、ポーラーカーブ（速度性能曲線）を踏まえてこの程度の増速が合理的である、という趣旨で説明します。",
 s:"ASK21は49ktと55ktでほぼ滑空比が変わらないので、通常は増速しても損の少ない55ktを目安にします。強い正対風や強い沈下があるときは60ktまで増速します。追い風や上昇気流の場合には、最小沈下速度に近づけます。速度を先にセットし、「正対風が強いので55ktとしました」のように申告します。",
 rel:["最良滑空比速度の早見表は、どのように使いますか。"],
 hint:"55kt（100km/h）が基準、強風・強沈下時は60ktまでという具体的な数値、追い風や上昇気流の場合は最小沈下速度に近づけること、先にセットしてから申告する流れが言えているか。"},

{cat:"aircraft", imp:2, examiner:["yuda"],
 q:"最良滑空比速度の早見表は、どのように使いますか。どうやって作りましたか。",
 a:"縦に昇降計の指示、横に風を取った表です。全備重量550kgで計算してあります。読み方は、まず昇降計の指示から大気そのものの上下を知ります。ASK21の最小沈下は昇降計で1.7ノット相当なので、昇降計がマイナス1.7を指していれば大気は静穏、0を指していれば大気が1.7ノットで上昇している、という関係です。そのうえで正対風の成分を横に取ります。静穏無風なら51ノット。向かい風20ノットなら57ノット。沈む空気の中、大気沈降マイナス1.8で向かい風20ノットなら69ノットまで増速します。逆に追い風10ノットで静穏なら49ノットに落とします。作成にあたっては、櫻井さんのEMLT講座のグライダー性能計算ツール2にASK21の諸元を入力して計算しました。",
 s:"縦に昇降計の指示、横に風を取った表で、全備重量550kgで計算してあります。ASK21の最小沈下は昇降計で1.7ノット相当なので、昇降計がマイナス1.7を指していれば大気は静穏です。静穏無風で51ノット、向かい風20ノットで57ノット、追い風10ノットなら49ノットに落とします。",
 rel:["最良滑空比速度は、風や沈下率の状況に応じてどのように調整しますか。", "最小沈下速度と最良滑空比速度の違い"],
 hint:"昇降計の指示から大気の上下を読むという2段構えの理解ができているか。静穏無風51kt、向かい風20ktで57ktといった代表値を1つ以上挙げられるか。"},

{cat:"airspace", imp:1, examiner:["sakai"],
 q:"管制圏には無許可で進入できますか。管制承認（クリアランス）だけで進入できますか。",
 a:"管制圏には無許可で進入することはできません。また、単なる管制承認（クリアランス）だけで進入することもできません。管制機関からの明確な「進入の許可（Clearance / Permission）」が必要です。",
 hint:"無許可進入はできないこと、単なる管制承認だけでは不十分で、管制機関からの明確な「進入の許可」が必要であることの区別が言えているか。"},

{cat:"airspace", imp:1, examiner:["sakai"],
 q:"ローカルで飛行する際のトランスポンダーのスコークコードはどうしますか。他にどのような使い方がありますか。",
 a:"通常のVFR飛行では1200（10,000ft以上では1400）を使用します。管制機関から特定の識別のために個別のコード（ディスクリートコード）の指定を受けた場合はそれに従います。",
 s:"通常のVFR飛行では1200、10,000ft以上では1400です。管制機関から個別のコードの指定を受けた場合はそれに従います。",
 rel:["トランスポンダーはどのような時に使用しますか"],
 hint:"通常は1200／1400、指定があればディスクリートコードに従うという点が言えているか。"},

{cat:"airspace", imp:1, examiner:["sakai"],
 q:"PCA（Positive Control Area）とはどのようなところですか。",
 a:"航空交通が非常に混雑する空港周辺やその進入経路上に設定された、原則としてVFR（有視界飛行方式）での飛行が禁止されている空域です。",
 hint:"空港周辺・進入経路上に設定された空域であること、原則としてVFRでの飛行が禁止されている点が言えているか。"},

{cat:"airspace", imp:1, examiner:["sakai"],
 q:"飛行中に「不確実の段階」になり得る具体的な状況にはどのようなものがありますか。",
 a:"位置通報や運航状態通報の予定時刻から30分以上経過しても連絡が取れない場合（山岳地帯で地形に電波を遮られ、定時連絡が30分以上遅れる場合など）、目的地や着陸予定地への到着予定時刻（ETA）を30分以上過ぎても到着しない場合（上昇気流が弱く向かい風も強くて帰投が遅れ、無線の不具合で報告できていない場合など）、が挙げられます。",
 s:"1. 通信途絶・定時連絡の途絶（30分以上の超過）。2. 予定到着時刻の30分以上の遅延。",
 hint:"通信途絶（定時連絡の30分以上の超過）と到着予定時刻の30分以上の遅延という2類型が挙げられているか。グライダーに即した具体例（山岳地帯での電波遮蔽、サーマル不足による帰投遅れ）まで言えると加点。"},

{cat:"aircraft", imp:1, examiner:["sakai"],
 q:"飛行機には速度制限がありますが、滑空機にも同様の速度制限はありますか。",
 a:"滑空機にも、機体の飛行規程で定められた運動速度（VA）や超過禁止速度（VNE）などの速度限界があります。管制圏内での一律の速度制限は飛行機ほど明確ではありませんが、機体の速度限界と安全な操縦速度を守る必要があります。",
 hint:"滑空機にも機体固有の速度限界（VA・VNEなど）があるという点が言えているか。"},

{cat:"aircraft", imp:1, examiner:["sakai"],
 q:"無線機のバッテリーにはどのような特性がありますか。良否はどのように確認しますか。何ボルトくらいあればよいですか。",
 a:"リチウムイオン電池です。無線機操作要領の写真が13.1V、同じ資料の画面図が12.9Vを示していますが、鉛蓄電池は満充電で休ませても12.7V程度なので、この電圧は12V級のリチウムイオン電池のものです。特性は4つ挙げます。1つ目が放電カーブが平坦なこと。容量の大半を13V前後のまま使うので電圧から残量が読めず、終わりに近づくと急に落ちます。だから飛行前に必ず電圧を見ますし、JA20HCは2個積んで、コックピットの切替スイッチで切り替えられるようにしています。2つ目が低温に弱いこと。寒いと容量も出力も落ちます。放電はできますが、氷点下での充電は電池を傷めるので避けます。3つ目が自己放電が小さく、メモリー効果がないこと。置いておいても減りにくく、継ぎ足し充電もできます。4つ目が専用の充電器が要ること。鉛蓄電池用の充電器で充電してはいけません。良否は無線機の電圧表示で確認します。BeckerのAR4201はMDEボタンで画面が3つ切り替わり、その1画面目に周波数と並べて電圧が出ます。健全なら13V前後で、12V台まで下がっていたら終わりが近いと見て、交換するか充電します。",
 s:"リチウムイオン電池です。低温では容量も出力も落ちます。自己放電が小さく、メモリー効果もありません。12V仕様のシステムであれば、満充電時で約12.5V〜13.8V、使用限界（カットオフ電圧）は約10.5V〜11.0V程度です。安全に運用するためには、フライト前に11.5V〜12.0V以上あることが望ましいです。電圧がこれより低いと、送信（マイクを押した瞬間）に電圧降下が起き、無線機が正常に動作しなくなる恐れがあります。良否は無線機のMDEボタンで切り替えた1画面目の電圧表示で見ます。2個積んでいるので、切替スイッチで両方を確認します。",
 hint:"リチウムイオン電池と答えられているか。鉛蓄電池と言ってしまわないこと。放電カーブが平坦で電圧から残量が読めない、低温で落ちる、の2点は落とさない。「無線機の画面（MDEの1画面目）で読む」「13V前後」、2個積んで切替できることまで言えると加点。"},

{cat:"airspace", imp:1, examiner:["sakai"],
 q:"付近の空港のレーダー管制施設とは、状況によって無線でコンタクトできますか。イニシャルコンタクトの周波数は何ですか。",
 a:"周波数と管轄範囲が合致していれば交信できます。滝川周辺は主に札幌アプローチ（札幌レーダー）と千歳アプローチ（千歳レーダー）の管轄です。イニシャルコンタクトの周波数は、札幌アプローチが119.225MHz、千歳アプローチが120.10MHzです。管轄外や電波の到達範囲外では交信できないこともあります。",
 s:"周波数と管轄範囲が合致していれば交信できます。札幌アプローチが119.225MHz、千歳アプローチが120.10MHzです。",
 rel:["大きな（管制されている）空港に着陸する必要が生じた場合"],
 hint:"条件が合えば交信可能だが管轄・到達範囲の制約がある点。加えて札幌アプローチ・千歳アプローチの周波数を1つ以上挙げられるか。"},

{cat:"aircraft", imp:1, examiner:["sakai"],
 q:"実地試験で実施する代表的な操作課目にはどのようなものがありますか。",
 a:"着陸形態・進入形態での失速とその回復、低速飛行、急旋回、最良滑空比速度での飛行、指定地着陸などが代表的な課目です。",
 hint:"失速・低速飛行・急旋回・最良滑空比速度・指定地着陸のうち複数が挙げられているか。"},

{cat:"emergency", imp:1, examiner:["sakai"],
 q:"曳航前の打ち合わせで確認しておくべきエマージェンシー項目にはどのようなものがありますか。",
 a:"離陸滑走中のトラブル、曳航機の吊り上げ・見失い（ロスト）、曳航機のエンジン故障、離脱不能の4点は、曳航前に必ず確認しておくべき代表的なエマージェンシー項目です。",
 hint:"離陸滑走中トラブル・曳航機のロスト・曳航機のエンジン故障・離脱不能の4点のうち複数が言えているか。"},

{cat:"law", imp:1, examiner:["sakai"],
 q:"飛行中にバードストライク（鳥との衝突）が発生した場合、届出は必要ですか。",
 a:"必要です。国土交通省航空局への届出（報告）義務があります。対象は、空港内での駐機・地上走行・離着陸滑走中、空港周辺での上昇・降下・進入中、そして福岡飛行情報区（FIR）内での航行中に発生したバードストライクです。福岡FIRは名称によらず日本全土をカバーする唯一のFIRなので、滝川もこの対象に含まれます。報告の時期は、航空機の著しい損傷や飛行計画の変更を伴うような重大な場合はできるだけ速やかに、それ以外の軽微な衝突やニアミス（衝突のおそれ）は月単位でまとめて翌月10日までに報告します。",
 s:"必要です。国土交通省航空局への報告義務があります。重大な場合（機体の著しい損傷や飛行計画変更を伴う場合）はできるだけ速やかに、軽微な場合は月単位でまとめて翌月10日までに報告します。",
 hint:"報告先（国土交通省航空局）、重大／軽微による報告時期の違い（速やか／翌月10日まで）に触れられるか。報告対象の場面（空港内・空港周辺・福岡FIR内）まで言えると加点。"},

{cat:"emergency", imp:3, examiner:["sakai"],
 q:"失速からの回復操作を行う際、エルロン（補助翼）の使用について特に注意すべき点は何ですか。",
 a:"失速からの回復は、エルロンではなくエレベーター（昇降舵）とラダー（方向舵）を主に使用します。まずは何よりも最優先で操縦桿を前に押し、迎え角を小さくして翼の気流を回復（失速を解除）させます。失速中に機体が傾いた場合は、エルロンではなくラダーを反対側に踏んで傾きを修正します。操縦桿を押し、速度が十分に回復（風切り音が戻り、舵に手応えが戻る）したことを確認してから、初めてエルロンを使って水平飛行に戻します。",
 s:"失速回復はエルロンではなくエレベーターとラダーが中心です。まず操縦桿を前に押して迎え角を小さくし、傾きが出たらラダーで修正します。速度が十分に回復してから、初めてエルロンで水平飛行に戻します。",
 hint:"操縦桿を前に押して迎え角を小さくすることを最優先とすること、傾きの修正はエルロンではなくラダーで行うこと、速度が十分に回復してから初めてエルロンを使うという順序に触れているか。"},

{cat:"aircraft", imp:1, examiner:["sakai"],
 q:"急旋回に入る前に確認しておくべきことは何ですか。",
 a:"旋回方向の安全（クリアー）確認、速度、バンク角の目安、そして旋回中も前方の景色の見え方でピッチ姿勢を維持することを意識します。",
 hint:"クリアー確認と、前方の景色でピッチ姿勢を維持する意識の両方に触れているか。"},

{cat:"aircraft", imp:1, examiner:["sakai"],
 q:"科目と科目の間に実施すべき3点チェックとは何ですか。",
 a:"ポジション（自機位置）チェック、高度チェック、速度チェックの3点です。旋回前後のクリアー確認とあわせて、落ち着いて安全にフライトを続けるために科目の合間に行います。",
 hint:"ポジション・高度・速度の3点チェックが挙げられているか。"},

// ── #4 2022.10.11-13／野中試験官／今野さん・加藤さん・佐々木さん より ──
{cat:"airspace", imp:1, examiner:["nonaka"],
 q:"滑空場によっては、VHF以外にどのような無線機が使われていますか。",
 a:"HF（短波）無線機が使用されることもあります。追加で装備する場合は、無線局免許の内容変更として総務省（地方総合通信局）から認可を受ける必要があります。",
 hint:"HF無線機を使う滑空場もあるという点、追加装備には認可が必要という点に触れているか。"},

{cat:"aircraft", imp:1, examiner:["nonaka"],
 q:"ASK21はどのくらいの高度まで上昇できますか。",
 a:"上昇できる高度は、その時の気象条件（上昇気流の強さ）や空域の法的規制、搭乗員の酸素装備の有無によって決定されます。上昇前には酸素やトランスポンダーの準備が必要です。",
 hint:"気象条件（上昇気流の強さ）、空域の法的規制、酸素装備の有無という3つの要因が言えているか。"},

{cat:"weather", imp:1, examiner:["nonaka"],
 q:"山岳波（ウェーブ）ではどのくらいの高度まで上昇することがありますか。",
 a:"条件がそろえば、通常のサーマルソアリングでは到達しにくい30000ftを超えるような高高度まで上昇することがあり、その場合は酸素装備や耐寒対策、トランスポンダー等の装備がより重要になります。",
 hint:"サーマルより高い高度に到達し得ること、装備の重要性が増す点に触れているか。"},

{cat:"weather", imp:1, examiner:["nonaka"],
 q:"高度を上げていく上で問題になるのは酸素だけですか。",
 a:"酸素以外にも、気温低下による低体温症のリスク、必要な装備（トランスポンダー・無線）の要否、減圧による身体への影響などが問題になり得ます。",
 hint:"酸素以外の要因（低体温症・装備要件など）に触れているか。"},

{cat:"emergency", imp:1, examiner:["nonaka"],
 q:"救急用具には具体的にどのようなものが積まれていますか。期限はどう管理していますか。",
 a:"JA20HCに積んでいるのは3つです。非常用信号灯（信号弾）。救急箱。そして携帯灯です。期限の管理は保安装備品点検表で行っていて、点検年月日ごとに各品目の状態を記録し、点検者が押印します。信号弾はメーカーの指定期限があり、現在積んでいるものは2028年8月までです。点検日は2026年7月31日でした。なお救急用具の点検期限そのものの規定は2026年3月の改正で撤廃され、メーカー指定の手順によることになりましたが、実務上は当面60日を目安に運用しています。",
 s:"3つです。非常用信号灯（信号弾）、救急箱、そして携帯灯。期限は保安装備品点検表で管理していて、いま積んでいる信号弾はメーカー指定で2028年8月まで、点検日は2026年7月31日でした。",
 rel:["グライダーの定期交換部品（いわゆるカレンダー部品）には", "装備品の使用期限はどのように管理していますか。"],
 hint:"信号弾・救急箱・携帯灯の3つが挙げられているか。保安装備品点検表で管理していると言えるか。"},

{cat:"aircraft", imp:1, examiner:["nonaka"],
 q:"滑空機のU類・A類とはそれぞれどのような分類ですか。",
 a:"航空法施行規則の附属書第一に定義があります。滑空機 実用Uは、普通の飛行のほかに、強度に制限を設けた上で特定の曲技飛行（宙返り、失速旋回、急旋回、錐揉み、レージーエイト、シャンデル）に適するものです。滑空機 曲技Aは、普通の飛行に加え、制限なくあらゆる曲技飛行（アクロバット飛行）に適する強度を持つものです。いずれも最大離陸重量750kg以下が対象です。つまり曲技Aは曲技飛行そのものに適するのに対し、実用Uは特定の曲技飛行に限られる、という差になります。JA20HCの耐空類別は耐空証明書と運用限界等指定書のとおり滑空機 実用Uです。",
 s:"航空法施行規則の附属書第一の定義で、どちらも750kg以下。実用Uは普通の飛行に加え、強度に制限を設けた上で特定の曲技飛行（宙返り、失速旋回、急旋回、錐揉み、レージーエイト、シャンデル）に適するもの、曲技Aは普通の飛行に加え制限なくあらゆる曲技飛行に適する強度を持つものです。JA20HCは実用Uです。",
 hint:"根拠が航空法施行規則の附属書第一だと言えるか。曲技Aは制限なくあらゆる曲技飛行に適する強度、実用Uは強度に制限を設けた特定の曲技飛行に限られる、という差で説明できているか。JA20HCが実用Uだと即答できるか。"},

{cat:"aircraft", imp:1, examiner:["nonaka"],
 q:"キャノピー（風防）の取り扱いで注意することは何ですか。",
 a:"開閉時に無理な力をかけない、ロックを確実にかける、地上で強風時に不用意に開けない、といった点に注意します。飛行前点検でロック機構が確実に機能するかを確認します。",
 hint:"ロックの確実な確認、強風時の取り扱い注意のいずれかに触れているか。"},

{cat:"aircraft", imp:1, examiner:["nonaka"],
 q:"ヒューズの点検では具体的に何を確認しますか。",
 a:"確認する項目は3つです。1つ目は機体への適合性で、飛行規程で定められた適正な破断強度（通常は全備重量の約1.3倍）のものが使われているか、また強度ごとに色分け（赤、青、黒など）されているため、機種に適合した正しい色のヒューズが装着されているかを目視等で確認します。2つ目は損傷や変形の有無で、ヒューズ本体に変形、亀裂、破損、過度な摩耗がないか、また規定の枚数のヒューズが完全な状態で取り付けられているかを確認します。3つ目は取付状態で、曳航索やシャックル、リング等の正しい位置に確実に装着されているか、緩みや不具合がないかを確認します。",
 s:"機体への適合性（規定の破断強度・色の一致）、損傷や変形の有無（亀裂・破損・摩耗、規定枚数）、取付状態（曳航索やシャックル等への確実な装着）の3点を確認します。",
 rel:["ウインチ曳航（WT）のヒューズはなぜ2枚ついていますか。"],
 hint:"機体への適合性（破断強度・色）、損傷や変形の有無、取付状態の3系統に分けて説明できているか。"},

{cat:"aircraft", imp:1, examiner:["nonaka","yuda"],
 q:"曳航中の合図にはどのようなものがありますか。",
 a:"翼を振る、ラダーを振るといった目視合図と、無線での通話による合図があります。曳航機側からの合図は、離脱高度になったら翼を振る、です。滑空機側から曳航機へ出す合図で押さえておきたいのは、曳航機の左側にずれてから翼を振る、という動きです。これは離脱できない、つまりレリーズ不良を知らせるスタンダードシグナルで、曳航機はこれを見たら飛行場へ引き返し、安全な高度で切り離すことになります。逆に、離脱そのものを要求する合図はありません。離脱は滑空機側の判断でいつでもできるので、要求する必要がないからです。予定より早く離脱する場合は、無線で知らせてから離脱します。無線が使えない場合に備え、どの合図が何を意味するかを曳航前の打ち合わせで必ずすり合わせておきます。",
 s:"目視の合図と無線の合図があります。曳航機側は、離脱高度になったら翼を振ります。滑空機側で押さえておきたいのは、曳航機の左側に出てから翼を振ると離脱できないという意味になることです。離脱そのものを要求する合図はありません。離脱は自分の判断でできるからです。どの動きが何を意味するかは、曳航前の打ち合わせで必ずすり合わせます。",
 rel:["曳航中に最大曳航速度を超えそうになりました。", "速度超過の合図を出したいが無線が通じません。"],
 hint:"翼を振るなどの視覚合図と無線合図の両方に触れているか。滑空機が左側に出て翼を振る＝離脱不能、を挙げられているか。離脱は自分の判断でできるので離脱を要求する合図はない、と整理できていると加点。事前の打ち合わせが前提であることに触れられているか。"},

{cat:"aircraft", imp:1, examiner:["nonaka"],
 q:"毛糸（ヨーストリング）がずれている場合、どのように直しますか。",
 a:"ラダーとエルロンを適切に使って機体の釣り合い（横滑りの有無）を修正し、毛糸がまっすぐ後方を向く状態に戻します。",
 hint:"ラダー・エルロン操作で釣り合いを修正するという点が言えているか。"},

{cat:"departure", imp:1, examiner:["nonaka"],
 q:"ドローンが飛行しているという情報はどこから入手できますか。",
 a:"NOTAMから確認できます。趣味用の小型ドローンの飛行は必ずしも事前に把握できるとは限らないため、目視での警戒も重要です。",
 hint:"NOTAMという情報源に加え、目視警戒の重要性にも触れているか。"},

{cat:"weather", imp:1, examiner:["nonaka"],
 q:"視程1,500mというと、実際にはどれくらいの見え方ですか。",
 a:"1,500m先にある目立つ物標（山や建物など）がぼんやりとでも識別できる程度の見え方です。それより近い距離しか見えない場合はVMC基準を満たしません。",
 s:"1,500m先にある目立つ物標（山や建物など）がぼんやりとでも識別できる程度の見え方です。",
 hint:"具体的な距離感（1,500m先の物標が識別できる程度）で説明できているか。"},

{cat:"airspace", imp:1, examiner:["nonaka"],
 q:"進入管制区や管制区はどのような目的で設定されていますか。",
 a:"航空交通量の多い空域で、計器飛行方式の航空機を中心に管制間隔を確保し、安全な交通整理を行うために設定されています。",
 hint:"交通整理・管制間隔の確保という目的が言えているか。"},

{cat:"airspace", imp:1, examiner:["nonaka"],
 q:"着陸帯に設置される「かぎ型」の標識にはどのような意味がありますか。",
 a:"着陸帯（滑走路）の四隅（コーナー）を示す境界標識です。標識より手前に着陸してはいけません。",
 hint:"着陸帯の四隅を示す境界標識であること、標識より手前に着陸してはいけないという点が言えているか。"},

{cat:"law", imp:1, examiner:["nonaka"],
 q:"捜索救難活動を取り仕切る機関はどこですか。",
 a:"救難調整本部（RCC）が取り仕切ります。国内では東京空港事務所内に設置されています。",
 hint:"RCC（救難調整本部）が取り仕切るという点が言えているか。"},

{cat:"aircraft", imp:1, examiner:["nonaka"],
 q:"高度1,000ftから、ASK21の最良滑空比で飛行するとおよそどのくらいの距離を飛行できますか。",
 a:"ASK21の最良滑空比はおよそ34から36程度とされています。1,000フィートは約300メートルですから、無風で大気に上下がないと仮定すれば、300に34から36を掛けて、およそ10.2kmから10.8km。つまり10km前後まで飛行できる計算になります。滝川でいえば、9km圏内の端までがちょうど1,000ftぶんの滑空、という感覚です。実際には風や沈む空気の影響でこれより短くなりますし、着陸のための高度も残さなければならないので、余裕を見て考えます。",
 s:"およそ10kmです。",
 rel:["最良滑空比速度は、風や沈下率の状況に応じてどのように調整しますか。", "滝川滑空場では、何m以上が航空交通管制区になりますか。"],
 hint:"滑空比×高度で概算距離を求める考え方が示せているか。1,000ft＝約300mの換算ができ、10km前後という数値が出せるか。"},

{cat:"emergency", imp:1, examiner:["nonaka"],
 q:"有視界飛行中に誤って雲の中に入ってしまった場合、どうなりますか。どう対応しますか。",
 a:"視界を失い、姿勢や方位を見誤って空間識失調に陥る危険があります。気づいた時点で速やかに旋回するなどして雲から出る方向へ操作し、計器があれば姿勢維持に活用します。",
 hint:"空間識失調の危険性と、速やかに雲から出る対応の両方に触れているか。"},

{cat:"emergency", imp:1, examiner:["nonaka"],
 q:"航法でロストポジション（自機位置を見失うこと）になった場合、どのように対処しますか。",
 a:"落ち着いて高度を確保し、目立つ地形・目標物を探して現在位置を推定します。必要であれば無線で地上や他機に状況を伝え、支援を求めます。",
 hint:"落ち着いて地形を手がかりに位置を推定する対応、必要に応じ無線で支援を求める点に触れているか。"},

{cat:"emergency", imp:1, examiner:["nonaka"],
 q:"飛行中に静圧口が塞がれてしまった場合、高度計や速度計の指示はどうなりますか。",
 a:"静圧の変化が計器に伝わらなくなるため、高度計は塞がれた時点の高度付近から動かなくなり、速度計の指示も実際の速度と乖離して不正確になります。",
 hint:"高度計が動かなくなること、速度計の指示が不正確になることの両方に触れているか。"},

{cat:"lookout", imp:1, examiner:["konno"],
 q:"航空法で衝突予防について規定している考え方は、何を重視していますか。",
 a:"航空機同士の見張り義務や進路権のルールを定め、動力を用いない航空機を優先するなど、パイロット自身の警戒と譲り合いによって衝突を未然に防ぐことを重視しています。",
 hint:"見張り義務・進路権のルールにより衝突を未然に防ぐという考え方が言えているか。"},

{cat:"airspace", imp:1, examiner:["konno"],
 q:"動力滑空機（モーターグライダー）は、飛行機・回転翼航空機と優先順位は同じですか。",
 a:"はい。進路権の順位では、飛行機・回転翼航空機・動力滑空機は同じ4番（最下位）の区分です。この区分内で正面から接近する場合は互いに右へ避ける、追い越しは前の機体の右側を通過する、といったルールに従います。",
 hint:"動力滑空機が飛行機・回転翼と同じ区分（4番）であること、区分内では右側優先などのルールに従う点が言えているか。"},

{cat:"aircraft", imp:2, examiner:["konno"],
 q:"航空機曳航を行う基準にはどのようなものがありますか。必要な人員や打ち合わせ内容は何ですか。",
 a:"航空法施行規則第195条により定められています。基準としては、曳航索の長さは40m以上80m以下とし、離脱高度は原則としてその曳航索の長さの80%相当以上に達してから離脱すること、雲中飛行および夜間の曳航は行わないこととされています。必要な人員は、機内の連絡員（2人以上搭乗できる機体の場合。無線通信ができれば省略可）、離陸時に緊密な連絡を援助する地上連絡員、曳航索の離脱を航空機へ確実に連絡する地上の離脱確認・連絡員です。事前の打ち合わせでは、合図とその意味、出発及び曳航の方法、曳航索の離脱の時期・場所・方法、その他気象状況や周辺の他機情報などの必要事項を確認します。",
 s:"航空法施行規則第195条により、曳航索の長さは40〜80m、離脱高度は曳航索長さの80%相当以上、雲中・夜間曳航は禁止と定められています。人員は機内連絡員（無線があれば省略可）、地上連絡員、地上の離脱確認・連絡員です。事前打ち合わせでは、合図の意味、出発・曳航の方法、離脱の時期・場所・方法、気象や周辺他機情報などを確認します。",
 hint:"根拠条文（施行規則第195条）、曳航索の長さ（40〜80m）と離脱高度（索長の80%以上）、雲中・夜間曳航の禁止、必要な人員（機内連絡員・地上連絡員・離脱確認連絡員）、打ち合わせ項目（合図・出発と曳航の方法・離脱の時期場所方法・その他）のいずれかに具体的に触れられているか。"},

{cat:"weather", imp:1, examiner:["konno"],
 q:"秋から冬にかけて、ウェーブで高高度まで上昇する際に特に注意すべきことは何ですか。",
 a:"秋から冬の高高度では気温が低いため、低体温症対策や酸素・トランスポンダーなどの装備確認、重装備の防寒対策（血流確保）がより重要になります。また、低温によりキャノピーが霜や曇りで見えにくくなることがあるため、その対策も必要です。",
 s:"気温の低さによる低体温症対策、重装備の防寒対策（血流確保）、酸素やトランスポンダーの装備確認に加え、キャノピーの霜・曇り対策も必要です。",
 hint:"低体温症・防寒対策（血流確保）・酸素装備の重要性、キャノピーの霜・曇り対策のいずれかに触れているか。"},

{cat:"weather", imp:1, examiner:["konno"],
 q:"サーマル内を飛行する際は、どのような操作・注意が必要ですか。",
 a:"サーマルの中心付近で旋回を続けることで最大の上昇率を得られるため、上昇率の変化を見ながら旋回半径や位置を微調整します。他機がいる場合は衝突を避けるための見張りと決められた旋回方向の遵守が必要です。また、風下に流されすぎると戻れなくなったり、山肌のローターなど危険空域に巻き込まれたりするため、常に自機の位置を意識する必要があります。",
 hint:"中心付近を捉える旋回、他機との見張り・旋回方向遵守、風下への流されすぎへの注意のいずれかに触れているか。"},

{cat:"departure", imp:3, examiner:["nonaka","sakai","konno"],
 q:"機長の出発前確認事項（航空法第73条の2）の項目をすべて述べてください。",
 a:"6項目あります。1.当該航空機及びこれに装備すべきものの整備状況、2.離陸重量・着陸重量・重心位置及び重量分布、3.航空法第99条第1項により国土交通大臣が提供する航空情報、4.当該航行に必要な気象情報、5.燃料及び滑油の搭載量及びその品質（上級滑空機には該当しません）、6.積載物の安全性です。この確認が終わるのは、曳航前のコントロールフリーチェックの時点です。実務としては、書類は搭載義務の有無や有効期限を、航空情報はノータムなど飛行に影響する情報を、気象情報は出発地・目的地・経路上の現況と予報を確認します。特に気象情報は「現況」を具体的に述べられるようにしておく必要があります。",
 s:"6項目です。整備状況、離陸重量・着陸重量・重心位置及び重量分布、国土交通大臣が提供する航空情報、気象情報、燃料及び滑油の量と質、積載物の安全性。上級滑空機に燃料の項目は該当しません。実務では、書類は搭載義務の有無や有効期限、航空情報はノータムなど、気象情報は出発地・目的地・経路上の現況と予報を確認します。",
 hint:"6項目（整備状況・重量重心・航空情報・気象情報・燃料滑油・積載物の安全性）がすべて挙げられているか。燃料滑油は滑空機には該当しない点、気象情報は「現況」を具体的に述べる必要がある点にも触れられるとよい。"},

{cat:"departure", imp:1, examiner:["konno"],
 q:"滑空機は、備え付けが義務付けられている書類を機体に搭載しなくてもよいのですか。",
 a:"航空機登録証明書、耐空証明書などの備付書類は、滑空機については行動半径が小さいことなどから搭載が免除されています。ただし飛行中は自己の管理下に置いておく必要があります。",
 hint:"搭載は免除されるが、自己管理下に置く必要があるという点の両方が言えているか。"},

{cat:"departure", imp:1, examiner:["konno"],
 q:"航空情報にはどのような種類があり、どのように更新されますか。",
 a:"NOTAM（ノータム）、AIP（航空路誌）などがあり、変更や制限が生じた際に随時発行・更新されます。パイロットは飛行前に最新の航空情報を確認する必要があります。",
 hint:"NOTAM・AIPなど代表的な種類、随時更新されるため飛行前確認が必要という点に触れているか。"},

{cat:"weather", imp:1, examiner:["konno"],
 q:"高層天気図（Soundings）の赤い線と青い線はそれぞれ何を表していますか。2本の線が接近・接触している状態はどういう状態を示しますか。",
 a:"一般に赤い線が気温、青い線が露点温度を表し、両者の差を湿数と呼びます。2本の線が接近・接触している状態は、その高度の大気が非常に湿っている、または飽和していることを示し、間隔が離れている高度は空気が乾燥していることを示します。グライダーの飛行では主に3つの判断材料になります。1つ目は雲やガス（霧）の発生で、線が接触している高度では雲の層やガスが形成されている可能性が高いことを示します。2つ目はサーマルトップ（雲底高度）の予測で、地上の空気が上昇していく際に赤い線と青い線が最も接近・交差する高度が雲底高度の目安になり、グライダーで上昇できる限界高度を把握する重要な手がかりになります。3つ目は視程悪化のリスクで、低い高度で線が接近・接触していると、地上付近で霧やもやが発生し視程が悪化する可能性を示します。タスクを計画する際は、線がほどよく離れて視界が良く、ある高度で少し接近して良い積雲ができるような状態が理想的なコンディションとされます。",
 s:"赤い線が気温、青い線が露点温度で、差を湿数と呼びます。線が接近・接触していると大気が湿っている（雲やガスの発生）ことを、離れていると乾燥していることを示します。グライダーでは、線が最も接近する高度がサーマルトップ（雲底高度）の目安になり、上昇できる限界高度の判断材料になります。低い高度で線が接触していれば、視程悪化のリスクも示します。",
 hint:"赤＝気温、青＝露点温度、両者の差が湿数であるという対応関係、線の接近・接触は雲やガスの発生を示すという点、線が最も接近する高度がサーマルトップ（雲底高度）の目安になるという点のいずれかに触れているか。"},

{cat:"law", imp:1, examiner:["konno"],
 q:"航空法はなぜ必要なのですか。",
 a:"根拠は航空法第1条の目的規定です。同条は大きく3つの柱を掲げています。1つ目は国際民間航空条約（シカゴ条約）とその附属書が定める標準・方式・手続に準拠すること、2つ目は航空機の航行の安全を確保し、事故や障害を防止すること、3つ目は利用者の利便を増進することです。これらを通じて航空の発達を図り、公共の福祉を増進するのが航空法の目的です。法規を知らずに飛行することは、自分自身だけでなく周囲の安全も脅かすことになります。",
 s:"航空法第1条の目的規定に基づき、国際法（シカゴ条約）への準拠、航空機の航行の安全確保、利用者の利便の増進の3つを図るために必要です。",
 hint:"航空法第1条の3本柱（国際法準拠・安全確保・利用者の利便）を挙げられるか。"},

// ── #6 2026.8.8／日口教官の模擬オーラル より ─────────────────
// 注：出典は模擬オーラルの記録。当日「割愛」となった質問のうち、既存の設問で
//     カバーできるものは新規に起こさず、上の該当設問に higuchi タグを付けている。

{cat:"airspace", imp:2, examiner:["higuchi"],
 q:"航空交通管制区とは何ですか。",
 a:"航空法第2条の定義に定められた空域で、地表または水面から200m以上の高さの空域のうち、航空交通の安全のために国土交通大臣が告示で指定したものをいいます。実際の下限高度は場所ごとに告示で決められており、どこでも200mというわけではありません。主な目的は、高高度を飛行する航空機や計器飛行方式（IFR）の航空機の交通整理を行い、安全で円滑な運航を維持することです。管制区内を飛行する航空機は、管制機関と常時連絡を取り、指示に従う必要があります。管制圏のように飛行場を中心とした円柱状の空域ではなく、航空路を保護するために広い範囲に設定される点が、管制圏との違いです。グライダーも航空機として扱われるため、管制区内を飛行する場合や高度10,000ft以上に達する場合は、無線機やトランスポンダーの搭載が求められます。また航空法第92条により、管制区・管制圏内では技能証明を持たない練習生が単独で操縦練習飛行を行うことは原則として禁止されています。管制区内はレーダー誘導のIFR機が多数飛んでいるため、VFRで飛ぶグライダーとの接近を避けるための飛行情報の共有やトランスポンダーによる位置表示が特に重視されます。",
 s:"航空法第2条に定められた空域で、地表または水面から200m以上の高さの空域のうち、航空交通の安全のために国土交通大臣が告示で指定したものです。実際の下限は場所ごとに告示で決まっていて、どこでも200mというわけではありません。高高度・IFR機の交通整理が目的で、管制圏のような飛行場中心の円ではなく広範囲に設定されます。グライダーも航空機として扱われ、無線機・トランスポンダーの搭載義務や、技能証明のない練習生の単独練習飛行の禁止（航空法第92条）などの規制を受けます。",
 rel:["進入管制区や管制区はどのような目的で", "PCA（Positive Control Area）とは", "巡航高度とは何ですか。"],
 hint:"法第2条の定義であること、「200m以上の空域のうち告示で指定したもの」という骨格に加え、高高度・IFR機の交通整理という目的、管制圏との違い、グライダーにも適用される規制（無線機・トランスポンダーの搭載義務、92条による練習生の単独飛行禁止、IFR機との接近回避のための情報共有）まで言えているか。"},

{cat:"airspace", imp:3, examiner:["higuchi","yuda"],
 q:"滝川滑空場では、何m以上が航空交通管制区になりますか。",
 a:"300m以上です。滝川は札幌飛行場から20NM以上40NM以内の範囲にあたり、この区分では管制区の下限が300mとされているためです。したがって滝川では、高度300m未満はクラスGの空域、300m以上が管制区になります。VMCの基準も「クラスG・300m以下」と「管制区内」で切り替わるので、同じ300mという線で覚えておくと整理しやすくなります。",
 s:"300m以上です。滝川は札幌飛行場から20NM以上40NM以内にあたり、この区分では管制区の下限が300mとされているためです。",
 note:"出典はAIP ENR2.1-23（模擬オーラルで提示されたもの）。原典を直接確認できていません。ただし本問答集の「管制区と管制圏の違い」にある『空港から40NM以内では1,000ft』という記述（1,000ft≒300m）と一致しています。最新のAIPで距離区分と下限高度を確認してください。",
 rel:["クラスGの空域、高度300m以下でのVMC基準", "高度3,000m未満におけるVMCの気象条件を", "高度3,000m未満におけるVMCの気象条件"],
 hint:"「300m以上」と即答できるか。札幌飛行場からの距離区分という根拠に触れられるか。"},

{cat:"airspace", imp:2, examiner:["higuchi"],
 q:"管制区や管制圏を航行する上で、どのような装置が必要ですか。",
 a:"VHFが義務付けられています。根拠は航空法第60条で、具体的な装備の要件は施行規則第146条第1号に定められています。",
 rel:["滑空場によっては、VHF以外にどのような無線機", "この機体に搭載されているVHF無線機には", "上空で無線が故障したら"],
 hint:"「VHF」と答えられているか。法第60条→施行規則第146条という条文のたどり方が言えているか。"},

{cat:"airspace", imp:2, examiner:["higuchi"],
 q:"進入管制区を飛行する場合はどのような装置が必要ですか。トランスポンダーは必要ですか。",
 a:"有視界飛行方式であれば、VHF（無線電話）があれば飛行できます。根拠は航空法第60条→施行規則第146条第2号→告示第200号です。有視界飛行方式でトランスポンダーの装備が求められるのは、特別管制区と、管制区のうち高度10,000ft以上の空域に限られます。この10,000ftは、告示上は日本の計量法に合わせて「3,000m」と定められていますが、航空の実務では国際標準であるフィート表記が使われるため、換算した「10,000ft」という基準で広く運用されています。進入管制区でトランスポンダーが必要になるのは計器飛行方式の場合です。",
 s:"有視界飛行方式なら、VHF、無線電話があれば飛行できます。トランスポンダーの装備が求められるのは、特別管制区と、管制区のうち10,000ft以上の空域に限られます。進入管制区でトランスポンダーが要るのは計器飛行方式の場合です。",
 note:"進入管制区に個別の除外空域があるかどうかを、告示第200号の原文で確認できていません。模擬オーラルでは「日高進入管制区を除く」との言及がありましたが、提示された告示の抜粋（除外されているのは旭川・大雪・十勝・霞目・富山・相馬原・霞ヶ浦・舞鶴・静浜の各管制圏）では確認できませんでした。日口教官に確認することを勧めます。",
 rel:["トランスポンダーはどのような時に使用しますか", "ローカルで飛行する際のトランスポンダーのスコークコード", "特別管制区（特管区）とは何ですか", "緊急事態が発生した場合、トランスポンダーは"],
 hint:"有視界飛行方式と計器飛行方式で要求が違うこと、VFRでトランスポンダーが要るのは特別管制区と10,000ft以上であることが整理できているか。"},

{cat:"law", imp:3, examiner:["higuchi"],
 q:"飛行機（曳航機）は滝川滑空場に着陸してよいのですか。",
 a:"航空法第79条により、航空機は空港等以外の場所で離陸・着陸してはならないと定められています。ただし国土交通大臣の許可を受けた場合はこの限りではありません。滑空機は施行規則第172条で第79条の適用から除外されているため、空港等以外でも離着陸できます。一方、曳航機のような飛行機には除外規定がないので、滝川のような滑空場に離着陸するには場外離着陸場としての許可が必要になります。美唄の機体などが滝川に降りられるのも、この許可があるためです。",
 s:"場外離着陸場としての許可があれば着陸できます。第79条で空港等以外での離着陸は禁止ですが、滑空機は施行規則第172条で除外されています。飛行機には除外がないので、大臣の許可が必要です。",
 rel:["場外離着陸場とは何ですか。", "O/L（アウトランディング）とはどのような状態ですか", "滝川滑空場と新千歳空港のような大規模空港とでは"],
 hint:"「滑空機は規則第172条で除外」「飛行機は第79条ただし書の許可が必要」という区別ができているか。"},

{cat:"aircraft", imp:3, examiner:["higuchi"],
 q:"飛行規程の第1章から第5章には、それぞれ何が書かれていますか。",
 a:"概要、限界事項（運用限界）、非常操作、通常操作、性能です。このほか別添として、三面図・装備品目表・重量重心計測記録・重心図表・主翼の固有振動数が付いています。",
 rel:["重量限界にはどのようなものがありますか。", "この機体（ASK21）の荷重制限", "ASK21の速度限界にはどのようなものがありますか。", "滑空機は、備え付けが義務付けられている書類"],
 hint:"5つの章を「概要・限界事項・非常操作・通常操作・性能」の順に並べられているか。"},

{cat:"emergency", imp:2, examiner:["higuchi"],
 q:"飛行規程の「非常操作」には、どのような項目が記載されていますか。",
 a:"ASK21では、スピンからの回復、キャノピーの投棄と緊急脱出、雨中飛行、ウイングドロップ、グランドループが記載されています。",
 rel:["スピンはどのような状況で起こりやすいですか", "キャノピー（風防）の取り扱いで注意することは", "失速からの回復操作を行う際、エルロン", "有視界飛行中に誤って雲の中に入ってしまった場合"],
 hint:"5項目のうち3つ以上を挙げられるか。特にスピンからの回復と緊急脱出。"},

{cat:"aircraft", imp:2, examiner:["higuchi","yuda"],
 q:"速度計の常用運用範囲（緑の弧線）の下限は、どのような速度ですか。",
 a:"最大重量における1.1Vs1、つまり失速速度の1.1倍です。単に「失速速度」と答えると誤りになります。根拠は耐空性審査要領7-3-3です。ASK21では43ktで、飛行規程2-1の速度計標識に、緑色弧線は43から97ktと書かれています。",
 s:"最大重量における失速速度の1.1倍です。根拠は耐空性審査要領7-3-3です。ASK21では43ktで、飛行規程に記載されています。",
 rel:["速度計のマーキングについて説明してください。", "ASK21の速度限界にはどのようなものがありますか。"],
 hint:"「失速速度」で止めず、「最大重量での1.1Vs1」と言えているか。ASK21では43ktと、ノットの数値でも答えられるか。"},

{cat:"aircraft", imp:1, examiner:["higuchi"],
 q:"推奨最小進入速度とは、どのような速度ですか。",
 a:"推奨最小進入速度とは、最終進入（滑走路への最終直線経路を飛行する段階）において、安全性を確保しつつ飛行できる最低限の対気速度として航空機製造者が指定した速度のことです。ASK21では、エアブレーキを開いた状態で運動操作を安全に行うことができる速度として、飛行規程2-1の標識表に48.5ktと定められており、速度計の黄色い三角の印がこの速度を示しています。実際の運用でいう推奨進入速度も飛行規程4-9で49ktとされており、ほぼ同じ速度です。",
 s:"最終進入において、安全性を確保しつつ飛行できる最低限の対気速度として航空機製造者が指定した速度です。ASK21ではエアブレーキを開いた状態で48.5ktとされ、速度計の黄色い三角の印がこの速度を示しています。",
 rel:["速度計のマーキングについて説明してください。", "推奨進入速度は何ktですか。"],
 hint:"「最終進入で安全に飛行できる最低限の対気速度として製造者が指定」という定義と、ASK21での48.5kt・速度計の黄色三角という具体が言えているか。"},

{cat:"aircraft", imp:1, examiner:["higuchi"],
 q:"運用様式限界とは何ですか。",
 a:"その機体でどのような様式の飛行を行ってよいかを定めた限界で、飛行規程の第2章 限界事項に記載されています。ASK21 JA20HCでは7つ挙げられています。計器航法による飛行以外の有視界飛行、昼間飛行、ウィンチ曳航、航空機曳航、自動車曳航、曲技飛行、そして3000m以上の高々度飛行です。裏返せば、計器飛行方式や夜間飛行は認められていません。高々度飛行については酸素の規定があり、3000mから4000mまでは飛行時間から30分を減じた時間分、4000mを超える場合は全飛行時間分の酸素が必要です。",
 s:"その機体でどのような様式の飛行を行ってよいかを定めた限界で、飛行規程 第2章にあります。ASK21では7つ、有視界飛行、昼間飛行、ウィンチ曳航、航空機曳航、自動車曳航、曲技飛行、3000m以上の高々度飛行です。裏返せば、計器飛行方式と夜間飛行は認められていません。",
 rel:["曲技飛行を行う上での基準には", "滑空機のU類・A類とは", "ASK21で認められている曲技の課目は何種類ありますか。"],
 hint:"7つの様式のうち大半を挙げられているか。特に「計器航法によらない有視界飛行」「昼間飛行」の2つと、3種類の曳航方式。高々度飛行の酸素の規定まで言えれば十分。"},

{cat:"airspace", imp:2, examiner:["higuchi"],
 q:"高高度を飛行する場合、どのような装備が必要ですか。",
 a:"酸素供給装置とトランスポンダーの2つで、どちらも法令の要求です。まず酸素です。航空法第62条に「凍結防止装置、外気温度計、酸素吸入装置、航法計器その他の国土交通省令で定める航空の安全のための特別の装置を装備する航空機でなければ、高高度飛行、雲中飛行その他の国土交通省令で定める特別の飛行を行つてはならない」とあり、酸素は法令上の要求です。飛行規程だけの話ではありません。必要な量は飛行規程2-3に書かれていて、高々度飛行とは3,000m以上の高度をいい、3,000mから4,000mまでは当該飛行にかかる飛行時間から30分を減じた飛行時間中に搭乗者が必要とする量、4,000mを超える高度では当該飛行にかかる時間中に搭乗者が必要とする量です。もうひとつがトランスポンダーで、こちらは航空法第60条から施行規則第146条第2号、そして国土交通大臣の告示で指定された空域、という順にたどります。管制区のうち高度10,000ft以上の空域などが指定されていて、そこを飛ぶならモードAまたはモード3で識別符号を、モードCで高度を応答できる装置が必要です。この10,000ftは、告示上は日本の計量法に合わせて「3,000m」と定められていますが、航空の実務では国際標準であるフィート表記が使われるため、換算した「10,000ft」という基準で広く運用されています。なおJA20HCは92条の許可が4,000ft MSL以下なので、実際にこの高度域を飛ぶことはありません。",
 s:"酸素供給装置とトランスポンダーの2つで、どちらも法令の要求です。酸素は航空法第62条の「航空の安全のための特別の装置」にあたり、量は飛行規程2-3に、3,000mから4,000mまでは飛行時間から30分を減じた時間分、4,000mを超えるなら全飛行時間分とあります。トランスポンダーは航空法第60条から施行規則第146条第2号、告示で指定された空域で、管制区の高度10,000ft以上などが該当します。",
 rel:["20,000ft以上を飛行する場合", "高度を上げていく上で問題になるのは酸素だけですか。", "山岳波（ウェーブ）ではどのくらいの高度まで"],
 hint:"酸素が飛行規程だけでなく航空法第62条の要求だと言えているか（「飛行規程で要求」とだけ答えると不足）。量の区切り（3,000〜4,000mは飛行時間マイナス30分、4,000m超は全時間）が言えるか。トランスポンダーは法60条→規則146条2号→告示、とたどれるか。"},

{cat:"weather", imp:1, examiner:["higuchi"],
 q:"酸素はいつから使用しますか。",
 a:"法規上の基準は、高度3,000m以上の飛行で酸素の使用が規定されています。ただし、パイロットのパフォーマンス維持や低酸素症（高度による酸欠状態）を防ぐためには、より低い高度から使用することが望ましく、安全性を考慮して10,000ft（約3,000m）未満の段階から使用が推奨されるケースもあります。",
 s:"法規上は高度3,000m以上で酸素の使用が規定されていますが、低酸素症を防ぐため、より低い高度、10,000ft（約3,000m）未満の段階から使用が推奨されるケースもあります。",
 rel:["低酸素症（ハイポキシア）とは何ですか", "チアノーゼはどのように確認しますか。", "パルスオキシメータはどのような仕組みで", "秋から冬にかけて、ウェーブで高高度まで"],
 hint:"法規上の基準（高度3,000m以上）と、低酸素症予防のためより低い高度から使用が推奨される場合があるという2点が言えているか。"},

{cat:"aircraft", imp:2, examiner:["higuchi"],
 q:"JA20HCの酸素装備について、容量と使用可能時間を教えてください。",
 a:"満タンで1,500psiです。高度15,000ftで使用した場合、約10から11時間分の酸素量があります。この酸素ボトルを2本搭載しています。",
 rel:["酸素はいつから使用しますか。", "高高度を飛行する場合、どのような装備が必要ですか。"],
 hint:"満タン1,500psi、15,000ftで約10〜11時間、ボトルを2本搭載している、の3点が言えているか。"},

{cat:"aircraft", imp:3, examiner:["higuchi"],
 q:"低速飛行（操縦可能な最小速度）は何ノットで行いますか。その速度はどのように決めますか。",
 a:"40ノットです。決め方は2段階です。まず飛行規程の失速速度40ktが最大全備重量600kgでの値であることを踏まえ、実際の全備重量550kgに換算します。失速速度は重量の平方根に比例するので、40kt×√(550÷600)＝約38ktとなります。次に、失速させないための余裕として5％を加え、38kt×1.05＝約40ktとします。数値そのものより、この2段階の計算を口頭で説明できることが重要です。",
 s:"40ktです。飛行規程の失速速度40ktは最大重量600kgでの値なので、実際の550kgへ重量の平方根で換算して約38kt、これに5％の余裕を足して約40ktとしています。",
 note:"5％の余裕（×1.05）の根拠となる規定は特定できていません。模擬オーラルの記録でも「なぜ1.05を掛けるのか」が宿題として残されています。失速余裕を確保して操縦可能な最小速度とするため、という理解でよいか日口教官に確認してください。",
 rel:["実地試験で急旋回を実施する際の速度", "最小沈下速度と最良滑空比速度の違い", "失速からの回復操作を行う際、エルロン"],
 hint:"「40ノット」だけで終わらず、重量換算（平方根）と5％の余裕という2段階の計算を説明できているか。"},
// ── 飛行規程（Fuka先生 講習・2026）──────────────────────────
{cat:"law", imp:2, examiner:["fuka"],
 q:"飛行規程承認書とは何ですか。誰が承認するものですか。",
 a:"その飛行規程が所定の手続きを踏んで作られ、現在有効であることを示す書面です。原則として国土交通大臣が承認しますが、実務においては耐空検査員が行います。JA20HCの飛行規程承認書は、承認日が平成14年4月19日、区分は個別・基本、承認事由は耐空証明の新規です。",
 s:"その飛行規程が所定の手続きを踏んで作られ、現在有効であることを示す書面です。原則として国土交通大臣が承認しますが、実務においては耐空検査員が行います。",
 rel:["飛行規程の第1章から第5章には", "耐空検査証（耐空証明）は誰が発行しますか。"],
 hint:"「所定の手続きを踏んだ有効な飛行規程であることの証明」であること、承認権者は原則国土交通大臣だが実務は耐空検査員が行うことの2点が言えているか。"},

{cat:"law", imp:1, examiner:["fuka"],
 q:"飛行規程の「頁一覧表」と「変更現況表」は何のためにありますか。",
 a:"頁一覧表と変更現況表は、その規程が最新かつ正しい状態であることを管理するためにあります。頁一覧表は各ページが最新版かを確認する一覧で、JA20HCでは本文1-1から5-2までが承認、別添1から5は対象外です。変更現況表は改訂履歴を記録するもので、JA20HCでは平成14年4月19日に新規検査による初版作成、とあります。",
 s:"頁一覧表は各ページが最新版かを確認するための一覧、変更現況表は改訂履歴の記録です。どちらも規程が最新かつ正しい状態であることを管理するためにあります。",
 rel:["飛行規程承認書とは何ですか。", "航空図（航空路図・チャート）が最新かどうかは"],
 hint:"頁一覧表＝各ページが最新版か確認するため、変更現況表＝改訂履歴の記録、という役割の違いが言えているか。全体の目的（規程が最新かつ正しい状態であることを管理するため）にも触れられるか。"},

{cat:"aircraft", imp:2, examiner:["fuka","yuda"],
 q:"ASK21の耐空類別は何ですか。装備によって変わりますか。",
 a:"滑空機 実用Uです。装備によって変わることはありません。根拠は耐空証明書 第2026-55-06号の4項の耐空類別欄と、運用限界等指定書の用途欄で、どちらも滑空機 実用Uと書かれています。耐空類別は航空法第10条第3項にもとづいて耐空証明のときに用途として指定されるものなので、Gメーターを付けたから今日はA、という切り替わり方はしません。紛らわしいのがコクピットのプラカードで、飛行規程2-6に2種類が定められています。Gメーターとボトムストラップがない状態では「曲技飛行禁止。耐空類別U（実用）としての装備」、ある状態では「飛行規程に従った曲技飛行が可能。耐空類別A（曲技）としての装備」です。ただし原文は Equipment as under airworthiness category A、つまり耐空類別Aに定める装備を備えている、という装備の状態を示すもので、この機体の耐空類別がAになるという意味ではありません。ASK21という型式がUとAの両方に対応しているので、プラカードが2枚用意されているということです。JA20HCには加速度計もボトムストラップも前後席に装備されているので、掲示されるのはA側になります。曲技飛行ができる根拠も耐空類別ではありません。運用限界等指定書の運用限界が飛行規程の第2章とされていて、その2-3の運用様式限界に曲技飛行が挙がっている、というたどり方になります。",
 s:"滑空機 実用Uです。装備では変わりません。",
 rel:["滑空機のU類・A類とは", "曲技飛行を行うために追加で必要な装備品は何ですか。"],
 note:"プラカードの原文は Aerobatics as per Flight Manual / Equipment as under airworthiness category \"A\" (Acrobatic) で、機体の類別ではなく装備の状態を指す表現。なお航空法施行規則の附属書第一では、滑空機 実用U は普通の飛行に加えて失速旋回・急旋回・錐揉・レージーエイト・シャンデル・宙返りの6課目、曲技Aは曲技飛行そのものに適するものと定義されている。飛行規程2-3が挙げる曲技課目10種のうち、スプリットS・インメルマン・スロー・ロール・背面飛行の4つはこの6課目に含まれない。実用U指定の機体でどこまでできるかは、教官または耐空検査員に確認するのが安全。",
 hint:"「滑空機 実用U」と即答できているか。「装備でAになる」と答えてしまわないこと。耐空類別は耐空証明書と運用限界等指定書で指定されるもので装備では変わらない、プラカードが示すのは装備の状態、と切り分けられているか。"},

{cat:"aircraft", imp:3, examiner:["higuchi","fuka"],
 q:"悪気流とは何ですか。",
 a:"飛行規程では、リー・ウェイブのローター、雷雲、および目視できる旋風等の中での気流、または山頂を通過するときに遭遇する気流、と定められています。この中で許される最大の速度が悪気流速度VRAで、ASK21では108ktです。",
 rel:["ASK21の速度限界にはどのようなものがありますか。", "ソアリングにはどのような種類がありますか。"],
 hint:"自分の言葉での説明ではなく、飛行規程の定義（ローター・雷雲・旋風・山頂通過時の気流）を挙げられているか。VRA108ktとの結びつきまで言えるか。"},

{cat:"aircraft", imp:3, examiner:["higuchi","fuka"],
 q:"VNEで飛行しているとき、大きな舵で旋回してもよいですか。エアブレーキは全開にできますか。",
 a:"大きな舵は使えません。飛行規程では、VNEにおける操縦舵面の操作量は最大操作量の3分の1に制限されています。運動速度VAの97kt（180km/h）までは各操縦舵面をいっぱいまで使用できますが、それを超える速度では慎重に操舵する必要があります。操作量を制限しているのは、制限荷重倍数に達する前に舵面そのものが空力荷重に耐えられず壊れる可能性があるためで、最悪の場合エルロンが吹き飛ぶといったことも起こり得ます。エアブレーキも全開にはできません。",
 s:"大きな舵は使えません。VNEでは操縦舵面の操作量が最大の3分の1に制限されているからです。制限荷重倍数に達する前に舵面自体が空力荷重で壊れる可能性があるためです。エアブレーキも全開にはできません。",
 rel:["ダイブブレーキは何をするための装置ですか。", "ASK21の速度限界にはどのようなものがありますか。", "この機体（ASK21）の荷重制限（制限荷重倍数）について説明して"],
 hint:"舵は「3分の1に制限」、エアブレーキも「全開にはできない」という点をそれぞれ説明できているか。操作量を制限しているのは舵面自体が壊れる可能性があるためだと言えているか。"},

{cat:"aircraft", imp:2, examiner:["fuka"],
 q:"高度が上がるとVNEはどう変わりますか。なぜですか。",
 a:"指示対気速度で見たVNEは、高度が上がるほど小さくなります。飛行規程では5000ftで151kt、10000ftで144kt、15000ftで132kt、20000ftで121ktとされています。理由は、フラッターに関係するのは真対気速度（TAS）だからです。高度が上がると空気密度が下がって翼の振動を抑える空気力学的な減衰力が弱まるうえ、同じ指示対気速度（IAS）でも真対気速度（TAS）は大きくなるため、高高度ではより低いIASの段階でフラッターの危険域に達してしまいます。目安としては5000ftごとにおよそ10kt近く変わる、と捉えておけばよいです。",
 s:"指示対気速度で見たVNEは、高度が上がるほど小さくなります。5000ftで151kt、10000ftで144kt、15000ftで132kt、20000ftで121ktです。フラッターに関係するのは真対気速度で、高度が上がると空気密度の低下で減衰力が弱まり、同じ指示対気速度でも真対気速度が大きくなるためです。",
 rel:["ASK21の速度限界にはどのようなものがありますか。", "高高度を飛行する場合、どのような装備が必要ですか。"],
 hint:"「指示対気速度（IAS）で見たVNEは下がる」と言えているか。理由が真対気速度（TAS）とフラッターの関係であることまで説明できているか。5000ftごとに約10ktという目安。"},

{cat:"aircraft", imp:2, examiner:["fuka"],
 q:"制限荷重倍数は、VNEにおいてVAにおけるものより小さくなっています。なぜですか。",
 a:"高速飛行時における構造的な破壊を防ぎ、安全マージン（突風や意図しない操舵への耐性）を確保するためです。動圧は速度の2乗で効くため、VNEの151ktではVAの97ktに比べて動圧が約2.4倍になり、荷重倍数以外の荷重（特に高速・低迎角で圧力中心が後方へ移ることによる主翼のねじりモーメントや、舵面・尾翼にかかる荷重）が増えます。突風による荷重倍数の増分も速度に比例するため、VNEではVAの約1.6倍の突風荷重が上乗せされます。そのため、あらかじめ使ってよい荷重倍数を絞ってあります。",
 s:"高速飛行時における構造的な破壊を防ぎ、安全マージン（突風や意図しない操舵への耐性）を確保するためです。",
 rel:["この機体（ASK21）の荷重制限（制限荷重倍数）", "VNEで飛行しているとき、大きな舵で旋回してもよいですか。"],
 hint:"「高速時の構造破壊防止と安全マージン確保」という目的が言えているか。そのうえで、動圧が速度の2乗で効くこと、ねじりモーメントや突風荷重の増加のいずれかを補足できているか。"},

{cat:"aircraft", imp:2, examiner:["fuka"],
 q:"加速度計（Gメーター）の標識について説明してください。制限荷重倍数とは違うのですか。",
 a:"違います。加速度計（Gメーター）の標識は、機体に加わるG（加速度）の安全限界を目で見えるようにした計器の目盛り（黄色の警戒範囲や赤線）のことで、パイロットが限界を超えないようにするための運用上の目印です。具体的には、正の側は運動速度VAから超過禁止速度VNEの範囲にあたるプラス5.3からプラス6.5Gが黄色の警戒範囲、VNEにおける制限値プラス6.5Gが赤です。負の側は警戒範囲がマイナス3.0からマイナス4.0、制限値がマイナス4.0です。一方の制限荷重倍数は、機体が永久に変形（歪み）を起こさずに耐えられる構造上の物理的な限界値で、VAにおいてプラス6.5、マイナス4.0。VNEにおいてプラス5.3、マイナス3.0。エアブレーキ展開時にプラス3.5で、マイナス側はゼロ、というように速度の状態ごとに定められた設計上の値です。数字は似ていますが、Gメーターの標識は運用上の目印、制限荷重倍数は設計上の限界という別の概念なので、混同しないよう注意が必要です。",
 s:"違います。加速度計の標識はG（加速度）の安全限界を示す運用上の目印で、正の側はプラス5.3からプラス6.5Gが黄色の警戒範囲、プラス6.5Gが赤の制限値。負の側は警戒範囲がマイナス3.0からマイナス4.0、制限値がマイナス4.0です。制限荷重倍数のほうは機体が変形せず耐えられる構造上の限界値で、速度の状態ごとに定められた別の項目です。",
 rel:["この機体（ASK21）の荷重制限（制限荷重倍数）", "速度計のマーキングについて説明してください。"],
 hint:"「計器の標識（運用上の目印）」と「制限荷重倍数（設計上の限界）」が別項目であることを区別できているか。数字を取り違えていないか。"},

{cat:"aircraft", imp:3, examiner:["fuka"],
 q:"「揚力発生部を除いた部分の最大重量410kg」とは何ですか。水バラストはこれに含まれますか。",
 a:"主翼以外の部分、つまり胴体側の重量の上限で、実質的には主桁にかかる荷重の制限です。最大離陸重量600kgとの差の190kgが主翼側の余地にあたります。水バラストは含まれません。水バラストは主翼の中にあり、主翼自身が発生する揚力でその場で支えられるため、主桁を曲げる荷重にならないからです。搭乗者や荷物のように胴体に載る重量だけが410kgの対象になります。",
 s:"主翼以外、つまり胴体側の重量の上限で、実質は主桁にかかる荷重の制限です。水バラストは含まれません。主翼の中にあり、主翼自身の揚力でその場で支えられるので、主桁を曲げる荷重にならないからです。",
 rel:["重量限界にはどのようなものがありますか。", "ASK21はどのような航空機ですか。"],
 hint:"「主桁にかかる荷重の制限」という本質が言えているか。水バラストが対象外である理由を、主翼自身の揚力で支えられるからと説明できているか。"},

{cat:"aircraft", imp:2, examiner:["fuka","yuda"],
 q:"ASK21の許容重心位置範囲を答えてください。基準点はどこですか。",
 a:"許容重心位置範囲は、基準点（後述）から後方に234mm〜469mmの間（平均翼弦長の20.2%〜41.1%に相当）です。基準点は主翼付け根の前縁です。",
 rel:["重心位置が後方限界に近いと、スピンに入りやすくなりますか。", "重量限界にはどのようなものがありますか。", "重量重心を計測するとき、機体の水平はどのように出しますか。"],
 hint:"前方234mm・後方469mmという数値と、基準点が主翼付け根前縁であることが言えているか。%MACまで言えれば十分。"},

{cat:"departure", imp:1, examiner:["fuka"],
 q:"重量重心を計測するとき、機体の水平はどのように出しますか。",
 a:"胴体後部の上面、トータルエナジーのピトー管が生えているあたりに、1000対52の傾きを持った枠型の治具を置き、その上面に水平器を載せて水平を出します。この1000対52という数値は、飛行規程の別添1、三面図にセンターライン・アジャストメント、1000対52 ホリゾンタル、として記載されています。専用の枠型は実際に存在します。",
 s:"胴体後部の上面、トータルエナジーのピトー管が生えているあたりに、1000対52の傾きを持った枠型の治具を置き、その上面に水平器を載せて水平を出します。この1000対52は、飛行規程の別添1、三面図に記載されています。",
 rel:["ASK21の許容重心位置範囲を答えてください。", "固定バラストの重量とアーム（モーメント）の関係"],
 hint:"「胴体後部上面に1000対52の枠を置いて水平器で見る」という具体的な方法が言えているか。三面図に根拠があることまで言えれば十分。"},

{cat:"aircraft", imp:2, examiner:["fuka","yuda"],
 q:"ASK21の横風限界は何ノットですか。",
 a:"8kt（15km/h）です。飛行規程の第2章 限界事項に記載されています。",
 rel:["ウインドソック（吹き流し）で風速はどのように判断しますか。"],
 hint:"8kt（15km/h）という数値が即答できるか。"},

{cat:"aircraft", imp:2, examiner:["fuka","yuda"],
 q:"ASK21の通常飛行における最少装備品を挙げてください。",
 a:"7つあります。最大目盛300km/hの速度計、高度計、4点式シートベルト、自動式または手動式のパラシュートあるいは圧縮状態で10cm以上の厚さのシートクッション、重量重心プラカード、データプレート、そして飛行規程です。ここでいう最少装備品は、この機体が耐空性を持つために備えていなければならないものの一覧で、日本の航空法上の書類の搭載義務とは別の話です。なお飛行規程が単位を指定しているのは速度計だけで、最大目盛300km/hと明記されています。高度計については単に高度計とあるだけで、単位の指定はありません。日本では高度をフィートで扱うので、実機にはフィート表示の高度計が装備されています。",
 s:"7つあります。最大目盛300km/hの速度計、高度計、4点式シートベルト、パラシュートまたは厚さ10cm以上のシートクッション、重量重心プラカード、データプレート、そして飛行規程です。これは耐空性を持つための一覧で、日本の航空法上の搭載義務とは別の話です。",
 rel:["最少装備品に飛行規程が入っていますが、滑空機は搭載が免除されているのではありませんか。", "曲技飛行を行うために追加で必要な装備品は何ですか。", "高高度を飛行する場合、どのような装備が必要ですか。"],
 hint:"7項目のうち5つ以上を挙げられるか。パラシュートの代わりにシートクッションでもよいことを落としていないか。飛行規程が入っている点を突っ込まれても、耐空性の要件と搭載義務は別だと切り分けられるか。"},

{cat:"departure", imp:2, examiner:["fuka"],
 q:"最少装備品に飛行規程が入っていますが、滑空機は搭載が免除されているのではありませんか。",
 a:"ご指摘のとおりで、実際に機体へ積む必要はありません。2つの別々の話が同じ「飛行規程」という言葉で出てくるので、切り分けて答えます。1つ目は飛行規程 第2章の最少装備品です。これはこの機体が耐空性を持つために備えていなければならないものの一覧で、ドイツの原典を翻訳したものです。2つ目は日本の航空法による書類の搭載義務で、こちらは航空法施行規則第143条により、滑空機は免除されています。したがって実務上は機体に積まず、地上の事務所に整えておいて、出発前確認では現物で確認します。ただし飛行中は自己の管理下に置いておく必要があります。「飛行規程は装備品なので積んでいます」と答えると免除を知らないと見られますし、「免除だから不要です」だけで終えると最少装備品の記載を読めていないと見られます。両方に触れるのが正解です。",
 s:"ご指摘のとおり、機体へ積む必要はありません。飛行規程 第2章の最少装備品は、この機体が耐空性を持つための要件の一覧で、日本の航空法による書類の搭載義務とは別のものです。搭載義務のほうは施行規則第143条で滑空機は免除されているので、地上に整えておいて現物で確認します。",
 rel:["滑空機は、備え付けが義務付けられている書類を機体に搭載しなくてもよいのですか。", "ASK21の通常飛行における最少装備品を挙げてください。", "機体に備え付ける書類を、根拠条文とあわせてすべて挙げてください。"],
 hint:"「耐空性の要件としての最少装備品」と「航空法上の搭載義務」を切り分けられているか。規則143条の免除と、自己の管理下に置く必要があることの両方に触れられるか。"},

{cat:"aircraft", imp:2, examiner:["fuka"],
 q:"曲技飛行を行うために追加で必要な装備品は何ですか。",
 a:"4つです。前席と後席のフロアハーネス、前席のGメーター、前席と後席のラダーペダルストラップ、そしてパラシュートです。飛行規程2-4の最少装備品の一覧で、通常の7項目に続けて8番から11番として挙げられています。押さえておきたい点が2つあります。1つはパラシュートで、通常飛行では自動式か手動式のパラシュート、または圧縮状態で10cm以上の厚さのシートクッションでよいのに対し、曲技飛行ではパラシュートでなければなりません。もう1つが呼び名です。8番のフロアハーネスは、コクピットのプラカードでは bottom strap、耐空検査準備作業報告書の装備品の表ではボトム・ストラップと書かれていますが、同じものです。JA20HCの現況は、Gメーターは飛行規程では前席だけでよいところを前後席とも装備、ボトム・ストラップも前後席とも装備しているので、4項目とも満たしています。",
 s:"4つです。前席と後席のフロアハーネス、前席のGメーター、前席と後席のラダーペダルストラップ、そしてパラシュート。",
 rel:["ASK21の通常飛行における最少装備品を挙げてください。", "ASK21の耐空類別は何ですか。", "Gメーター（加速度計）は曲技以外の飛行でも必要ですか。"],
 hint:"4項目を、前後席か前席かまで含めて挙げられるか。パラシュートが必須になる点に触れられているか。フロアハーネスがプラカードや装備品表のボトム・ストラップと同じものだと分かっていると加点。"},

{cat:"aircraft", imp:1, examiner:["fuka"],
 q:"ASK21で認められている曲技の課目は何種類ありますか。禁止されている課目はありますか。",
 a:"10種類が限定されています。ループ、ストールターン、スプリットS、インメルマン、スロー・ロール、背面飛行、スピン、急上昇旋回、レージーエイト、シャンデルです。禁止されているのは、急激な操作による曲技飛行、ネガティブループ、テイルスライドの3つです。また曲技飛行中は絶対に操縦桿およびラダーから手足を離してはならず、コントロールを失うか急激に速度が増加した場合は直ちにエアブレーキを開けます。ただしテイルスライドの場合は除きます。トリムは中立を維持し、終了するまで変更しません。",
 s:"10種類が限定されています。ループ、ストールターン、スプリットS、インメルマン、スロー・ロール、背面飛行、スピン、急上昇旋回、レージーエイト、シャンデルです。禁止されているのは、急激な操作による曲技飛行、ネガティブループ、テイルスライドの3つです。",
 rel:["運用様式限界とは何ですか。", "曲技飛行を行う上での基準には"],
 hint:"10課目のうち半分程度を挙げられるか。禁止課目（ネガティブループ・テイルスライド）を言えるか。"},

{cat:"aircraft", imp:2, examiner:["fuka"],
 q:"ASK21の失速速度を答えてください。単座と複座で違いますか。",
 a:"違います。飛行規程では単座470kgのとき、エアブレーキ閉で35kt（65km/h）、エアブレーキ開で37kt（68km/h）です。複座600kgのとき、エアブレーキ閉で40kt（74km/h）、エアブレーキ開で42kt（77km/h）です。エアブレーキを開くと失速速度は約2kt（3km/h）増加します。",
 s:"違います。単座470kgではエアブレーキ閉で35kt、開で37kt。複座600kgでは閉で40kt、開で42ktです。エアブレーキを開くと失速速度は約2kt増加します。",
 rel:["低速飛行（操縦可能な最小速度）は何ノットで行いますか。", "エアブレーキを開くと失速速度はどうなりますか。"],
 hint:"重量によって違うこと、複座600kgでエアブレーキ閉40kt（74km/h）という代表値が言えているか。"},

{cat:"aircraft", imp:2, examiner:["fuka"],
 q:"エアブレーキを開くと失速速度はどうなりますか。",
 a:"約1.6kt（3km/h）増加します。飛行規程4-9の進入・着陸の項に注意として明記されています。着陸進入でエアブレーキを開いた状態では、その分だけ失速までの余裕が減るということです。",
 rel:["ASK21の失速速度を答えてください。", "推奨進入速度は何ktですか。", "ダイブブレーキは何をするための装置ですか。"],
 hint:"「約1.6kt（3km/h）増える」という具体的な数値が言えているか。"},

{cat:"aircraft", imp:2, examiner:["fuka"],
 q:"推奨進入速度は何ktですか。速度を増やすのはどのような場合ですか。",
 a:"49kt（90km/h）です。タービュランスがある場合はこれよりも速度を増加させるのが望ましいとされています。また雨の中を飛行した場合は、安全マージンとして着陸進入速度を約5kt（10km/h）増加させます。エアブレーキを有効に使用すれば、速度を増加させずに深いパスでの進入ができます。着陸進入の初期にエアブレーキのロックを外しておくことが望ましい、とも書かれています。",
 s:"49ktです。タービュランスがあるときは増速するのが望ましいとされ、雨の中を飛行した場合は約5kt増やします。エアブレーキを有効に使えば、増速せずに深いパスでの進入ができます。",
 rel:["推奨最小進入速度とは、どのような速度ですか。", "雨の中を飛行してもよいのですか。", "エアブレーキを開くと失速速度はどうなりますか。"],
 hint:"49kt（90km/h）という数値と、増速する場面（タービュランス、雨中飛行後）が言えているか。"},

{cat:"aircraft", imp:1, examiner:["fuka"],
 q:"サイドスリップで進入角を調整するとき、注意することは何ですか。",
 a:"サイドスリップ中にラダーをいっぱいまで操作すると、ラダーの操舵力がほぼゼロになります（飛行規程4-9）。このためラダーを中立まで戻すには、反対のラダーを踏み返さなければなりません。自然には戻ってこない、という点が注意事項です。",
 rel:["スリップランディング（横滑り降下）を行う際、速度計が", "トップラダーとは何ですか。"],
 hint:"「ラダーの操舵力がほぼゼロになり、戻すには反対を踏み返す必要がある」という点が言えているか。"},

{cat:"aircraft", imp:2, examiner:["fuka"],
 q:"ウインチ曳航と航空機曳航の推奨速度、離陸速度を答えてください。曳航索の推奨長さは何mですか。",
 a:"ウインチ曳航は最大81kt（150km/h）で、推奨は49から60kt（90から110km/h）です。レリーズは主車輪前部の重心レリーズを使います。航空機曳航は必ずノーズレリーズを使用し、最大97kt（180km/h）、推奨は49から76kt（90から140km/h）です。曳航索の推奨長さは40から60mです。離陸速度は約40kt（75km/h）です。いずれもトリムは中立とします。",
 s:"ウインチ曳航は最大81kt、推奨49から60ktで、主車輪前部の重心レリーズを使います。航空機曳航は必ずノーズレリーズで、最大97kt、推奨49から76kt。曳航索の推奨長さは40から60m、離陸速度は約40ktです。",
 rel:["ASK21の速度限界にはどのようなものがありますか。", "航空機曳航（AT）とウインチ曳航（WT）で、レリーズの位置"],
 hint:"WT推奨49〜60kt、AT推奨49〜76kt、索長40〜60m、離陸速度約40kt（75km/h）のうち3つ以上が言えているか。"},

{cat:"aircraft", imp:2, examiner:["higuchi"],
 q:"航空機曳航（AT）を行う際の注意点を2つ挙げてください。",
 a:"1つ目は、曳航機を吊り上げないことです。ポーポイズ（上下運動）に注意し、小窓など他のことに気を取られて操縦がおろそかにならないようにします。2つ目は、グランドループを起こしたら直ちに索を離脱することです。",
 hint:"「曳航機を吊り上げない（ポーポイズに注意、他のことに気を取られない）」と「グランドループが起きたら直ちに離脱する」の2点が言えているか。"},

{cat:"aircraft", imp:1, examiner:["fuka"],
 q:"ウインチ曳航では、どのように操作するとより高い離脱高度が得られますか。",
 a:"飛行規程には、曳航の初期は僅かに頭上げ傾向があり、曳航の後半で操縦桿を引いて機首が下がらないようにすれば、より高い離脱高度が得られると書かれています。",
 rel:["ウインチ曳航と航空機曳航の推奨速度、離陸速度を答えてください。"],
 hint:"「曳航後半で機首を下げさせない」という操作が言えているか。"},

{cat:"aircraft", imp:1, examiner:["fuka"],
 q:"背面飛行では対気速度計の指示はどうなりますか。",
 a:"通常の動圧孔の形状では、背面飛行において大きな圧力誤差を生じ、対気速度計の指示は実際よりも22kt（40km/h）低い値を示します。真鍮製のチューブ、直径12mm・肉厚1mm・長さ140mmで動圧管を延長すれば正確な指示が得られます。チューブは機首方向に最低70mm突出させます。延長チューブが無い場合の背面飛行の許容指示対気速度はVA76kt（140km/h）、VNE130kt（240km/h）に下がり、延長チューブが付いていればVA97kt（180km/h）、VNE151kt（280km/h）となります。",
 s:"実際よりも22kt低い値を示します。通常の動圧孔の形状では、背面飛行で大きな圧力誤差を生じるためです。延長チューブが無い場合の許容指示対気速度はVA76kt、VNE130ktに下がり、付いていればVA97kt、VNE151ktとなります。",
 rel:["飛行中にピトー管が虫などで詰まった場合、どうしますか。", "ASK21の速度限界にはどのようなものがありますか。"],
 hint:"「実際より22kt（40km/h）低く出る」という数値と、延長チューブで補正できることが言えているか。"},

{cat:"aircraft", imp:1, examiner:["fuka"],
 q:"ASK21のタイヤ空気圧を答えてください。",
 a:"主輪が5.00-5で2.7バール、前輪が4.00-4で2.0バール、尾輪が210×65で2.5バールです。",
 hint:"主輪2.7バールという代表値が言えているか。3つとも言えれば十分。"},

// ── 非常操作（第3章）──
{cat:"emergency", imp:2, examiner:["fuka","yuda"],
 q:"キャノピーの投棄および緊急脱出の手順を説明してください。前席と後席のどちらが先に脱出しますか。",
 a:"状況の許す限り、後席のパイロットから先に脱出します。前席は、計器盤上部の赤いレバーを左に回してキャノピーを上に押します。後席は両側のサイドロックを後方に引きます。キャノピーを投棄したら、ハーネスを外し、立ち上がって脱出します。手動索式のパラシュートであれば、1秒から3秒待ってからリップコードをいっぱいに引きます。",
 rel:["前席と後席で、後席から先に脱出するのはなぜですか。", "飛行規程の「非常操作」には、どのような項目が", "キャノピー（風防）の取り扱いで注意することは"],
 hint:"「後席から先に脱出」という順序が言えているか。前席の赤レバーを左に回す、パラシュートは1〜3秒待つ、という具体まで言えるか。理由を聞かれたら重心の話ができるか。"},

{cat:"emergency", imp:3, examiner:["yuda"],
 q:"前席と後席で、後席から先に脱出するのはなぜですか。",
 a:"重心位置の問題です。前席は重心よりかなり前方にあり、アームが長いため、前席搭乗者の70kgから110kgが抜けると、重心は大きく後方へ移動します。後方限界を超えると縦の安定が失われ、飛行規程4-6にあるとおり、基準点後方400mmを超える領域ではスピンは回復操作を取らない限り持続します。つまり前席が先に脱出すると、後席のパイロットは重心が後方限界を超えた、回復が困難な機体に取り残されることになります。逆に後席は重心の近くにあるので、後席が先に抜けても重心移動は小さく、前席のパイロットは機体の制御を保ったまま脱出できます。ですから、状況の許す限り後席から先に脱出します。",
 s:"前席は重心より前方にあるため、先に抜けると重心が大きく後方へ移動し危険です。後席は重心付近なので、影響が小さいためです。",
 rel:["ASK21の許容重心位置範囲を答えてください。", "重心位置が後方限界に近いと、スピンに入りやすくなりますか。", "固定バラストの重量とアーム（モーメント）の関係"],
 note:"飛行規程は「状況の許す限り後席のパイロットから先に脱出する」と書くのみで、理由までは記載していません。上の説明は重心位置とアームの関係からの理解です。",
 hint:"「重心が後方へ移動するから」と即答できているか。前席はアームが長く重心移動が大きい／後席は重心付近なので移動が小さい、という対比ができているか。"},

{cat:"emergency", imp:2, examiner:["fuka","yuda"],
 q:"ウィングドロップに遭遇したときの回復操作を説明してください。",
 a:"ウィングドロップとは、失速に入るときに左右どちらかの翼が先に失速し、その翼が急に下がる現象です。左右の翼が同時に失速せず、迎え角や気流の乱れにわずかな差があると起こります。放っておくと下がった翼の側へ機首が回り込み、そのままスピンに入ります。回復は、直ちに操縦桿を前に押し、同時にロール方向と反対のラダーを踏み込みます。ラダーを操作しないと、操縦桿を前に操作してもスピンに入る可能性があります。ASK21の失速特性は極めて穏やかですが、タービュランスによるウィングドロップには遭遇し得ます。なおヨーイング角5度までは影響がなく、ピッチ角30度までの急な引き起こしでもウィングドロップは生ぜず静かに機首が下がります。45度バンクの旋回における失速も同様です。",
 s:"失速に入るときに左右どちらかの翼が先に失速し、その翼が急に下がる現象です。放っておくと下がった翼の側へ機首が回り込み、そのままスピンに入ります。回復は、直ちに操縦桿を前に押し、同時にロール方向と反対のラダーを踏み込みます。ラダーを操作しないと、操縦桿を押してもスピンに入る可能性があります。",
 rel:["スピンはどのような状況で起こりやすいですか", "失速からの回復操作を行う際、エルロン"],
 hint:"まず「片方の翼が先に失速して急に下がる現象」と定義できているか。そのうえで「操縦桿を前」と「反対ラダー」を同時に、ラダーを使わないとスピンに入り得るという理由まで。"},

{cat:"emergency", imp:1, examiner:["fuka"],
 q:"グランドループを起こしたらどうしますか。どのようなときに起こりやすいですか。",
 a:"直ちに索を離脱します。草丈が高い場合や路面が荒れている場合はグランドループの可能性があります。",
 rel:["飛行規程の「非常操作」には、どのような項目が"],
 hint:"「直ちに索を離脱する」と即答できているか。"},

// ── 通常操作・点検（第4章）──
{cat:"departure", imp:2, examiner:["fuka"],
 q:"飛行前点検で、エルロンとエアブレーキの接続はどのように確認しますか。",
 a:"左翼上部の点検窓から目視で確認します。見るのは、クイックコネクタ、ロテリエ・フィッティングのボールピボットが受け側のスロット部から突き出ているかどうかです。突き出ていなければ接続は不完全です。指で触れて確認します。さらにセーフティーロックをロック方向に押し込み、正しくロックされているかを確認し、そのセーフティーロックにスプリングクリップがかけられているかまで確認します。",
 s:"主翼左側上面にある点検窓から目視、触診、およびロックピンの確認によって行います。",
 rel:["組立時のリンケージ（操縦索・コネクション）の点検要領を説明してください。", "主翼の組立要領について説明してください。"],
 hint:"「左翼上部の点検窓から」という場所、「ボールピボットがスロットから突き出ているか」という判定基準、スプリングクリップの確認の3点が言えているか。"},

{cat:"departure", imp:2, examiner:["fuka"],
 q:"飛行規程のチェックリストにある離陸前点検の項目を挙げてください。",
 a:"7項目です。コントロールチェック、ハーネス、トリムセット、高度計セット、無線機オン、エアブレーキロック、キャノピーロックです。これに加えて、規定には記載がありませんが、実際には小窓の確認も行います。",
 rel:["機長の出発前確認事項（航空法第73条の2）の項目を", "飛行前点検で、エルロンとエアブレーキの接続はどのように確認しますか。"],
 hint:"7項目（コントロールチェック・ハーネス・トリムセット・高度計セット・無線機オン・エアブレーキロック・キャノピーロック）を挙げられるか。規定にはないが小窓の確認も実際には行う点に触れられると加点。"},

{cat:"departure", imp:2, examiner:["fuka"],
 q:"ハードランディングをしてしまった場合、どうしますか。",
 a:"飛行規程には、ハードランディングまたは過荷重のおそれがある場合は、主翼および尾翼を取り外して機体全般にわたる点検を行う、と書かれています。損傷があれば耐空検査員の点検を受け、修理が完了するまでは、いかなる場合でも飛行してはなりません。",
 rel:["バードストライク（鳥との衝突）が発生した場合の処置要領", "耐空証明書があれば、どんな整備・運用状態でも"],
 hint:"「主翼・尾翼を取り外しての全般点検」「耐空検査員の点検」「修理完了まで飛行禁止」の3段階が言えているか。"},

{cat:"departure", imp:1, examiner:["fuka"],
 q:"組み立てのとき、メインピンと主翼後縁のアタッチメントピンはどちらを先に入れますか。分解のときはどうですか。",
 a:"組み立てではメインピンが先です。飛行規程には、メインピンを差し込む前に後縁のアタッチメントピンを入れてはならない、と明記されています。分解は逆で、メインピンを抜く前に後縁のアタッチメントピンを抜きます。組み立て手順は、胴体を組み立て位置にセットして水平に維持し、左翼、右翼と差し込んでメインピンの孔を合わせ、メインピンを差し込んでセーフティー、その後に後縁アタッチメントピンという順です。",
 s:"組み立てではメインピンが先です。飛行規程に、メインピンを差し込む前に後縁のアタッチメントピンを入れてはならない、と明記されています。分解は逆で、メインピンを抜く前に後縁のアタッチメントピンを抜きます。",
 rel:["主翼の組立要領について説明してください。", "ASK21の組み立てには何人、どのくらいの時間が必要ですか。"],
 hint:"「組立はメインピンが先、分解は後縁ピンが先」という順序が正しく言えているか。"},

{cat:"aircraft", imp:1, examiner:["fuka"],
 q:"係留や駐機の際に注意することは何ですか。",
 a:"係留時は必ずキャノピーを閉じてロックします。発航待ちであっても、直射日光の下でキャノピーを開けたままにしてはなりません。太陽の位置と日射の強さによっては、キャノピーがレンズとなって計器板やヘッドレスト付近に焦点を結び、その部分を焦がす危険があるためです。屋外に駐機する場合は必ずキャノピーを閉めてロックし、白いカバーで覆います。また陸上輸送の際は、いかなる場合も垂直安定板上部のエレベーターアクチュエータに荷重をかけてはなりません。柔らかいクッションであっても例外ではありません。",
 s:"係留時は必ずキャノピーを閉じてロックします。直射日光の下で開けたままにすると、キャノピーがレンズとなって計器板やヘッドレスト付近に焦点を結び、焦がす危険があるためです。屋外なら白いカバーで覆います。",
 rel:["キャノピー（風防）の取り扱いで注意することは", "地上でグライダーを移動させる際に注意することは"],
 hint:"「キャノピーがレンズになって焦がす」という理由が言えているか。閉めておく、という結論だけでは不足。"},

{cat:"aircraft", imp:1, examiner:["fuka"],
 q:"ASK21の注油・グリスアップはどのような頻度で行いますか。",
 a:"注油・グリスアップは、主に機体の組み立て（リギング）時、および年次検査（定期検査）時（少なくとも年に1回）の頻度で行うよう、アレキサンダー・シュライハー社のメンテナンスマニュアル（Lubrication Scheme）で規定されています。具体的なタイミングと部位別の対応は次のとおりです。組み立て（リギング）時は、スムーズな結合と摩耗・固着防止のため、その都度、主翼や尾翼の接続ピン（メインピン・ドラッグピン）、ブッシング、各操縦系統の自動接続コネクター（ロテリエ・フィッティングなど）の古いグリスや汚れを拭き取り、指定のグリスまたはオイルを薄く塗布します。年次検査時は、注油計画図（Lubrication Scheme）に基づき、最低でも年に1回、操縦桿ベースやラダーペダル可動部、操縦ロッド用ベアリングやベルクランク、曳航索離脱装置（トスト・リリース。別途TOST社のマニュアルに基づく洗浄・注油が必要）、着陸脚の軸受け・可動部など、操縦系統全体の注油を行います。",
 s:"注油・グリスアップは、主に機体の組み立て（リギング）時、および年次検査（定期検査）時（少なくとも年に1回）の頻度で行うよう、アレキサンダー・シュライハー社のメンテナンスマニュアル（Lubrication Scheme）で規定されています。",
 rel:["グライダーの定期交換部品（いわゆるカレンダー部品）には"],
 hint:"組み立て（リギング）時と年次検査時（少なくとも年1回）という2つの周期が区別できているか。組み立て時は接続ピン・ブッシング・自動接続コネクター、年次検査時は操縦系統全体（操縦桿ベース・ベアリング・トストリリース・着陸脚など）が対象であることまで言えているか。"},

// ── 口述の作法 ──
{cat:"tem", imp:3, examiner:["yuda"],
 q:"スレット・アンド・エラーマネジメント（TEM）について説明してください。いまのケース（曳航中に曳航機が雲へ近づいた）でのスレットは何ですか。",
 a:"大前提として、人間の脳は必然的に誤りを犯すので、エラーをなくすことはできません。ですからエラーを減らすことと、エラーの影響を軽減することを目指す、というのがTEMの根本的な考え方です。スレットは乗員が関与できない領域で生じるもので、乗員が引き起こすものではありません。エラーは、組織やクルー自身がするはずのこと、できるはずのことをしなかった、またはできなかった状態です。両者を放置するとUAS、望ましくない航空機の状態に至り、そこも修正できないと事故になります。そこで各段階にマネジメントという防御線を張ります。いまのケースのスレットは、雲底が下がってきていること、曳航機からは滑空機側の視界の状況が分からないこと、雲に入る前の段階でVMCの条件を割り込む可能性があること、離脱の判断が遅れると回復に使える高度が減ること、曳航機との意思疎通が無線に依存していることなどです。VMCについては、雲に入らなければよいというものではありません。曳航中は地表から300m以上、つまり管制区の中を飛んでいますから、3,000m未満の管制区内のVMC、雲から上方150m、下方300m、水平600m、飛行視程5,000mが求められます。雲から水平600mというのは相当な距離ですから、雲に入るはるか手前で、もう条件を満たさなくなっている可能性があります。つまり「まだ雲には入っていないから大丈夫」という判断そのものがスレットだ、ということです。",
 s:"人はエラーを犯すので、エラーをなくすことはできません。だから、減らすことと影響を軽減することを目指す、というのがTEMです。いまのケースのスレットは、雲底が下がってきていること、曳航機からは滑空機側の状況が見えないこと、雲に入る前でもVMCの条件を割り込むこと、離脱が遅れると使える高度が減ることなどです。VMCは曳航中なら管制区内なので、雲から水平600m、飛行視程5,000m。雲に入るはるか手前で条件を割ります。",
 rel:["スレット（脅威）とは何ですか。具体例を挙げてください。", "エラーとはどのようなものですか。具体例を挙げてください。", "UAS（望ましくない航空機の状態）とは何ですか。", "スレットを3つしか発見できないパイロットと、5つ発見できるパイロットがいます。"],
 hint:"「エラーはなくせないので、減らす・影響を軽減する」という大前提が言えているか。スレットとエラーの区別（乗員が関与できるかどうか）ができているか。スレットとして、雲に入る前にVMCを割り込むこと（曳航中は管制区内なので雲から水平600m・視程5,000m）を挙げられていると加点。"},

{cat:"tem", imp:3, examiner:["yuda"],
 q:"スレットを3つしか発見できないパイロットと、5つ発見できるパイロットがいます。どちらが安全なパイロットですか。",
 a:"どちらでもありません。スレットを多く発見できるから、その分安全だ、ということにはならないからです。大事なのはその後のマネジメントです。スレットを発見したとしても、それをマネジメントできないのであれば何の意味もありません。ですから、発見した数を比べるのではなく、スレットマネジメントとエラーマネジメントの部分を考えなければならない、というのが答えになります。",
 s:"どちらでもありません。大事なのは発見した数ではなく、その後のマネジメントです。発見してもマネジメントできなければ意味がありません。",
 note:"2026年の実地試験で実際に問われた設問です。「多く挙げられる方が安全」と答えると外れます。",
 rel:["エラーが発生したら、それは事故につながりますか。", "スレット・アンド・エラーマネジメント（TEM）について説明してください。", "日々のトレーニングで、スレットを多く挙げられるパイロットに"],
 hint:"「どちらでもありません」と言い切れているか。理由が「その後のマネジメントが大事だから」と説明できているか。発見の数を安全の指標にしていないか。"},

{cat:"tem", imp:3, examiner:["yuda"],
 q:"エラーが発生したら、それは事故につながりますか。",
 a:"エラーそれだけで事故に直結するわけではありません。エラーの結果として望ましくない航空機の状態、UASが生まれ、それを修正できなければ事故につながることがあります。TEMは、スレット、エラー、UASという各段階にそれぞれマネジメントという防御線を張る考え方で、どこかの段階で止められれば事故には至りません。ですから、エラーが起きたかどうかではなく、マネジメントの防御線の段階を重視して答えるのがよいです。",
 s:"それだけでは直結しません。エラーの結果としてUAS、望ましくない航空機の状態が生まれ、それを修正できなければ事故になります。各段階に防御線を張り、どこかで止められれば事故には至りません。",
 rel:["スレットを3つしか発見できないパイロットと、5つ発見できるパイロットがいます。", "UAS（望ましくない航空機の状態）とは何ですか。", "スレット・アンド・エラーマネジメント（TEM）について説明してください。"],
 hint:"「直結はしない」と言い切ったうえで、エラー→UAS→修正できなければ事故、という順序が言えているか。防御線の段階という枠組みで答えられているか。"},

{cat:"tem", imp:3, examiner:["yuda"],
 q:"スレットを予期できると、なぜエラーしないのですか。",
 a:"エラーの多くは、予期していないことが起きて驚き、限られた時間の中で判断を迫られたときに出るからです。予期していれば、その状況は「想定内」になります。反射的に対応するのではなく、あらかじめ決めておいた手順を実行するだけになるので、手順の抜けや操作の間違いが起きにくくなります。また、予期していれば注意をそこへ向けて配れるので、エラーが起きても早い段階で気づいて修正でき、望ましくない状態まで進みません。",
 s:"エラーの多くは、予期していないことが起きて驚き、限られた時間で判断を迫られたときに出るからです。予期していれば想定内になり、決めておいた手順を実行するだけになります。気づくのも早くなります。",
 rel:["スレット・アンド・エラーマネジメント（TEM）について説明してください。"],
 hint:"「驚きと時間切迫がエラーを生む／予期していれば想定内の手順の実行になる」という説明ができているか。エラーをゼロにするのではなく、早く捕まえられる、という点まで言えれば十分。"},

{cat:"tem", imp:3, examiner:["yuda"],
 q:"日々のトレーニングで、スレットを多く挙げられるパイロットになるには、どのようなトレーニングをすればよいですか。",
 a:"飛ぶ前に、その日のスレットを声に出して、あるいは書き出して挙げる習慣をつけることです。毎回やっていると、挙げられる数と切り口が増えていきます。飛んだ後には、実際に何が起き、自分の予想と何が違ったかを振り返ります。あわせて、事故やインシデントの報告例、ほかのパイロットのヒヤリハットを読んで、自分の引き出しに入れておくこと。そして、教官や仲間とブリーフィングとデブリーフィングで言葉にしてすり合わせること。これを繰り返すのが一番の訓練になります。",
 s:"飛ぶ前に、その日のスレットを声に出す、または書き出す習慣をつけることです。飛んだ後は、実際に何が起きたかを振り返ります。あわせて他の人のヒヤリハットを読み、ブリーフィングで言葉にしてすり合わせます。",
 rel:["「技量があれば安全に飛べる」と言えますか。"],
 hint:"「気をつける」といった精神論ではなく、事前の書き出し・事後の振り返り・事例の学習・ブリーフィングという具体的な習慣を挙げられているか。"},

{cat:"tem", imp:3, examiner:["yuda"],
 q:"「技量があれば安全に飛べる」と言えますか。",
 a:"言えません。技量は安全の必要条件であって、十分条件ではありません。操縦の腕が確かでも、状況の把握、意思決定、見張り、コミュニケーション、自分のコンディションの管理といったノンテクニカルな部分が伴わなければ、危険な状況にそもそも入り込んでしまいます。実際、事故の多くは操縦技術そのものではなく、判断や見張りの不足から起きています。技量があるほど、無理のきく状況に踏み込みやすくなる、という面もあります。",
 s:"言えません。技量は必要条件であって、十分条件ではないからです。状況把握、意思決定、見張り、コミュニケーション、体調管理といったノンテクニカルな部分が伴わなければ、危険な状況に入り込んでしまいます。",
 rel:["日々のトレーニングで、スレットを多く挙げられるパイロットに"],
 hint:"「言えません」と言い切ったうえで、ノンテクニカルスキルの具体（状況把握・意思決定・見張り・コミュニケーション・自己管理）を挙げられているか。"},

// VMCの実践判断
{cat:"airspace", imp:3, examiner:["yuda"],
 q:"地上で視程がいいと思って上がったが、上空の視程が悪い。どうしますか。",
 a:"周囲の安全と自機の位置を確保しながら、速やかに着陸態勢に移るか、安全な滑空場へ引き返すのが鉄則です。まず地表の目印やGPSで自機の位置を確認し、滑空場や着陸可能な場所に戻れる距離にいるかを把握します。視界が悪いと姿勢感覚が狂いやすいため、速度計・昇降計・旋回計などの計器で安全な速度を維持します。他機が見えにくくなるリスクがあるため、FLARMの確認や無線での注意喚起・位置通報で見張りを強化します。",
 rel:["VFRで飛行する際のVMC（有視界気象状態）の条件について", "視程には「飛行視程」と「卓越視程」が", "有視界飛行中に誤って雲の中に入ってしまった場合"],
 hint:"「周囲の安全と自機の位置を確保しながら速やかに着陸態勢に移る、または引き返す」という結論を言えるか。自機位置の確認（目印・GPS）、計器による速度・高度維持、FLARM・無線による見張り強化、という3つの初期対応が挙げられるか。"},

{cat:"airspace", imp:3, examiner:["yuda"],
 q:"曳航中はどうしますか。曳航機が何となく雲に近づいていったら、どうしますか。",
 a:"曳航機からは滑空機側がどう見えているか分からないので、まず無線で曳航機に状況を伝え、進路の変更を要求します。それでも雲へ近づき続け、このままでは有視界気象状態を維持できないと判断した時点で、自分の判断で離脱します。曳航中であっても、滑空機の機長は自分です。曳航機についていったから責任を免れる、ということはありません。離脱後に滑空場へ戻れる高度と位置にあるうちに決めることが大事です。",
 s:"まず無線で曳航機に状況を伝え、進路の変更を要求します。それでもVMCを維持できないと判断した時点で、自分の判断で離脱します。曳航中であっても、滑空機の機長は自分だからです。",
 rel:["曳航機についていくか、切り離すかの基準は", "VFRで飛行する際のVMC（有視界気象状態）の条件について", "曳航中の合図にはどのようなものがありますか。"],
 hint:"「無線で伝える→それでも駄目なら自分の判断で離脱」という2段階と、「曳航中でも機長は自分」という責任の所在が言えているか。"},

{cat:"airspace", imp:3, examiner:["yuda"],
 q:"曳航機についていくか、切り離すかの基準は何ですか。",
 a:"基準は2つです。1つは、有視界気象状態を維持できるかどうか。維持できなくなると判断したら離脱します。もう1つは、いま離脱して滑空場に戻れるか、戻れないなら安全に降ろせる場所があるか、です。この2つ目があるので、離脱の判断は「もう駄目だ」と思ってからでは遅く、まだ戻れるうちに決めなければなりません。具体的には、曳航前の打ち合わせの段階で、どの高度・どの位置までなら戻れるかを自分の中で決めておき、そこを判断点にします。",
 s:"基準は2つです。VMCを維持できるかどうか。いま離脱して滑空場へ戻れるか、戻れないなら安全に降ろせる場所があるかです。まだ戻れるうちに決めなければなりません。",
 rel:["曳航中はどうしますか。曳航機が何となく雲に近づいて", "曳航前の打ち合わせで確認しておくべきエマージェンシー項目"],
 hint:"VMC維持と帰投可能性という2つの基準を挙げられているか。判断点を事前に決めておく、という発想があるか。"},

// 捜索救難・アウトランディング
{cat:"emergency", imp:2, examiner:["yuda"],
 q:"クロスカントリー飛行でアウトランディングし、機体を壊して自身も負傷して動けません。捜索救難のルールはどうなっていますか。",
 a:"まず命を最優先に、動ける範囲で119番か110番へ直接通報するか、機体の無線で121.5MHzを送信するのが望ましいです。通報時に最優先で伝えるべき情報は「現在地」と「怪我の状況」です。フライトプランを出していれば、到着予定時刻を過ぎて連絡がないと、不確実の段階、警戒の段階、遭難の段階の順に捜索救難が自動的に進み、遭難の段階で救難調整本部が指揮する本格的な捜索が始まります。動けなくても、機体のそばを離れず、防寒して救助を待つのが基本です。フライトプランを出していなければ誰も気づかないので、その提出が生命線になります。",
 s:"命を最優先に、119/110番への通報か、機体の無線で121.5MHzを送信するのが望ましいです。最優先で伝えるべきは「現在地」と「怪我の状況」です。フライトプランがあれば、不確実→警戒→遭難の3段階で自動的に捜索が進み、遭難の段階で救難調整本部が本格捜索を始めます。動けなくても機体のそばで防寒しながら救助を待つのが基本です。",
 rel:["捜索救難の段階区分について説明してください。", "アウトランディングで機体を壊し、負傷して動けません。早く救助される", "捜索救難活動を取り仕切る機関はどこですか。"],
 hint:"命を最優先にした初動（119/110番通報、121.5MHzでの送信）、通報時に最優先で伝える情報（現在地・怪我の状況）、不確実→警戒→遭難の3段階、遭難の段階で救難調整本部が指揮すること、機体のそばを離れず防寒して待つことのいずれかに触れているか。"},

{cat:"emergency", imp:2, examiner:["yuda"],
 q:"アウトランディングで機体を壊し、負傷して動けません。早く救助されるためには、どうしますか。",
 a:"事前の備えと、着陸後の行動の両方があります。事前には、フライトプランを提出して到着予定時刻を正確に申告しておくこと、飛行前に飛行経路と着陸候補地を関係者に伝えておくこと、携帯電話を充電しておくこと、そして位置を発信できる装置、ELTや位置情報を送れるロガー、携帯のアプリなどを持つことです。着陸後は、まず自分の位置をできるだけ正確に把握し、携帯電話が通じるなら、救急や警察へ通報し、あわせて滑空場の関係者へ連絡します。通じない場合に備え、機体を目立つ場所に置く、白い翼面を上に向ける、といった視認性の確保も有効です。",
 s:"事前の備えと、着陸後の行動があります。事前は、フライトプランの提出、飛行経路と着陸候補地を関係者に伝えておくこと、携帯の充電、位置を発信できる装置。着陸後は、自分の位置を正確に把握し、通じるなら救急や警察へ通報して、滑空場へも連絡します。通じないときは機体を目立たせます。",
 rel:["クロスカントリー飛行でアウトランディングし、機体を壊して", "アウトランディングで機体を壊し、負傷して動けません。携帯電話は通じます", "フライトプランはどのような場合に必要ですか。"],
 hint:"「事前の備え」と「着陸後の行動」を分けて答えられているか。位置を伝える手段を具体的に挙げられているか。"},

{cat:"emergency", imp:2, examiner:["yuda"],
 q:"アウトランディングで機体を壊し、負傷して動けません。携帯電話は通じます。救助を求めて通報するとき、何を伝えますか。",
 a:"位置、状況、人数、そして機体です。位置は緯度経度、または最寄りの地名・目標物からの方向と距離。状況は負傷の有無と程度、動けるかどうか、火災や燃料漏れの危険の有無。人数は搭乗者数と、それぞれの状態。機体は登録記号、種類、色です。あわせて、自分の連絡先と、いま電話が使える時間、バッテリー残量も伝えておくと、次の連絡の取り方を相手が決められます。",
 s:"位置、状況、人数、機体の4つです。位置は緯度経度か、目標物からの方向と距離。状況は負傷の程度と動けるかどうか。人数は搭乗者数とそれぞれの状態。機体は登録記号、種類、色です。あわせて連絡先とバッテリー残量も伝えます。",
 rel:["アウトランディングで機体を壊し、負傷して動けません。早く救助される", "クロスカントリー飛行でアウトランディングし、機体を壊して"],
 hint:"位置・状況・人数・機体という4本の柱で整理できているか。緯度経度だけでなく目標物からの方向と距離という言い方ができるか。"},

{cat:"inflight", imp:2, examiner:["yuda"],
 q:"アウトランディングする際の手順を説明してください。",
 a:"高度に余裕のあるうちに決めることが全てです。まず、まだ十分な高度があるうちにアウトランディングを決心し、着陸場所の選定にかかります。選ぶ基準は、大きさ、風向に対する向き、地面の状態、傾斜、そして進入経路上の障害物です。畑であれば作物の種類と畝の向きも見ます。決めたら、上空から場周経路を組み立て、風向を煙や水面、草の動きから確認します。以後は通常の場周と同じで、余裕のある高度で第3旋回に入り、エアブレーキで高度を処理して接地させます。接地後は速やかに停止させ、必要なら着陸後に関係者へ連絡します。",
 s:"高度に余裕のあるうちに決めることが全てです。まだ十分な高度があるうちに決心し、大きさ、風向に対する向き、地面の状態、傾斜、進入経路上の障害物で場所を選びます。決めたら上空から場周経路を組み立て、以後は通常の場周と同じです。",
 rel:["場外離着陸場とは何ですか。", "風向が上空と地上とで異なります。どうしますか。", "アウトランディングで機体を壊し、負傷して動けません。早く救助される"],
 hint:"「早く決心する」ことが最優先だと言えているか。場所の選定基準（大きさ・風向・地面・傾斜・障害物）を複数挙げられているか。"},

{cat:"inflight", imp:2, examiner:["yuda"],
 q:"風向が上空と地上とで異なります。どうしますか。",
 a:"着陸の判断に使うのは地上付近の風です。上空の風は流されの計算や進入経路の組み立てに使いますが、接地の瞬間に効くのは地表付近の風だからです。したがって、煙、吹き流し、水面のさざ波、草木や作物の揺れといった地表付近の指標から風向を読み、それに合わせて着陸方向を決めます。そのうえで、上空と地上で風向が違うということは、進入中に風向・風速が変化する、つまりウインドシアがあるということなので、進入速度に余裕を持たせ、エアブレーキを使い切らずに残して進入します。",
 s:"着陸の判断に使うのは地上付近の風です。接地の瞬間に効くのは地表付近の風だからで、煙、吹き流し、水面のさざ波、草木の揺れから読みます。加えて、上空と地上で風向が違うのはウインドシアがあるということなので、進入速度に余裕を持たせ、エアブレーキを残して進入します。",
 rel:["アウトランディングする際の手順を説明してください。", "ウインドソック（吹き流し）で風速はどのように判断しますか。", "推奨進入速度は何ktですか。"],
 hint:"「着陸判断は地上の風」と言い切れているか。風向の差＝ウインドシアと読み替え、進入速度に余裕を持たせるところまで言えているか。"},

{cat:"weather", imp:2, examiner:["yuda"],
 q:"下層での境界層の高さはどのくらいですか。",
 a:"大気境界層（下層の混合層）の上端の高さは、気象条件や季節、時間帯によって大きく変わりますが、一般的な好天のフライト日和であれば地表から高度約1,000mから2,000m程度に達します。この境界層の最上部（境界層高度、BLトップ）は、日中の地表加熱で発生したサーマルが到達する限界点、つまり対流の天井を意味し、グライダーにとっては今日どこまで高く登れるかの重要な目安になります。夏の強い日射や乾燥した地域では条件が良いと3,000から4,000m、海外の砂漠地帯などでは5,000m近くまで押し上げられることもある一方、冬場や日射の弱い日は境界層の発達が鈍く数百mから1,000m未満にとどまり、夜間・早朝は放射冷却で大気が安定するため地表付近の数十mから200m程度まで一気に収縮します。グライダー飛行における重要性は2つあります。1つ目はサーマルトップ、つまり上昇の限界で、グライダーがサーマルを利用して旋回上昇できるのは、原則としてこの境界層のトップ、または雲が発生している場合は雲底高度までです。2つ目は乱気流と風の変化で、境界層の内部は地表の摩擦や熱対流によって空気が激しくかき混ぜられており、ガストやサーマルによる揺れがありますが、この境界を突き抜けて上の自由大気に出ると空気は非常にスムーズになります。",
 s:"好天日には地表から約1,000〜2,000m程度に達し、この境界層の最上部（BLトップ）がサーマルの到達する限界、つまり今日どこまで登れるかの目安になります。",
 note:"「境界層の高さ」は条件によって変わる量で、飛行規程や告示に定まった数値があるわけではありません。上の値は一般的な目安です。滝川での実際の値は、RASPのBLトップやサーマルトップの予想図で日々確認してください。",
 rel:["風向が上空と地上とで異なります。どうしますか。", "サーマルはどのように見つけますか。", "ソアリングにはどのような種類がありますか。"],
 hint:"好天日で1,000〜2,000m程度という目安と、境界層トップ（BLトップ）がサーマルの到達限界＝今日登れる高さの目安になるという理解、季節・時間帯による大きな変動（夏3,000〜4,000m、夜間・早朝は数十m〜200m）、境界層内の乱気流と自由大気でのスムーズさの違いのいずれかに触れているか。"},

// 曳航・速度超過
{cat:"aircraft", imp:3, examiner:["yuda"],
 q:"曳航中に最大曳航速度を超えそうになりました。どうしますか。無線のコールは「速い」ですか、「遅く」ですか。",
 a:"「遅く」です。無線は相手にしてほしい操作を伝えるものなので、曳航機に減速を求める以上、「遅く」と伝えます。「速い」では現状を述べているだけで、曳航機が加速すべきなのか減速すべきなのかが伝わりません。ASK21の最大航空機曳航速度は97kt（180km/h）です。まず無線で「遅く」と伝え、それでも速度が下がらず超過してしまうようなら、機体を守るために離脱します。",
 s:"「遅く」です。無線は相手にしてほしい操作を伝えるものだからです。",
 rel:["速度超過の合図を出したいが無線が通じません。", "ASK21の速度限界にはどのようなものがありますか。", "曳航中の合図にはどのようなものがありますか。"],
 hint:"「遅く」と即答できているか。状態ではなく相手にしてほしい操作を伝える、という理由まで説明できているか。"},

{cat:"aircraft", imp:3, examiner:["yuda"],
 q:"速度超過の合図を出したいが無線が通じません。その時の合図は何ですか。スタンダードシグナルを説明してください。",
 a:"滑空機側から曳航機へ減速を求める合図は、ヨー、つまりラダーを使って機体を左右に振ることです。曳航機側からもバックミラーや振り返りで見える動きなので伝わります。これに対して、翼を大きく振る合図は離脱の要求や異常の通知に使われます。合図は運航者によって定めが異なる場合があるので、曳航前の打ち合わせで、どの動きが何を意味するかを必ず確認しておきます。合図が通じない、または状況が悪化するようなら、最後は自分の判断で離脱します。",
 s:"減速を求める合図は、ラダーを使って機体を左右に振ることです。翼を大きく振るのは離脱の要求や異常の通知です。合図は運航者ごとに違うことがあるので、曳航前の打ち合わせで必ず確認します。",
 note:"合図の割り当ては運航者ごとの取り決めによる部分があります。滝川での定めを、曳航前の打ち合わせと運航規程で必ず確認してください。",
 rel:["曳航中に最大曳航速度を超えそうになりました。", "曳航中の合図にはどのようなものがありますか。", "曳航前の打ち合わせで確認しておくべきエマージェンシー項目"],
 hint:"具体的な動き（ラダーで機体を振る）を挙げられているか。合図の定めは運航者ごとで、事前の打ち合わせが前提だと言えているか。"},

{cat:"aircraft", imp:2, examiner:["yuda"],
 q:"航空機曳航のウィークリンク（ヒューズ）は何色ですか。荷重値はいくつですか。",
 a:"ASK21の飛行規程では、航空機曳航用の曳航索安全装置は最大600プラスマイナス60daNです。トストのウィークリンクは荷重値ごとに色分けされていて、600daNは青にあたります。ちなみにウィンチ曳航用は1000プラスマイナス100daNで、こちらが黒です。",
 note:"色の割り当てはトストの規格によるものです。実際に装着されているウィークリンクの色と刻印を、機体と一緒に必ず現物で確認してください。",
 rel:["ウインチ曳航（WT）のヒューズはなぜ2枚ついていますか。", "航空機曳航（AT）のロープにはヒューズが付いていませんが", "ヒューズの点検では具体的に何を確認しますか。"],
 hint:"600±60daNという数値が即答できているか。色（青）と、ウィンチ用1000daN＝黒との対比が言えるか。"},

// スピン／スパイラル
{cat:"emergency", imp:3, examiner:["yuda"],
 q:"スピンからスパイラルに移行したということは、何でわかりますか。",
 a:"速度と荷重倍数（G）の変化でわかります。スピンは主翼が完全に失速したまま回転している状態で、速度は失速速度付近で低いまま安定し、操縦桿の手応えはスカスカで、かかるGも1〜1.5G程度と小さめです。これに対してスパイラルは失速が解けて翼が揚力を発生している急旋回降下なので、速度計の針が猛烈に上がり続け、操縦桿は重く手応えがあり、体には強いGがかかります。つまり回転が続いたまま速度計の針が上がり続け、Gも増えてきたら、スピンではなくスパイラルに移行したと判断します。ここでスパイラルへの移行に気づかずスピンの回復操作（逆ラダー等）を続けると、速度が超過禁止速度VNEを超えて機体が空中分解したり、過大なGで主翼が折れたりする危険があります。速度計が勢いよく上がり始めたら、直ちにエアブレーキを展開して速度を抑え、バンクを戻してから慎重に引き起こします。",
 s:"速度とG（荷重倍数）でわかります。スピンは失速したままなので速度は低いまま一定で、Gも小さめです。スパイラルは失速が解けているので速度もGも増え続けます。回転したまま速度計が上がり続けたらスパイラルへの移行です。",
 rel:["スパイラルからの回復手順を説明してください。", "スピンはどのような状況で起こりやすいですか"],
 hint:"速度が増え続けること、Gが増えること、操縦桿の手応えが重くなることのいずれかでスパイラルと判断できているか。スピンの回復操作を続ける危険性（VNE超過・過大Gでの破損）と、正しい対処（エアブレーキ展開→バンク修正→慎重な引き起こし）に触れられているか。"},

{cat:"emergency", imp:3, examiner:["yuda"],
 q:"スパイラルからの回復手順を説明してください。",
 a:"スピンの回復操作とは違います。スパイラルは失速しておらず速度が急激に増加するため、まず速やかにエアブレーキを展開して過速度を防ぎます。次にエルロンでバンクを水平に戻します。バンクが戻ってから、操縦桿を優しく引いて機首を引き起こし、水平飛行に戻します。バンクが深いまま引き起こそうとすると、旋回がきつくなって速度もGも増え、構造の制限を超えるおそれがあります。対気速度計を見て制限速度を超えないよう注意し、急に操縦桿を引いて過大なGをかけないようにします。",
 s:"スピンとは違い、まずエルロンでバンクを水平に戻し、機首を起こして速度過度を防ぐ操作を行います。バンクが深いまま引くと速度もGも増え、構造の制限を超えるおそれがあります。",
 rel:["スピンからスパイラルに移行したということは、何でわかりますか。", "この機体（ASK21）の荷重制限（制限荷重倍数）", "スピンはどのような状況で起こりやすいですか"],
 hint:"「エアブレーキ展開→バンク修正→引き起こし」という順序が言えているか。バンクが深いまま引くと速度もGも増える、という理由と、速度・Gの制限に注意する点まで説明できているか。"},

// サブG（マイナスG）
{cat:"weather", imp:2, examiner:["yuda"],
 q:"サブG（マイナスG）のトレーニングを最後にやったのはいつですか。サブGの耐性は、トレーニングの間隔が開くとどうなりますか。どういうケースなら再トレーニングが必要ですか。",
 a:"サブGは0G以上1G未満の状態を指し、必ずしもマイナスG（0G未満）とは限りません。耐性はトレーニングの間隔が開くと確実に低下し、体が慣れるのが早い分、忘れるのも早いという特徴があります。間隔が開いた状態で急な低重力にさらされると、サブGセンセーション（恐怖感やパニック）を強く感じやすくなり、その驚きから操縦かんを強く握りしめる、過剰に押し下げる、あるいは強く引き起こすといったパニック・リアクションを起こしやすくなります。これが意図しない急降下（サブGダイブ）や失速を招くため危険です。正しい対処は操縦かんを急激に動かさないことで、必要であればわずかに引く操作にとどめます。再トレーニングが必要なのは、長期のフライトブランク（冬期明けなど）の後、ウインチ曳航を再開するとき（索離脱の瞬間に強いサブGが発生しやすい）、荒れた気象条件（強いサーマルやガスト）で飛ぶ前、曲技飛行を再開する前、機種を変えたとき、そしてフライト中に強い恐怖感やすくみを感じたときです。最後のケースでは無理に一人で飛ばず、教官と再訓練をやり直すべきです。",
 s:"サブGは0G以上1G未満の状態です。耐性は間隔が開くと確実に低下し、久しぶりだとサブGセンセーション（恐怖感）を強く感じてパニック・リアクション（操縦かんを強く押す・引く）を起こしやすくなります。正しくは急激に動かさず、必要ならわずかに引く程度にとどめます。再トレーニングが必要なのは、長期ブランクの後、ウインチ曳航の再開時、荒天飛行の前、曲技飛行の再開前、機種を変えたとき、そしてフライト中に強い恐怖感を感じたときです。",
 note:"「サブG」の訓練内容と実施間隔の基準は、所属する運航者・クラブの訓練規程によります。滝川での定めを教官に確認してください。",
 rel:["この機体（ASK21）の荷重制限（制限荷重倍数）", "錯覚にはどのようなものがありますか。", "低酸素症（ハイポキシア）とは何ですか。"],
 hint:"「サブGは0G以上1G未満」という定義、間隔が開くと耐性が落ちてパニック・リアクション（操縦かんの誤操作）を招きやすいこと、正しい対処（急激に動かさずわずかに引く程度）、再訓練が要る複数の場面（ブランク後、ウインチ再開時、荒天前、曲技再開前、機種変更時、恐怖感を感じたとき）のいずれかに触れているか。"},

// 機体・書類
{cat:"aircraft", imp:2, examiner:["yuda"],
 q:"航空機の種類にはどのようなものがありますか。その中でASK21はどれに該当しますか。ASK21の種類と型式は何ですか。",
 a:"航空法上の航空機の種類は、飛行機、回転翼航空機、滑空機、飛行船の4つです。ASK21はこのうち滑空機に該当します。飛行規程では、種類が滑空機、型式がASK21と記載されています。滑空機の中の区分としては上級滑空機で、耐空類別は滑空機 実用Uです。",
 rel:["ASK21の耐空類別は何ですか。", "滑空機の等級にはどのようなものがありますか。", "ASK21はどのような航空機ですか。"],
 hint:"航空機の種類4つを挙げられているか。「種類＝滑空機／型式＝ASK21」という言い方ができているか。種類・等級・耐空類別を混同していないか。"},

{cat:"departure", imp:2, examiner:["yuda"],
 q:"最小装備品がすべて揃っているかどうかは、どうやって確認していますか。",
 a:"飛行規程の第2章にある最少装備品の一覧と、実機のコクピットとを突き合わせて確認します。速度計と高度計は目視で作動と指示を、シートベルトは4点式であることと各部の状態を、パラシュートまたはシートクッションは装着と厚みを、重量重心プラカードとデータプレートは掲示されていることを、そして飛行規程を確認します。ただし飛行規程については、機体に積む必要はありません。飛行規程 第2章の最少装備品は、この機体が耐空性を持つための要件としての一覧であって、日本の航空法上の書類の搭載義務とは別のものです。滑空機は航空法施行規則第143条により搭載が免除されているので、地上に整えておいて現物で確認します。曲技飛行を行うなら、Gメーター、フロアハーネス、ラダーペダルストラップ、パラシュートの4つが加わります。",
 s:"飛行規程 第2章の最少装備品の一覧と、実機のコクピットを突き合わせて確認します。速度計と高度計は作動と指示、シートベルトは4点式であること、パラシュートまたはシートクッション、重量重心プラカードとデータプレートの掲示、そして飛行規程です。飛行規程は搭載が免除されているので、地上で現物を確認します。",
 rel:["ASK21の通常飛行における最少装備品を挙げてください。", "曲技飛行を行うために追加で必要な装備品は何ですか。", "機長の出発前確認事項（航空法第73条の2）の項目を"],
 rel:["最少装備品に飛行規程が入っていますが、滑空機は搭載が免除されているのではありませんか。", "ASK21の通常飛行における最少装備品を挙げてください。", "曲技飛行を行うために追加で必要な装備品は何ですか。"],
 hint:"「飛行規程の一覧と実機を突き合わせる」という手順が言えているか。飛行規程は搭載が免除されている点を押さえているか。"},

{cat:"emergency", imp:2, examiner:["yuda"],
 q:"重心位置が前方限界の近くにあったら、スピンには入らないのですか。",
 a:"入りにくくはなりますが、「前方限界の近くだから入らない」と言い切ることはできません。飛行規程が示しているのは、基準点後方315mmより前方であればスピンに入ることはない、という値です。許容重心位置範囲の前方限界は基準点後方234mmですから、確かに前方限界の付近であれば315mmより前方に収まります。ただし重心位置は搭乗者の体重や固定バラストの枚数で変わりますし、実際に何mmになっているかは重量重心の計算をして初めて分かります。ですから、位置関係として入りにくい、と答えたうえで、根拠となる315mmという数値と、自分の搭乗形態での計算結果を示すのが正確です。",
 s:"入りにくくはなりますが、入らないと言い切ることはできません。飛行規程が示しているのは、基準点後方315mmより前方であればスピンに入ることはない、という値です。前方限界は234mmなので確かにその前方に収まりますが、実際に何mmかは重量重心の計算をして初めて分かります。",
 rel:["重心位置が後方限界に近いと、スピンに入りやすくなりますか。", "ASK21の許容重心位置範囲を答えてください。", "固定バラストの重量とアーム（モーメント）の関係"],
 hint:"「入らない」と断言せず、315mmという根拠の数値を挙げられているか。前方限界234mmとの位置関係を説明できているか。"},

{cat:"airspace", imp:3, examiner:["yuda"],
 q:"滝川では300m以上が航空交通管制区とのことですが、その管制区に入るにはどうすればよいのですか。",
 a:"管制機関の許可は要りません。管制区は計器飛行方式の航空機のために設定された空域で、管制圏のように進入に管制承認が必要な空域ではないからです。有視界飛行方式で入るために必要なのは3つです。1つ目、その空域のVMCを満たすこと。管制区内では、高度3,000m未満で雲から上方150m・下方300m・水平600mの距離を保ち、飛行視程は5,000m以上が必要です。クラスGの300m以下では雲から離れて視程1,500m以上でよかったので、300mの線を越えると基準が厳しくなります。2つ目、装備です。高度10,000ft以上を飛ぶならトランスポンダが必要になります。この10,000ftは、告示上は日本の計量法に合わせて「3,000m」と定められていますが、航空の実務では国際標準であるフィート表記が使われるため、換算した「10,000ft」という基準で広く運用されています。3つ目、操縦の練習等のための飛行として飛ぶ場合は、航空法第92条第1項ただし書の許可が必要です。滝川はこの許可を受けていて、たきかわスカイパークを中心とする半径9km以内、高度4,000ft MSL以下の空域で、日の出から日没までとされています。まとめると、通常のソアリングで上がるぶんには許可は不要でVMCの切り替わりに注意すればよく、訓練として飛ぶなら92条の許可の範囲内で飛ぶ、ということになります。",
 s:"許可は要りません。管制区は計器飛行方式のための空域で、管制圏のような進入承認は要らないからです。必要なのは3つ、その空域のVMCを満たすこと、10,000ft以上ならトランスポンダ、訓練として飛ぶなら92条の許可です。",
 rel:["滝川滑空場では、何m以上が航空交通管制区になりますか。", "高度3,000m未満におけるVMCの気象条件を", "92条の操縦練習飛行等許可について、内容を説明してください。", "管制区と管制圏の違いを説明してください。"],
 hint:"「許可は要らない」と言い切れているか。そのうえでVMCの切り替わり、10,000ft以上のトランスポンダ、訓練飛行なら92条の許可、という3点を整理できているか。"},

{cat:"airspace", imp:2, examiner:["yuda"],
 q:"滝川滑空場の特性と利用法について説明してください。ソアリングだけでなく、地形や空域についても説明してください。",
 a:"3つの層に分けて説明します。まず地形です。滝川は石狩平野の北部、石狩川と空知川が合流するあたりの河川敷にあります。西側には樺戸山地のピンネシリ、約1,100mがあり、そこから北へ増毛山地の暑寒別岳、約1,492mへと連なります。東側には夕張山地の芦別岳、約1,726mや夕張岳があり、さらにその奥、東から北東にかけて大雪山系があります。つまり東西を山地に挟まれた平野のまん中という地形です。西側の山地は北西から西の風のときにリッジやウェーブの源になり、平野部は日射でサーマルが立ちます。位置回復のランドマークとしても、石狩川の独特な蛇行の形と、大雪山系、暑寒別岳、ピンネシリの方角が使えます。次に空域です。滑空場周辺は管制圏でも情報圏でもないクラスGで、300mより上が航空交通管制区になります。管制区に入るのに許可は要りませんが、VMCの基準がクラスGのものから管制区のものへ切り替わります。訓練として飛ぶ場合は航空法第92条の許可の範囲内、つまり半径9km以内・4,000ft MSL以下で飛びます。周辺の空港との位置関係、訓練空域の設定も押さえておきます。最後に利用法です。ウインチ曳航と航空機曳航の両方が可能で、滑走路は河川敷に沿った向きなので、横風になりやすい風向があります。クロスカントリーに出る場合は、9kmを超えるならフライトプランが必要になります。",
 s:"地形、空域、利用法の3つで説明します。地形は、石狩平野の北部、東西を山地に挟まれた平野です。西の樺戸山地と増毛山地がリッジやウェーブの源になり、平野部は日射でサーマルが立ちます。空域はクラスGで、300mより上が航空交通管制区。訓練として飛ぶなら92条の許可の範囲、半径9km以内・4,000ft MSL以下です。利用法は、ウインチと航空機曳航の両方が可能で、9kmを超えるならフライトプランが必要です。",
 rel:["滝川滑空場では、何m以上が航空交通管制区になりますか。", "ソアリングにはどのような種類がありますか。", "フライトプランはどのような場合に必要ですか。"],
 hint:"地形・空域・利用法の3層に整理できているか。山の名前と方角を取り違えていないか。暑寒別岳とピンネシリは西側（増毛山地・樺戸山地）、芦別岳・夕張岳は東側（夕張山地）、その奥が大雪山系。ソアリングの話だけに寄っていないか。管制区の下限高度に触れられているか。"},

{cat:"departure", imp:3, examiner:["shorui"],
 q:"機体に備え付ける書類を、根拠条文とあわせてすべて挙げてください。",
 a:"7つです。航空法第59条によるものが3つで、航空機登録証明書、耐空証明書、航空日誌。航空法施行令第144条によるものが3つで、運用限界等指定書、飛行規程、そして飛行区間・飛行方式その他飛行の特性に応じて適切な航空図です。これに無線局免許状が加わります。ただし滑空機は航空法施行規則第143条により、これらの搭載が免除されています。免除されているのは「搭載」であって、書類そのものが不要になるわけではないので、実際には地上の事務所に整えておき、出発前確認ではそれを現物で確認します。",
 s:"7つです。第59条で航空機登録証明書、耐空証明書、航空日誌。施行令第144条で運用限界等指定書、飛行規程、航空図。これに無線局免許状が加わります。ただし滑空機は施行規則第143条で搭載が免除されています。",
 rel:["滑空機は、備え付けが義務付けられている書類を機体に搭載しなくてもよいのですか。", "航空機登録証明書には何が書かれていますか。", "運用限界等指定書には何が書かれていますか。"],
 hint:"法59条の3つと令144条の3つを区別できているか。規則143条で免除されるのは「搭載」であるという理解があるか。"},

{cat:"departure", imp:2, examiner:["shorui"],
 q:"航空機登録証明書には何が書かれていますか。",
 a:"登録番号、国籍記号および登録記号、航空機の型式、製造番号、所有者の氏名と住所、発行年月日です。JA20HCでは登録番号が5824、型式がアレキサンダー・シュライハー式ASK21型、製造番号21740、所有者が公益社団法人 滝川スカイスポーツ振興協会、発行が平成28年11月24日です。所有者を示す書類であって、耐空性を示すものではない点が耐空証明書との違いです。",
 s:"登録番号、国籍記号および登録記号、航空機の型式、製造番号、所有者の氏名と住所、発行年月日です。所有者を示す書類であって、耐空性を示すものではない点が、耐空証明書との違いです。",
 rel:["機体に備え付ける書類を、根拠条文とあわせてすべて挙げてください。", "耐空証明書には何が書かれていますか。"],
 hint:"登録番号・登録記号・型式・製造番号・所有者の5点が挙げられているか。「所有者を示す書類」という位置づけが言えるか。"},

{cat:"departure", imp:2, examiner:["shorui"],
 q:"耐空証明書には何が書かれていますか。",
 a:"耐空証明書番号、国籍記号および登録記号、航空機の型式および製造者、製造番号、耐空類別、耐空検査員、発行年月日、そして耐空証明有効期間です。JA20HCでは番号が第2026-55-06号、型式がアレキサンダー・シュライハー式ASK21型、製造者は西ドイツ国アレキサンダー・シュライハー社、製造番号21740、耐空類別が滑空機 実用U、発行が2026年4月10日、有効期間が2027年4月25日までです。証明書の本文には、国際民間航空条約と航空法の規定に従って交付するもので、指定した用途及び運用限界に従って整備し運用するときは耐空性を有することを証明する、と書かれています。",
 s:"耐空証明書番号、国籍記号および登録記号、型式および製造者、製造番号、耐空類別、耐空検査員、発行年月日、耐空証明有効期間です。本文には、指定した用途及び運用限界に従って整備し運用するときは耐空性を有する、と書かれています。",
 rel:["耐空証明書があれば、どんな整備・運用状態でも耐空性を有するといえますか。", "運用限界等指定書には何が書かれていますか。", "航空機登録証明書には何が書かれていますか。"],
 hint:"番号・耐空類別・有効期間の3つが即答できるか。「用途及び運用限界に従って」という条件付きの証明であることに触れられるか。"},

{cat:"departure", imp:2, examiner:["shorui"],
 q:"運用限界等指定書には何が書かれていますか。根拠条文は何ですか。",
 a:"航空法第10条第3項により、その航空機の用途と運用限界を指定する書面です。書かれているのは、型式・国籍記号および登録記号・製造番号・耐空証明書番号・用途・運用限界です。JA20HCでは用途が耐空類別 実用U、運用限界は「飛行規程の第2章」と指定されており、運用限界の中身自体は書かれていません。",
 s:"航空法第10条第3項により、用途と運用限界を指定する書面です。JA20HCでは用途が耐空類別 実用U、運用限界は「飛行規程の第2章」と書かれています。",
 rel:["耐空証明書には何が書かれていますか。", "運用様式限界とは何ですか。", "飛行規程の第1章から第5章には"],
 hint:"「用途と運用限界を指定する書面」であること、運用限界の中身は飛行規程第2章を指していることが言えているか。"},

{cat:"departure", imp:2, examiner:["shorui"],
 q:"無線局免許状には何が書かれていますか。",
 a:"免許人の氏名、住所、無線局の種別、免許の番号、免許の年月日と有効期間、無線局の目的、通信事項、通信の相手方、識別信号、無線設備の設置場所、電波の型式・周波数・空中線電力です。JA20HCは種別が航空機局、免許の番号が北空第86号、有効期間は無期限、運用許容時間は常時、目的は一般業務用です。識別信号はJA20HCと、もう1つ数字の呼出名称があり、こちらはATCトランスポンダのモードSを使用する場合に限る、と注記されています。電波はA3Eが118MHzから155.975MHzの帯で5W、V1Dが1090MHzで250W。この1090MHzがモードSとADS-Bの周波数です。",
 s:"免許人、無線局の種別、免許の番号、有効期間、目的、通信事項、通信の相手方、識別信号、設置場所、電波の型式・周波数・空中線電力です。JA20HCは航空機局、免許の番号は北空第86号、有効期間は無期限、識別信号はJA20HCです。",
 rel:["機体に備え付ける書類を、根拠条文とあわせてすべて挙げてください。", "進入管制区を飛行する場合はどのような装置が必要ですか。"],
 hint:"航空機局・免許番号・識別信号の3点が言えているか。数字の呼出名称がモードS用であること、1090MHzがトランスポンダの周波数であることに触れられるか。"},

// B. 整備状況
{cat:"departure", imp:3, examiner:["shorui"],
 q:"整備状況として何を確認しますか。総飛行時間はどこを見ますか。",
 a:"整備状況の確認は6点です。耐空証明が有効期間内であること、前回耐空検査後の飛行時間・回数から次回検査まで本日のフライト分の余裕があること、組立後点検・始業点検が資格者の署名付きで記録されていること、報告された不具合が整備士の確認（リリース）まで完了していること、TCD・サービスブレティンの実施状況、大きな修理の履歴です。JA20HCは総飛行時間9,026時間26分・25,966回、耐空検査後192時間29分・588回、前回耐空検査2026年4月10日、TCD3990-2001による3,000時間点検を2026年4月4日に実施済み、前回検査後の整備・大きな修理・サービスブレティンはいずれもなしです。総飛行時間は、航空日誌『飛行に関する記録』の最新ページ下部（または次ページへの繰越欄）にある累計値で確認します。",
 s:"6点確認します。耐空証明の有効期間内であること、次回耐空検査までの余裕、始業点検の署名記録、不具合の整備士確認、TCD・サービスブレティンの実施、大きな修理の履歴です。JA20HCは総飛行時間9,026時間26分・25,966回、耐空検査後192時間29分・588回。総飛行時間は航空日誌『飛行に関する記録』最新ページの累計欄で確認します。",
 rel:["TCD（耐空性改善通報）とは何ですか。", "3,000時間点検では何を交換しましたか。", "航空日誌にはどのようなことを記載しますか。"],
 hint:"耐空証明の有効期間と、耐空検査後の飛行時間・回数（次回検査までの余裕）を分けて言えるか。総飛行時間の参照箇所（航空日誌『飛行に関する記録』の累計欄）を具体的に言えるか。TCD・SB・大きな修理という3つの履歴確認に触れられるか。"},

{cat:"departure", imp:2, examiner:["shorui"],
 q:"TCD（耐空性改善通報）とは何ですか。JA20HCで現在有効なものはありますか。",
 a:"TCDは耐空性改善通報で、その型式の航空機に安全上の不具合が見つかったときに、国土交通大臣が改善のための整備や検査を義務づけるものです。適用区分は機体がA、発動機がE、プロペラがP、その他がCです。JA20HCの耐空検査準備作業報告書には11件のTCDが記載されていますが、多くは初回処置が終了しているか非該当です。現在も繰り返し処理が必要なのは3990-2001で、適用区分はC、その他です。これは3,000時間毎の点検を求めるもので、2010年4月11日と2026年4月4日に実施しています。点検の中身は、耐空検査準備作業報告書の作業の概要に「TCD 3990-2001（TN29 extension of service life beyond 12,000 hours による3,000時間点検）」と書かれているとおり、アレキサンダー・シュライハー社のテクニカルノート29が定める、使用時間を延長するための機体の点検です。FRP機は設計上の使用時間に限りがあり、3,000時間ごとにこの点検を受けて延長していく、という位置づけになります。",
 s:"耐空性改善通報で、その型式に安全上の不具合が見つかったとき、国土交通大臣が改善のための整備や検査を義務づけるものです。JA20HCで現在も繰り返し処理が必要なのは3990-2001で、適用区分はC、その他です。3,000時間毎の点検を求めるもので、2026年4月4日に実施しています。中身はシュライハー社のテクニカルノート29による、使用時間を延長するための機体の点検です。",
 rel:["整備状況として何を確認しますか。", "3,000時間点検では何を交換しましたか。", "耐空証明書があれば、どんな整備・運用状態でも耐空性を有するといえますか。"],
 hint:"「国が義務づける改善通報」という位置づけが言えているか。JA20HCで生きているのが3990-2001の3,000時間毎であることを挙げられるか。"},

{cat:"departure", imp:1, examiner:["shorui"],
 q:"3,000時間点検では何を交換しましたか。",
 a:"8点です。ラバーショック・アブソーバー、ラダー・ケーブル、ラダー・ペダル・ブッシング、レリーズ・ケーブル、ボール・ジョイント、ブレーキ・ディスク、ブレーキ・キャリパーのOリング、主脚フォークの取付ボルトとブッシングです。作業は2025年12月1日から2026年4月4日にかけて、たきかわスカイパーク内の格納庫で実施し、あわせて重量重心の測定、シートベルトとショルダーハーネスの12年毎のオーバーホール、サーキュラーによる高度計の2年点検も行っています。部品にはEASA FORM 1が付いています。",
 s:"8点です。ラバーショック・アブソーバー、ラダー・ケーブル、ラダー・ペダル・ブッシング、レリーズ・ケーブル、ボール・ジョイント、ブレーキ・ディスク、ブレーキ・キャリパーのOリング、主脚フォークの取付ボルトとブッシングです。2026年4月4日までに実施しました。",
 rel:["TCD（耐空性改善通報）とは何ですか。", "整備状況として何を確認しますか。"],
 hint:"操縦系統（ラダーケーブル・レリーズケーブル）と脚まわり（ブレーキ・主脚フォーク）という2系統に整理して挙げられているか。"},

{cat:"departure", imp:2, examiner:["shorui"],
 q:"装備品の使用期限はどのように管理していますか。",
 a:"2種類あるので、分けて管理します。1つはカレンダーで追うもので、義務無線機が1年、高度計とトランスポンダが2年、シートベルト・ショルダーハーネス・ボトムストラップが12年。1年・2年・12年の3段です。もう1つが発航回数で追うもので、曳航用レリーズの2,000発航。これだけカレンダーではなく航空日誌の発航回数で数えます。JA20HCの現況は、無線機が2026年3月21日で2027年3月21日まで、高度計が2026年4月4日実施で2028年4月4日まで、縛帯類が2026年4月4日交換で2038年まで、レリーズが2025年6月1日交換で使用回数が851回、2,000回まであと1,149回です。いちばん先に来るのが無線機の2027年3月なので、そこを起点に見ています。",
 s:"2種類あります。カレンダーで追うものが、義務無線機1年、高度計とトランスポンダ2年、シートベルト類12年。発航回数で追うものが曳航用レリーズの2,000発航で、これだけ航空日誌の発航回数で数えます。いちばん先に来るのが無線機の2027年3月です。",
 rel:["レリーズの使用回数には制限がありますか。", "グライダーの定期交換部品（いわゆるカレンダー部品）には", "救急用具には具体的にどのようなものが積まれていますか。"],
 hint:"カレンダーで追うものと発航回数で追うものに分けられているか。1年・2年・12年の3段（無線機・高度計/トランスポンダ・縛帯類）が言えるか。レリーズが回数管理である点を落としていないか。"},

{cat:"departure", imp:2, examiner:["higuchi"],
 q:"組み立てのたびに検査を受けなくてもよいのはなぜですか。",
 a:"根拠は航空法第17条の修理改造検査と、その基準を定める航空法施行規則第24条です。法は「機体を修理・改造したときは国の検査（修理改造検査）に合格しなければ飛行させてはならない」と定めていますが、日常の組み立て・分解はこの検査を要する修理・改造の範囲にそもそも該当しません。決まった手順でピンを差し込み固定するだけの軽微な保守であり、機体の性能や強度に影響を与える改造ではないためです。一方、タイヤ交換のような一般的な保守は整備士が行うべき作業です。",
 s:"組み立て・分解は、航空法第17条の修理改造検査（施行規則第24条）を要する範囲に該当しない軽微な保守だからです。決まった手順でピンを差し込むだけで、性能や強度に影響する改造ではありません。",
 rel:["主翼の組立要領について説明してください。", "装備品の使用期限はどのように管理していますか。"],
 hint:"法的根拠（航空法第17条の修理改造検査・施行規則第24条）を挙げられるか。組み立ては軽微な保守にあたり検査の対象範囲に該当しないこと、一般的な保守（タイヤ交換など）は整備士が行うという区別が言えているか。"},

{cat:"departure", imp:3, examiner:["shorui"],
 q:"今日の離陸重量と重心位置を計算して示してください。",
 a:"前席が私で63kg、後席が教官で65kgとして計算します。重量は2つの上限で確認します。まず全体で、空虚重量385kg、固定バラスト4kg、前席63kg、後席65kg、パラシュート2人分10kg、搭載物0kgで合計527kg。最大離陸重量600kg未満です。次に揚力発生部を除いた部分で、192kg、4kg、63kg、65kg、10kg、0kgで合計334kg。こちらの上限410kg未満です。重心位置はモーメントで求めます。空虚重量385kgにアーム基準点後方751mm、前席はパラシュート込みの68kgに前方1180mm、後席は同じくパラシュート込みの70kgに前方80mm。固定バラストは実重量4kgですが、前席位置に換算すると5kg相当になるため、重心計算では前方1250mmに5kgとして扱います。モーメントの合計19万7,045kg・mmを総重量527kgで割ると、基準点後方およそ374mmとなります。許容重心位置範囲は基準点後方234mmから469mm、その中央が351.5mmですから、範囲内で中央よりやや後ろです。",
 s:"前席が私で63kg、後席が教官で65kgとして、重量は527kgで最大600kg未満、揚力発生部を除いた部分は334kgで上限410kg未満です。固定バラストは実重量4kgですが、重心計算では前席換算の5kg相当として扱います。重心はモーメントの合計を527kgで割って基準点後方およそ374mm、許容範囲234mmから469mmの中に収まっています。",
 rel:["今日の重心位置は、飛行規程4-6のどの範囲にあたりますか。", "ASK21の許容重心位置範囲を答えてください。", "重量限界にはどのようなものがありますか。", "重量重心の計測は何年ごとに行いますか。"],
 hint:"600kgと410kgの2つの上限を分けて確認しているか。重心をモーメントの合計÷総重量で求め、許容範囲と比較できているか。"},

{cat:"departure", imp:3, examiner:["shorui"],
 q:"今日の重心位置は、飛行規程4-6のどの範囲にあたりますか。スピンとの関係はどうなりますか。",
 a:"今日は前席が私で63kg、後席が教官で65kg、それぞれパラシュート5kgを加えて68kgと70kgです。固定バラストは実重量4kgですが、前席位置に換算すると5kg相当になるため、重心計算では5kgとして扱います。これで計算すると重心は基準点後方およそ374mmで、飛行規程4-6でいう320mmから385mmの範囲に入ります。これは、スピンに入りやすくなるが、最大4回半の旋転で自然に回復する、とされている範囲です。315mmより前方であればスピンに入ることはない、とされていますから、今日はそれより後ろです。許容重心位置範囲の234mmから469mmには余裕を持って収まっていますが、許容範囲内であることと、スピンに入りにくいことは別の話です。むしろ帯の中では上限の385mmに近い側なので、低高度での大きな舵や旋回中の失速には普段以上に注意し、万一入っても飛行規程3-1の4段階で回復できるよう、手順と高度損失およそ80m、約260ftを頭に入れておきます。前に寄せたければ、固定バラストを増やすか、前席により重い人が乗ることになります。なお飛行規程が挙げている「複座でも前席重量が小さい場合にこの傾向が考えられる」というのが、まさに今日の組み合わせです。前席68kgに対して後席70kgと、前が軽いためです。前席の最小重量については、パラシュートを含めて数えるかどうかで見え方が変わりますが、いまは固定バラストを4枚積んでいるので、どちらに読んでも最小重量は満たしています。",
 s:"前席が私で63kg、後席が教官で65kgで、パラシュート込みで68kgと70kgです。固定バラストは実重量4kgですが、重心計算では前席換算の5kg相当として扱います。重心は基準点後方およそ374mmで、4-6の320mmから385mmの範囲に入ります。スピンに入りやすくなるが、最大4回半の旋転で自然に回復する、とされている範囲です。許容範囲に収まっていることと、スピンに入りにくいことは別の話で、帯の中では後ろ寄りなので注意します。",
 rel:["今日の離陸重量と重心位置を計算して示してください。", "重心位置が後方限界に近いと、スピンに入りやすくなりますか。", "スピンはどのような状況で起こりやすいですか", "固定バラストの重量とアーム（モーメント）の関係を説明してください。"],
 hint:"320〜385mmの帯に入ることを認めたうえで、「最大4回半で自然回復する範囲」と正しく言えているか。許容範囲内であることとスピンに入りにくいことは別、と整理できているか。対処まで述べられるか。"},

{cat:"departure", imp:2, examiner:["shorui"],
 q:"重量重心の計測は何年ごとに行いますか。最後に測ったのはいつですか。",
 a:"4年ごとです。JA20HCは直近では2026年4月4日に、3,000時間点検にあわせて計測しています。そのときの自重は384.5kgで重心は基準点後方751mm、空虚時の重心範囲は750mmから774mmとされています。各部の重量は、主翼左が96.5kg、主翼右が96.0kg、水平安定板が14.5kg、胴体が177.5kgで、このうち揚力を負担しない部分は水平安定板と胴体を合わせた192.0kgです。最大搭載量は216kgです。原本には410kg引く191.5kgが600kg引く384kgより大きい、と書かれています。揚力を負担しない部分の上限410kgまではあと218.5kg積めるのに対し、最大離陸重量600kgまでは自重を引いてあと216kg。小さいほうが効くので216kgが最大搭載量になります。つまり216kgは600kgと自重の差から出た値で、410kg側から出た値ではありません。",
 s:"4年ごとです。直近は2026年4月4日に、3,000時間点検にあわせて計測しました。そのときの自重は384.5kg、重心は基準点後方751mmです。",
 rel:["今日の離陸重量と重心位置を計算して示してください。", "「揚力発生部を除いた部分の最大重量410kg」", "重量重心を計測するとき、機体の水平はどのように出しますか。"],
 hint:"4年ごとという周期が即答できるか。空虚重量384.5kg・重心751mmという実測値を挙げられるか。"},

{cat:"departure", imp:1, examiner:["shorui"],
 q:"重量重心チャートはどのように読みますか。",
 a:"JA20HCのチャートは単座用と複座用の2枚に分かれています。単座の図は横軸が搭乗者の体重、縦軸が重心位置で、座席最小70kgと最大110kgの縦線、前方限界234mmと後方限界469mmの横線で囲まれた範囲に、座席が最前方のときと最後方のときの2本の線が引かれています。体重が軽いほど重心は後ろへ、重いほど前へ動きます。複座の図は横軸が前席の体重、縦軸が後席の体重で、前席最前方1250mmと前席最後方1180mmの2本の境界線と、前席最大110kg、後席最大110kg、前方限界234mmの線で囲まれた範囲が使用可能な組み合わせになります。前席が軽いほど後席に乗れる重量が制限される、という読み方になります。",
 s:"単座用と複座用の2枚に分かれています。単座は横軸が搭乗者の体重、縦軸が重心位置で、体重が軽いほど重心は後ろへ動きます。複座は横軸が前席、縦軸が後席の体重で、前席が軽いほど後席に乗れる重量が制限される、という読み方になります。",
 rel:["今日の離陸重量と重心位置を計算して示してください。", "ASK21の許容重心位置範囲を答えてください。"],
 hint:"単座図と複座図で軸が違うことを説明できているか。前席の座席位置によって境界線が2本あることに触れられるか。"},

// D. 航空情報
{cat:"departure", imp:3, examiner:["shorui"],
 q:"航空情報はどこから、どのように入手していますか。",
 a:"SWIMから入手しています。確認するのは4種類です。航空路誌つまりAIPは、AIS Japanで2026年8月6日から有効のものを使っています。航空路誌改訂版のAIP Amendmentsは該当なし。航空路誌補足版のAIP Supplementsは該当空域なし。そしてNOTAMを飛行当日と翌日の分まで確認します。NOTAMは、SWIMのメニューからデジタルノータムリクエストサービスで見ます。加えて航空情報サーキュラーのAICと、訓練空域内の飛行情報をSWIMで確認します。AIPは28日ごとのAIRACサイクルで更新されるので、有効日が今日を含んでいるかを必ず見ます。",
 s:"SWIMから入手しています。",
 rel:["航空情報にはどのような種類があり、どのように更新されますか。", "ノータム（NOTAM）はどこで確認しますか。", "今日のNOTAMには何が出ていましたか。"],
 hint:"AIP・AIP Amendments・AIP Supplements・NOTAMの4種類を挙げられているか。SWIMという入手先と、AIPの有効日確認に触れられるか。NOTAMの確認方法（SWIMメニューのデジタルノータムリクエストサービス）まで説明できると加点。"},

{cat:"departure", imp:3, examiner:["shorui"],
 q:"今日のNOTAMには何が出ていましたか。どう対応しましたか。",
 a:"無人航空機の目視外飛行に関するNOTAMが1件出ていました。地表から1,411ftまで、機体重量2.5kg、時間帯は日本時間で7時から21時というものです。これに対しては、当日午後の運航について運航者に直接確認を取りました。あわせて、災害特例時にヒグマや河川氾濫等の対応で申請空域を逸脱して150m、500ftを飛行する場合があること、その発着空域が石狩川東河川敷の滝新橋から石狩橋の南北2km程度であること、運航する場合は事前に連絡を受ける予定であることを把握しています。また徳富川上空を60m、200ftで飛ぶ定期便については、当日は運航予定なしと確認しました。NOTAMは読んで終わりではなく、影響がありそうなら運航者に直接確認するところまでが確認です。",
 s:"無人航空機の目視外飛行のNOTAMが1件出ていました。地表から1,411ft、機体重量2.5kg、日本時間で7時から21時です。当日午後の運航について運航者へ直接確認を取りました。読んで終わりにせず、確認まで行うのが要点です。",
 rel:["ドローンが飛行しているという情報はどこから入手できますか。", "航空情報はどこから、どのように入手していますか。", "ノータム（NOTAM）はどこで確認しますか。"],
 hint:"無人航空機のNOTAMであることと、高度・重量・時間帯という3要素を読めているか。運航者へ直接確認したという行動まで言えているか。"},

{cat:"departure", imp:2, examiner:["shorui"],
 q:"航空情報サーキュラー（AIC）には、いまどのようなものが出ていますか。",
 a:"控えているのは4件です。目視外飛行を行う無人航空機に関する飛行情報の提供について。航空機への鳥衝突、バードストライク等が発生した場合の報告について。航空安全情報自発申告制度、VOICESについて。そして有視界飛行方式により飛行する航空機の異常接近対策についてです。AICはNOTAMのように直ちに飛行を制約するものではなく、方式や制度の周知が中心ですが、バードストライクの報告手順やVOICESのように、実際に事が起きたときの行動を定めているものがあるので、内容を知っておく必要があります。",
 s:"控えているのは4件です。目視外飛行を行う無人航空機に関する飛行情報の提供。バードストライク等が発生した場合の報告。航空安全情報自発申告制度、VOICES。そして有視界飛行方式の航空機の異常接近対策です。",
 rel:["航空情報にはどのような種類があり、どのように更新されますか。", "飛行中にバードストライク（鳥との衝突）が発生した場合、届出は必要ですか。", "航空情報はどこから、どのように入手していますか。"],
 hint:"4件のうち2件以上を挙げられるか。AICの性格（直ちに制約するものではなく周知が中心）を説明できるか。"},

{cat:"law", imp:3, examiner:["shorui"],
 q:"92条の操縦練習飛行等許可について、内容を説明してください。",
 a:"航空法第92条に基づく「操縦練習飛行等許可」は、航空交通管制区や航空交通管制圏などの混雑した空域で、資格のない訓練生が操縦練習をしたり、急激な姿勢変更などの危険な飛行を行ったりする場合に、国土交通大臣から受ける必要がある許可です。同条第1項は、安全確保のため、管制区・管制圏で①無資格者による操縦練習（操縦技能証明を持たない人が機体に乗り込んで行う操縦練習）、②限定外の航空機の操縦練習（資格があってもその資格で認められていない種類の航空機での練習）、③交通の安全を阻害するおそれのある飛行（機体の姿勢をひんぱんに変える、失速を伴う、高度を急激に変更するなど施行規則で定める危険な飛行）を原則禁止とし、ただし書の許可を受ければ例外的に認めています。滝川スカイスポーツ振興協会は令和8年6月13日付の滝スカ第11号で申請し、東京航空局長が令和8年6月30日付の東空運航第13860号で許可しています。許可書そのものは「申請のとおり許可する」という一枚で、書かれている条件も1つだけです。ですから許可の中身は申請書の記載がそのまま効いています。飛行目的は技能証明および限定変更に係わるトレーニング。日時は令和8年7月1日から9月30日まで、そのうち日の出から日没まで。空域はたきかわスカイパークを中心とする半径9km以内、高度4,000ft MSL以下です。期間が3か月と短いのは、これが継続申請だからで、申請書には前回許可が令和8年3月27日付の東空運航第48227号、初回許可が平成元年3月28日付の東空運第2686号と書かれています。期間を区切って更新を重ねているということです。対象機はASK21を含む12機が別紙で指定され、JA20HCはモードSトランスポンダ装備として載っています。関係機関との調整として、東京航空局新千歳空港事務所、陸上自衛隊北部方面管制気象隊、ATMセンターと調整済みで、滑空場周辺の訓練飛行には訓練計画書の提出は不要とされています。",
 s:"航空法第92条に基づく「操縦練習飛行等許可」は、管制区・管制圏で無資格者の操縦練習や危険な飛行等を行う場合に国土交通大臣から受ける許可です。滝川スカイスポーツ振興協会が申請し、東京航空局長が許可しています。許可書は「申請のとおり許可する」という形なので、中身は申請書のとおりで、日時は令和8年7月1日から9月30日まで、そのうち日の出から日没まで。空域はたきかわスカイパークを中心とする半径9km以内、4,000ft MSL以下です。期間が3か月なのは継続申請で、期間を区切って更新を重ねているためです。",
 rel:["92条の許可には、どのような条件が付いていますか。", "滝川滑空場では、何m以上が航空交通管制区になりますか。"],
 hint:"航空法第92条第1項が、無資格者の操縦練習・限定外機種での練習・危険な飛行（急姿勢変更等）を管制区・管制圏で原則禁止し、ただし書の許可が必要としている点を説明できるか。そのうえで、半径9km・4,000ft MSL・日の出から日没・期間（令和8年7月1日〜9月30日）の4点、誰が申請し誰が許可しているか、期間が3か月なのは継続申請で更新を重ねているためだという点が言えているか。"},

{cat:"law", imp:3, examiner:["shorui"],
 q:"92条の許可には、どのような条件が付いていますか。",
 a:"許可書本文の条件は1つで、運航の安全または地上もしくは水上の人もしくは物件の安全に影響を及ぼすような重要な事情の変化があった場合は、許可を取り消し、または新たに条件を付加することがある、というものです。加えて申請書の「その他参考となる事項」に、実際の運航で守るべきことが書かれています。操縦練習飛行は操縦練習許可書が有効な者を対象とすること。操縦練習許可書または航空身体検査証明の期限が申請期間中に切れる場合は更新し、有効でなければ練習を行わないこと。人または家屋の密集する地域上空では練習飛行をしないこと。緊急時においても地上の物件に影響を及ぼさない経路を飛行すること。周囲の見張りには特に注意して実施すること。そして許可期間内であっても、航空交通量や管制方式に状況変化があった場合は報告すること、です。",
 s:"許可書本文の条件は1つで、重要な事情の変化があれば許可を取り消し、または条件を付加することがある、というものです。加えて申請書に、操縦練習許可書が有効な者を対象とすること、人家の密集する地域上空で練習しないこと、見張りに特に注意することなどが書かれています。",
 rel:["92条の操縦練習飛行等許可について、内容を説明してください。", "人又は家屋が密集している地域とは、具体的にどのような場所を指しますか。", "「技量があれば安全に飛べる」と言えますか。"],
 hint:"許可書の条件（重要な事情の変化）と、申請書側の遵守事項を区別できているか。見張りと密集地上空を避けることの2つは特に落とさない。"},

{cat:"airspace", imp:2, examiner:["shorui"],
 q:"滝川滑空場の周辺には、どのような障害物がありますか。最低安全高度との関係はどうなりますか。",
 a:"押さえているのは4つです。南側に滝新橋で高さ13m、42ft。南東側にごみ焼却場の煙突で55m、180ft。市街地は市役所が60mで海抜が30m、屋上が海抜90mになります。これに人家密集地域の安全高度300mを足して海抜390m、約1,300ftです。クラブの資料では余裕を見て400mと書かれています。そして百年記念塔が80mで、海抜が高い位置にあるため1,400ft以上が必要です。最低安全高度は、人または家屋の密集する地域では、その航空機を中心として水平距離600m以内の最も高い障害物の上端から300m。それ以外の地域では地上または水面から150mです。滝川では市街地の約1,300ftと百年記念塔の1,400ftが実質的な下限になります。",
 s:"市街地は市役所60mに海抜30mを足した屋上90mに、安全高度300mを足して海抜390m、約1,300ft。百年記念塔が80mで1,400ft以上です。最低安全高度は、人家の密集する地域では600m以内の最も高い障害物の上端から300m、それ以外は地上から150mです。",
 rel:["最低安全高度について説明してください。", "人又は家屋が密集している地域とは、具体的にどのような場所を指しますか。", "滝川滑空場の特性と利用法について説明してください。"],
 hint:"4つの障害物のうち3つ以上を高さとともに挙げられるか。市街地の約1,300ftを「障害物の高さ＋海抜＋300m」として組み立てて説明できるか。"},

// E. 気象
{cat:"weather", imp:3, examiner:["shorui"],
 q:"出発前確認では、どのような気象資料を見ていますか。",
 a:"出発前の気象確認では、大きな場から小さな場へ順に5つを見ます。1つ目が気象庁の天気図（地上・予想天気図）で、総観場を掴みます。2つ目が気象衛星ひまわりの赤外画像で、雲頂の高さや雲の厚みを見ます（夜間も見られます）。3つ目が同じくひまわりの可視画像で、下層雲や対流雲の様子を見ます（日中のみ）。4つ目が下層悪天予想図（北海道）で、実際に効いてくる数字がここに出ます。5つ目がMETARとTAFで、近傍空港の実況と予報を数字で裏取りします。最後に、現地での確認として観天望気・吹き流し・実測を行います。",
 s:"気象庁の天気図（総観場）、ひまわりの赤外画像（雲頂の高さ）、可視画像（下層雲の様子）、下層悪天予想図（実際に効く数字）、METAR/TAF（近傍空港の実況・予報）の順に見て、最後に現地での確認として観天望気などを行います。",
 rel:["機長の出発前確認事項（航空法第73条の2）の項目をすべて述べてください。", "高層天気図（Soundings）の赤い線と青い線は", "運航の気象条件はどのように定められていますか。"],
 hint:"①総観（天気図）→②雲の全体像（赤外画像）→③下層の実況（可視画像）→④効いてくる予想（下層悪天予想図）→⑤近傍空港の数字（METAR/TAF）→現地での確認、という順序と粒度で説明できているか。"},

{cat:"weather", imp:3, examiner:["shorui"],
 q:"運航の気象条件はどのように定められていますか。横風はどのように見積もりますか。",
 a:"グライダーの運航における気象条件は、航空法に基づく視界（VFR）の基準と、メーカーが機体ごとに指定している飛行規程（Flight Manual）に記載された運用限界の双方によって定められています。VMCは雲底300m、視程5000m、正対風30kt、横風20ktで、機体側はASK21の横風限界が飛行規程2-5で8ktです。VMCの20ktより機体の8ktのほうが厳しいので、実際に効いてくるのは8ktです。ここを取り違えないことが要点になります。横風成分は早見表で見積もります。表は風速10ktのときの横風成分で、風向と滑走路のなす角が10度で2、20度で3、30度で5、40度で6、50度で8、60度で10。割合に直すと、10度で2割、20度で3割、30度で5割、40度で6割、50度で8割、60度以上で10割です。これは角度のサインにほぼ一致する値で、60度以上だけは安全側に、風速をそのまま横風とみなしています。機体の8ktから逆算すると、60度以上の風なら風速8ktまで、50度で10kt、40度で13kt、30度で16kt、20度で26ktまでが目安になります。",
 s:"気象条件は、航空法のVFR基準と、機体ごとの飛行規程の運用限界の両方で定められています。VMCは雲底300m・視程5000m・正対風30kt・横風20kt、機体側はASK21の横風限界8kt（飛行規程2-5）で、厳しいほうの8ktが実際に効きます。横風成分は早見表（角度に応じて風速の1〜10割）で見積もり、8ktから逆算すると60度以上なら風速8kt、30度なら16ktが目安です。",
 rel:["ASK21の横風限界は何ノットですか。", "ウインドソック（吹き流し）で風速はどのように判断しますか。", "風向が上空と地上とで異なります。どうしますか。"],
 note:"視程5,000mは、出発前確認の資料では「降雨5km」と書かれていますが、視程5,000mの誤記であることを確認済みです。また早見表の数値は、10度から50度までは角度のサインとほぼ一致し、60度だけが安全側に切り上げられています。",
 hint:"VMCの条件と機体側の限界を区別し、厳しいほうの8ktが効くと言えているか。早見表の割合（30度で半分、60度以上で全部）を説明でき、8ktから風速を逆算できるか。"},

// F. 積載物
{cat:"departure", imp:2, examiner:["shorui"],
 q:"積載物の安全性としては何を確認しますか。",
 a:"積んでいるものの種類、重量、搭載場所、固定状況の4つを確認します。JA20HCでは2つあります。1つは無線機のバッテリー2個で合計1.0kg、場所は左右の翼根貨物室、バッテリー専用ケースに入れて固定ネジで留めています。もう1つが固定バラスト4.0kgで、前席の足元に固定ネジで留めています。翼根貨物室は飛行規程で左右それぞれ最大10kgと定められているので、その範囲内であることもあわせて確認します。固定が緩んでいると、飛行中に移動して重心が変わったり、操縦系統に干渉したりするおそれがあるため、固定状況の確認が要点になります。",
 s:"種類、重量、搭載場所、固定状況の4つを確認します。JA20HCでは、無線機のバッテリー2個で合計1.0kgを左右の翼根貨物室に専用ケースで、固定バラスト4.0kgを前席の足元に固定ネジで留めています。翼根貨物室の上限は左右それぞれ10kgです。",
 rel:["機長の出発前確認事項（航空法第73条の2）の項目を", "重量限界にはどのようなものがありますか。", "今日の離陸重量と重心位置を計算して示してください。"],
 hint:"種類・重量・場所・固定状況の4点で整理できているか。固定が要点である理由（重心移動・操縦系統への干渉）を言えるか。"},

// G. 書類の食い違い（教材価値の高い2問）
{cat:"departure", imp:1, examiner:["yuda"],
 q:"航空日誌にはどのようなことを記載しますか。",
 a:"航空日誌は機体の履歴を残すもので、飛行に関する記録と整備に関する記録が入ります。飛行の記録としては、飛行年月日、乗組員、飛行の目的、離着陸の場所と時刻、飛行時間、そして飛行回数。整備の記録としては、実施した整備や改造の内容、実施年月日、実施者と確認者です。出発前確認では、総飛行時間と総飛行回数、耐空証明検査後の時間と回数を航空日誌で確認し、レリーズのように回数で管理している装備品の残り回数もここから追います。",
 s:"飛行の記録と整備の記録が入ります。飛行は、飛行年月日、乗組員、目的、離着陸の場所と時刻、飛行時間、飛行回数。整備は、実施した整備や改造の内容、実施年月日、実施者と確認者です。出発前確認では、総飛行時間と回数をここで確認します。",
 rel:["整備状況として何を確認しますか。", "装備品の使用期限はどのように管理していますか。", "機体に備え付ける書類を、根拠条文とあわせてすべて挙げてください。"],
 hint:"飛行の記録と整備の記録の2系統に分けて説明できているか。回数管理の装備品を追う元帳でもあることに触れられるか。"},
// ── 安全理論（Fuka先生 TEM講習・2026）──────────────────────
{cat:"tem", imp:3, examiner:["fuka"],
 q:"スレット（脅威）とは何ですか。具体例を挙げてください。",
 a:"乗員が関与できない領域で生じるもので、乗員が引き起こすものではありません。スレットがあると運航が複雑化し、安全マージンを維持するには対抗手段が必要になります。大きく2つに分けられます。環境的スレットは、天候の変化、ATCの混乱した通信、着陸機の混雑、似たコールサインなど。組織的スレットは、機体の故障、地上要員のエラー、フライトサービスのエラーなどです。滑空機でいえば、雲底が下がってくること、曳航機側の事情、ウインチや索の状態、他機の混雑などが該当します。",
 s:"乗員が関与できない領域で生じるもので、乗員が引き起こすものではありません。環境的スレットは天候の変化やATCの混雑、組織的スレットは機体の故障や地上要員のエラーです。滑空機なら雲底の低下や曳航機側の事情です。",
 rel:["エラーとはどのようなものですか。具体例を挙げてください。", "スレット・アンド・エラーマネジメント（TEM）について説明してください。", "スレットマネジメントとは何をすることですか。"],
 hint:"「乗員が関与できない領域で生じる／乗員が引き起こすものではない」という定義が言えているか。環境的スレットと組織的スレットに分けて例を挙げられるか。"},

{cat:"tem", imp:3, examiner:["fuka"],
 q:"エラーとはどのようなものですか。具体例を挙げてください。",
 a:"組織やクルー自身が、するはずのこと、できるはずのことをしなかった、またはできなかった状態です。スレットと違って、自分たちが生み出すものだという点が区別の鍵になります。安全マージンを低下させます。例は3つに分けると整理しやすいです。操縦のエラーは、ピッチ・ヨー・速度の変動や、不適切なダイブの操作量。プロシージャのエラーは、チェックリストの省略や、復唱・相互確認を怠ること。コミュニケーションのエラーは、コールサインの誤りや、曖昧なコミュニケーションです。",
 s:"組織やクルー自身が、するはずのこと、できるはずのことをしなかった、またはできなかった状態です。自分たちが生み出す点がスレットとの違いです。操縦、プロシージャ、コミュニケーションの3つに分けると整理できます。",
 rel:["スレット（脅威）とは何ですか。具体例を挙げてください。", "エラーが発生したら、それは事故につながりますか。", "UAS（望ましくない航空機の状態）とは何ですか。"],
 hint:"「するはずのこと・できるはずのことをしなかった、またはできなかった状態」という定義が言えているか。操縦・プロシージャ・コミュニケーションの3つに分けて例を挙げられるか。"},

{cat:"tem", imp:3, examiner:["fuka"],
 q:"UAS（望ましくない航空機の状態）とは何ですか。事故の一歩手前ということですか。",
 a:"クルーのエラーから生じた、航空機の安全マージンが低下した状態のことです。ただし必ずしも事故の一歩手前に限りません。ここは誤解しやすいところです。飛行状態としては、高度が不安定なまま飛んでいる、ピッチやヨー、速度が変動し続けている、運用限界の外で飛行している、といったものが該当します。航空機の状態としては、操縦系統の誤接続、無線機の作動不良、重量重心位置の誤りなどです。身近な例では、JA20HCの無線が不調だったことがありましたが、あれもUASにあたります。",
 s:"クルーのエラーから生じた、安全マージンが低下した状態です。必ずしも事故の一歩手前とは限りません。高度が不安定、運用限界の外で飛んでいる、操縦系統の誤接続、無線機の作動不良などが該当します。",
 rel:["エラーが発生したら、それは事故につながりますか。", "UASマネジメントでは何をしますか。", "エラーとはどのようなものですか。具体例を挙げてください。"],
 hint:"「エラーから生じた安全マージンの低下した状態」であること、「必ずしも事故の一歩手前ではない」ことの両方が言えているか。飛行状態と航空機の状態の2系統で例を挙げられるか。"},

{cat:"tem", imp:3, examiner:["fuka"],
 q:"スレットマネジメントとは何をすることですか。",
 a:"スレットに対して対抗手段を講じることです。中心になるのが事前準備による対抗手段で、予測できるスレットを早期に発見し、対処方法をあらかじめ検討しておくことです。ただし、すべてを予測することはできません。ここが要点で、予測できなかったスレットが表面化したときに、その対処へ一点集中してしまうと、それがエラーにつながり、さらに事故につながります。ですから鉄則は、絶対に一点集中しないこと、そして機体を飛ばし続けることをまず基本にすることです。無線が故障したときの対処法などは、この考え方に含まれます。",
 s:"スレットに対して対抗手段を講じることです。中心は事前準備で、予測できるスレットを早期に発見し、対処方法を決めておきます。ただし全部は予測できないので、表面化したときに一点集中しないこと、機体を飛ばし続けることが鉄則です。",
 rel:["一点集中がなぜ危険なのですか。実際の事故の例はありますか。", "スレット（脅威）とは何ですか。具体例を挙げてください。", "UASマネジメントでは何をしますか。"],
 hint:"「事前準備による対抗手段」が中心だと言えているか。「すべては予測できない」「一点集中しない」「機体を飛ばし続ける」まで踏み込めているか。"},

{cat:"tem", imp:3, examiner:["fuka"],
 q:"UASマネジメントでは何をしますか。",
 a:"UASが発生していることを早期に発見することが極めて重要です。そのために有効なのがレビュー・カウンターメジャーで、自分の行動、あるいは行動しなかったことの結果が、航空機の状態にどう反映しているかを、いちいち振り返ることです。行動する前に計画した状態が実現しているかを振り返る。チェックリスト、復唱、相互確認を実行する。はっきりしないときは問い合わせて確認する。これらが具体的な手立てになります。ここで一番危ないのが、自分がやってしまったエラーの修正に集中してしまうことです。その結果、航空機の状態を正常にすることを忘れてしまいます。エラーの修正ではなく、航空機の状態を正常に戻すことを考える、というメンタリティが必要です。",
 s:"早期に発見することが最も重要です。そのために、自分の行動が航空機の状態にどう反映しているかを、いちいち振り返ります。一番危ないのは自分のエラーの修正に集中することで、エラーではなく航空機の状態を正常に戻すことを考えます。",
 rel:["一点集中がなぜ危険なのですか。実際の事故の例はありますか。", "UAS（望ましくない航空機の状態）とは何ですか。", "スレットマネジメントとは何をすることですか。"],
 hint:"「早期発見が重要」「レビューで自分の行動の結果を振り返る」が言えているか。「エラーの修正ではなく航空機の状態を正常に戻す」という優先順位まで言えるか。"},

{cat:"tem", imp:2, examiner:["fuka"],
 q:"一点集中がなぜ危険なのですか。実際の事故の例はありますか。",
 a:"対処に気を取られると、そのあいだ機体を見なくなり、それ自体がエラーになって事故につながるからです。代表例がイースタン航空401便、L-1011トライスターの墜落です。ランディングギアの状態を示すライトに異常が出ましたが、実際は電球が切れていただけでした。ところがクルー全員が電球の交換とノーズギアの位置確認に気を取られ、そのあいだ誰も外を見ておらず、計器もモニターしていませんでした。4分が経過するうちに機長の手が誤って操縦桿に触れ、操縦桿に力が加わると解除される機体だったためオートパイロットが解除されました。誰も気づかないまま機首が下がって降下を続け、最後の瞬間に機長が気づいたものの間に合わず墜落しました。ですから、何かが起きても機体を飛ばし続けることをまず基本にします。",
 s:"対処に気を取られると、そのあいだ機体を見なくなり、それ自体がエラーになるからです。代表例がイースタン航空401便の墜落で、切れた電球に全員が気を取られ、誰も外を見ず計器も見ていないうちにオートパイロットが外れ、機首が下がって墜落しました。何かが起きても機体を飛ばし続けることが基本です。",
 rel:["スレットマネジメントとは何をすることですか。", "UASマネジメントでは何をしますか。", "上空で無線が故障したら、どのように対応しますか。"],
 hint:"「対処に集中すると機体を見なくなる」という因果が言えているか。事例を1つ挙げて説明できるか。結論として「まず機体を飛ばし続ける」に着地できているか。"},

{cat:"tem", imp:2, examiner:["fuka"],
 q:"IMSAFEとは何ですか。日本語で答えてください。",
 a:"パイロットの心身の状態を確認するチェックリストです。Iがイルネスで病気、Mがメディスンで服薬、Sがスリープで睡眠、Aがアルコールで飲酒、Fがファティーグで疲労、Eがエモーションで感情の6つです。飛ぶ前に自分自身を点検するためのもので、TEMでいえば自分自身がスレットになっていないかを確かめる作業にあたります。",
 s:"パイロットの心身の状態を確認するチェックリストです。Iがイルネスで病気、Mがメディスンで服薬、Sがスリープで睡眠、Aがアルコールで飲酒、Fがファティーグで疲労、Eがエモーションで感情の6つです。",
 rel:["SHELL理論とはどのような考え方ですか。", "スレット（脅威）とは何ですか。具体例を挙げてください。", "低体温症とはどのような状態ですか。"],
 hint:"6つを日本語で全部言えるか。病気・服薬・睡眠・飲酒・疲労・感情。順序も含めて暗記しておく。"},

{cat:"tem", imp:2, examiner:["fuka"],
 q:"SHELL理論とはどのような考え方ですか。",
 a:"人と、その周りの要素との噛み合わせで事故を捉える考え方です。中心にあるのが当事者、ライブウェアとしてのL、つまり自分。その周りに、他の人間としてのL、ハードウェアのH、これは機体や計器。ソフトウェアのS、これは規程や手順、チェックリスト。そして環境のEが配置されます。中心の自分と周りの4つがパズルのようにきっちり噛み合っていれば事故は防がれますが、形の合わないところ、つまりミスマッチがあると、そこが事故の原因になる、という考え方です。現在の安全理論の基礎になっているもので、細部よりも、噛み合わないと駄目だ、という構図を理解しておけば十分です。",
 s:"人と、その周りの要素との噛み合わせで事故を捉える考え方です。中心に自分、ライブウェアのL。周りに他の人間のL、ハードウェアのH、ソフトウェアのS、環境のEが配置されます。噛み合っていれば事故は防がれ、ミスマッチがあるとそこが原因になる、という構図です。",
 rel:["IMSAFEとは何ですか。日本語で答えてください。", "スレット・アンド・エラーマネジメント（TEM）について説明してください。"],
 hint:"中心のLが自分であること、S・H・E・Lの4要素、そして「ミスマッチが事故の原因になる」という結論が言えているか。"},

// ── フライトサービス（法的な立ち位置）──────────
{cat:"airspace", imp:3, examiner:["fuka"],
 q:"フライトサービスとは何ですか。パイロットに指示を出せるのですか。助言はできますか。",
 a:"飛行場や空域を利用するパイロットに対し、気象情報や航空情報の提供、フライトプランの授受など、飛行の安全に必要な情報提供・支援を行う業務です。指示は出せませんし、助言もできません。法的にできるのは情報提供だけです。情報提供というのは、地上の風向風速、滑走路が空いているかどうか、トラフィックの有無といった事実をそのまま伝えることです。これに対して助言は、たとえば反対側の上空に別のグライダーがいるので、その後に降りた方がよいのではないか、というように判断が含まれるもので、これはできません。したがって、法的にはフライトサービスに何を言われてもパイロットに従う義務はなく、あくまで機長の判断です。仮にフライトサービスの情報が間違っていて事故が起きたとしても、最終責任は機長にあります。試験で答えるときは「フライトサービスの指示があるので」という言い方は絶対にしないことです。フライトサービスに指示を出す権限はないので、その一言で法的な立ち位置を理解していないと見られます。正しくは「フライトサービスの情報提供をもとに、自分が決めます」という姿勢を示します。実際、着陸が交錯したときでも、フライトサービスは、こちらがナンバーワンでそちらがナンバーツー、といった指示はしません。管制官であれば必ずしなければならない場面ですが、管制官ではないからこそしないのです。そのぶん、パイロットの側から自発的に、こちら先に降ります、あるいはそちらが先に降りてください、こちらはナンバー2です、と申告することが期待されています。",
 s:"パイロットへの情報提供・支援業務です。指示も助言もできません。法的にできるのは情報提供だけです。風向風速や滑走路の状況、トラフィックの有無といった事実を伝えるのが情報提供で、判断が含まれるものは助言にあたります。最終責任は機長にあります。試験では「フライトサービスの指示があるので」とは絶対に言わず、「情報提供をもとに自分が決めます」という姿勢で答えます。",
 note:"グライダーの世界では、機体間の距離が短く離着陸が相次ぐ特性から古くからピストが置かれ、管制官に近い役割を果たすことが暗黙に認められてきた経緯があります。フライトサービスもその延長にあり、実務と法的権限のあいだに曖昧さが残っている領域です。",
 rel:["滑空場によっては、VHF以外にどのような無線機が使われていますか。", "曳航中の合図にはどのようなものがありますか。", "「技量があれば安全に飛べる」と言えますか。"],
 hint:"パイロットへの情報提供・支援業務であるという定義、「指示も助言もできない、できるのは情報提供だけ」と言い切れているか。情報提供と助言の違いを例で説明できるか。最終責任は機長にあると結べているか。試験で「フライトサービスの指示があるので」と言ってはいけない理由、着陸順を自発的に申告する話まで出せるか。"},

// ── 捜索救難の段階の根拠 ──────────
{cat:"emergency", imp:1, examiner:["fuka"],
 q:"捜索救難の不確実・警戒・非常という段階は、どこに定められているのですか。",
 a:"捜索救難（SAR）の「不確実の段階」「警戒の段階」「非常の段階（遭難の段階とも呼ばれます）」という3つのフェーズは、国際条約とそれを国内に反映した関係省庁間の協定・実施細目に定められています。国際的には、国際民間航空条約（シカゴ条約）第12附属書（Annex 12：Search and Rescue）に定められており、それぞれ不確実の段階がINCERFA（Uncertainty phase）、警戒の段階がALERFA（Alert phase）、遭難（非常）の段階がDETRESFA（Distress phase）という世界共通のコードで呼ばれています。日本国内では、この国際基準に準拠して、警察庁、消防庁、防衛省、海上保安庁、国土交通省（航空局）などの間で結ばれた「航空機の捜索救難に関する協定」第7条に「緊急状態の三段階」として直接明記されています。",
 s:"国際民間航空条約（シカゴ条約）に基づき、不確実の段階（INCERFA）、警戒の段階（ALERFA）、遭難の段階（DETRESFA）として定められています。日本国内では、警察庁・消防庁・防衛省・海上保安庁・国土交通省（航空局）などが結ぶ「航空機の捜索救難に関する協定」第7条に「緊急状態の三段階」として明記されています。",
 note:"協定名・条文番号(第7条)は、ユーザー提供の参考資料に基づく記載です。協定の本文そのものには当たれていません。段階の名称と基準は、AIMの捜索救難のページとICAO第12附属書（Annex 12）で確認できます。",
 rel:["捜索救難の段階区分について説明してください。", "捜索救難活動を取り仕切る機関はどこですか。", "航空情報にはどのような種類があり、どのように更新されますか。"],
 hint:"国際民間航空条約（シカゴ条約）第12附属書（Annex 12）に定められていること、INCERFA・ALERFA・DETRESFAという国際共通コード、日本国内では航空機の捜索救難に関する協定第7条に明記されていることのいずれかに触れているか。"},

{cat:"inflight", imp:1, examiner:["fuka"],
 q:"滑空機の巡航について聞かれたら、どう答えますか。",
 a:"巡航はできません、と答えます。滑空機は動力を持たないので、一定の高度を保って飛び続けるという意味の巡航はできません。上昇気流の中にいるあいだは高度を保てますが、それは巡航とは呼びません。聞かれることはまずない設問ですが、聞かれたら一定高度での巡航はできません、と答えればそれで終わりです。",
 s:"巡航はできません。",
 rel:["巡航高度とは何ですか。地上からの高さ（AGL）とQNH高度のどちらで表されますか。", "最良滑空比速度は、風や沈下率の状況に応じてどのように調整しますか。"],
 hint:"「できません」と言い切れているか。動力がないので一定高度を保って飛び続けられない、という理由を添えられるか。"},

// ═══════════════════════════════════════════════════════════════════
// 見張り・衝突防止（Fuka先生 講義 第10章より）
// 2026.8.17 湯田試験官の講評「上空ではルックアウトが十分ではありませんでした」
// を受けて、見張りそのものを口述で答える形の設問を用意した。
// ═══════════════════════════════════════════════════════════════════

{cat:"lookout", imp:3, examiner:["fuka"],
 q:"上空での見張りは、具体的にどのように行っていますか。",
 a:"視野全体をだらっと眺めるのではなく、いくつかのブロックに分けて、1ブロックあたり数秒ずつ視線を止めながら順番に動かしていく、スキャニングという方法で行っています。視線を止めるのは、精細に見えているのが視線の中心のわずか約3度しかないためで、流し見では中心視がどこにも合わず、実際には何も確認できていないことになります。ブロックごとに止めることで、中心視でそのブロックを確実に確認しながら、同時に視線を動かすことで周辺視野も活性化させられます。旋回中はスキャンの方向を水平線の方向に保ち、下がった翼の側ばかりを見ないようにします。",
 s:"視野をいくつかのブロックに分けて、1ブロックあたり数秒ずつ視線を止めながら順に動かす、スキャニングで行っています。精細に見えるのは視線の中心の約3度だけなので、流し見では実際には何も確認できていないからです。旋回中はスキャンの方向を水平線方向に保ちます。",
 rel:["人間の目にはどのような限界がありますか", "コリジョンコース上の相手機は、なぜ見つけにくい", "見張りの義務は、どの条文に"],
 hint:"「よく見ています」で終わらず、ブロックに分けて数秒ずつ止める、という具体的な方法を言えているか。中心視が約3度しかないという理由まで言えるか。"},

{cat:"lookout", imp:3, examiner:["fuka"],
 q:"人間の目にはどのような限界がありますか。見張りにはどう影響しますか。",
 a:"3つあります。1つ目、精細に見えるのは視線の中心からわずか約3度の中心視だけで、水平視野角は約200度、垂直視野角は約140度あっても、その大半では動きを感じ取れる程度でしかありません。2つ目、死角です。頭を動かさずに前を見ていると、上方と水平方向にもキャノピーの枠や計器板に遮られる範囲があり、斜め下から真下はほとんど見えず、後方は当然見えません。3つ目、コリジョンコース上の相手機は止まって見えるため、動きを感知する周辺視野では見つけられません。したがって、頭を動かして死角を消し、視線を止めながらスキャンする必要があります。",
 s:"精細に見えるのは視線の中心の約3度だけで、視野の大半では動きを感じ取れる程度です。加えて、キャノピーの枠や計器板による死角があり、斜め下から真下と後方はほとんど見えません。ですから、頭を動かして死角を消し、視線を止めながらスキャンする必要があります。",
 rel:["上空での見張りは、具体的にどのように", "コリジョンコース上の相手機は、なぜ見つけにくい"],
 hint:"中心視が約3度という数値を言えるか。死角の存在（下方・後方・枠）に触れられるか。"},

{cat:"lookout", imp:3, examiner:["fuka"],
 q:"コリジョンコース上の相手機は、なぜ見つけにくいのですか。",
 a:"止まって見えるからです。互いに衝突するコースに入っている2機は、相対的な方位角が変化しません。視野の中で位置が動かないため、動きを感知することで働く周辺視野には引っかからず、たまたま中心視がそこへ向いたときにしか気づけません。しかも相手機は最後まで豆粒のように小さいままで、衝突の数秒前になって初めて急に大きくなります。大きくなったと気づいたときには回避が間に合いません。逆に言えば、視野の中で動いて見えている相手機はぶつからない、というのが見分け方になります。",
 s:"止まって見えるからです。衝突コースに入った2機は相対方位が変わらないので、動きを感知する周辺視野には引っかかりません。しかも最後まで小さいままで、数秒前に急に大きくなります。逆に、動いて見えている相手機はぶつからない、というのが見分け方です。",
 rel:["相手機を発見しました。ぶつかりそうかどうかは", "人間の目にはどのような限界がありますか", "航空機同士がコリジョンコース（衝突コース）にある場合"],
 hint:"「相対方位が変わらないから止まって見える」と説明できるか。動いて見えるならぶつからない、という裏返しまで言えるか。"},

{cat:"lookout", imp:3, examiner:["fuka"],
 q:"相手機を発見しました。ぶつかりそうかどうかは、どう判断しますか。避けるときはどうしますか。",
 a:"視野の中で相手機が動いて見えるかどうかで判断します。動いて見えるうちはぶつかりません。止まって見えるなら衝突コースなので、危険と判断します。避け方は2つあります。1つは、相手機の後方へ回り込むように針路を大きく変えること。中途半端に変えると相対方位が変わらないままになるので、大きく変えるのが要点です。もう1つは、高度差をつけること。上昇するか降下するかで高度差が大きくなれば衝突しません。いずれにしても、まず回避します。進路権の議論は着陸してからです。",
 s:"視野の中で動いて見えるうちはぶつかりません。止まって見えるなら衝突コースなので危険です。避け方は、相手機の後方へ回り込むように針路を大きく変えるか、上昇か降下で高度差をつけるかです。まず回避、進路権の議論は着陸してからです。",
 rel:["コリジョンコース上の相手機は、なぜ見つけにくい", "進路権を有する航空機は、その進路及び速度を維持", "滑空機の進路権について説明してください"],
 hint:"「動いて見えるか、止まって見えるか」で判断すると言えているか。針路を大きく変える、高度差をつける、という2つの避け方を挙げられるか。"},

{cat:"lookout", imp:3, examiner:["fuka"],
 q:"進路権を有する航空機は、その進路及び速度を維持しなければならないとされています。「まず回避」とは矛盾しませんか。",
 a:"矛盾しません。進路及び速度を維持するというのは、相手が避けやすいように予測可能な動きをする、という趣旨であって、衝突コースにあっても直進を続けてよいという意味ではありません。航空法第71条の2の見張り義務は、進路権の有無にかかわらず、すべての操縦者に課されています。ですから、進路権があっても、このままでは衝突すると判断した時点で回避します。「法的に進路権があるのだからこのまま進む」というのは、心理的な危険性として挙げられている大きな勘違いです。進路権は事故を防ぐための順位づけであって、事故に遭ってよい根拠ではありません。",
 s:"矛盾しません。進路及び速度を維持するのは、相手が避けやすいように予測可能な動きをするという趣旨で、衝突コースでも直進してよいという意味ではありません。第71条の2の見張り義務は進路権の有無によらず全員に課されるので、衝突すると判断した時点で回避します。",
 rel:["相手機を発見しました。ぶつかりそうかどうかは", "滑空機の進路権について説明してください", "見張りの義務は、どの条文に"],
 hint:"「進路権があるから進む」と答えていないか。維持義務の趣旨（予測可能な動き）と、見張り義務が進路権と無関係であることを説明できるか。"},

{cat:"lookout", imp:3, examiner:["fuka"],
 q:"見張りの義務は、どの条文に定められていますか。計器飛行方式でも必要ですか。機長でなくても必要ですか。",
 a:"航空法第71条の2です。条文は、航空機の操縦を行う者は、航行中、当該航空機外の物件を視認できない気象状態にある場合を除き、他の航空機その他の物件と衝突しないように見張りをしなければならない、というものです。ここで主語が「操縦を行う者」なので、有視界飛行方式か計器飛行方式かにかかわらず必要ですし、機長でなくても、操縦している以上は義務があります。除外されるのは、雲中のように機外の物件をそもそも視認できない気象状態にある場合だけです。",
 s:"航空法第71条の2です。「航空機の操縦を行う者は、航行中、機外の物件を視認できない気象状態にある場合を除き、衝突しないように見張りをしなければならない」とされています。主語が操縦を行う者なので、計器飛行方式でも、機長でなくても義務があります。",
 rel:["上空での見張りは、具体的にどのように", "進路権を有する航空機は、その進路及び速度を維持", "滑空機の進路権について説明してください"],
 hint:"条文番号を言えるか。「操縦を行う者」が主語であることから、IFRでも機長以外でも義務がある、と導けるか。"},

{cat:"lookout", imp:2, examiner:["fuka"],
 q:"他機に自分の位置を伝えるときは、どのように言いますか。",
 a:"相手機から見た自分の位置を、方位、または時計の文字盤の方向で伝えます。相手の正面が12時、右真横が3時、真後ろが6時です。あわせて高度差を、上に何フィート、下に何フィートというかたちで添えます。自分から見た位置を言っても相手には伝わらないので、相手の立場に置き換えて言うのが要点です。距離も分かれば加えます。",
 s:"相手機から見た自分の位置を、方位または時計の文字盤の方向で伝えます。相手の正面が12時、右真横が3時、真後ろが6時です。あわせて高度差を、上に何フィート、下に何フィートと添えます。自分から見た位置ではなく、相手の立場に置き換えて言うのが要点です。",
 rel:["衝突の危険が高まるのは、どのような状況", "「耳張り」とは何ですか"],
 hint:"「相手から見た位置」で言うことを押さえられているか。時計の文字盤と高度差の両方を挙げられるか。"},

{cat:"lookout", imp:2, examiner:["fuka"],
 q:"衝突の危険が高まるのは、どのような状況ですか。",
 a:"機体が1か所に集まる状況です。4つ挙げられます。1つ目、積雲ができた直後に、みんなが一斉に同じ雲の下へ向かうとき。2つ目、上昇できる場所が限られていて、そこが過密になるとき。3つ目、一斉にサーマルがなくなって、多数機が同時に着陸に向かうとき。4つ目、コンバージェンスの下を多数機が同じ針路で移動するとき。いずれも、自分だけでなく他機も同じ判断をしている、という点が共通しています。だからこそ、目視だけでなく無線で他機の状況を把握しておくことが効いてきます。",
 s:"機体が1か所に集まる状況です。積雲ができた直後に一斉に同じ雲の下へ向かうとき、上昇できる場所が限られて過密になるとき、一斉にサーマルがなくなって多数機が同時に着陸するとき、コンバージェンスの下を多数機が同じ針路で移動するときです。",
 rel:["「耳張り」とは何ですか", "上空での見張りは、具体的にどのように"],
 hint:"「他機も自分と同じ判断をする」という共通点に気づけているか。具体的な状況を複数挙げられるか。"},

{cat:"lookout", imp:2, examiner:["fuka"],
 q:"「耳張り」とは何ですか。",
 a:"無線を聞いて、他機がいまどこで何をしているかを常に把握しておくことです。目で見る見張りには、中心視が約3度しかないこと、死角があること、コリジョンコース上の機体は止まって見えることといった限界があるので、その穴を耳で埋める、という考え方になります。だれがどのサーマルにいる、だれが場周に入った、といった情報が頭に入っていれば、どこを重点的に見るべきかが分かります。地上で待っているあいだから無線を聞いて他機の状況を追う習慣をつけておくと、上空でも自然にできるようになります。",
 s:"無線を聞いて、他機がいまどこで何をしているかを常に把握しておくことです。目で見る見張りには中心視の狭さや死角といった限界があるので、その穴を耳で埋める、という考え方です。どこを重点的に見るべきかが分かるようになります。",
 rel:["衝突の危険が高まるのは、どのような状況", "他機に自分の位置を伝えるときは"],
 hint:"目視の限界を耳で補う、という位置づけを説明できているか。地上からの習慣づけに触れられるか。"},

{cat:"lookout", imp:2, examiner:["fuka"],
 q:"見張りについて、パイロットが陥りやすい思い込みには何がありますか。",
 a:"4つ挙げられます。1つ目、自分は衝突なんかしない、という正常性バイアス。2つ目、自分は常に気を付けている安全なパイロットだ、という過信。3つ目、自分は腕がいいのだから事故らない、という過信。4つ目、法的に進路権があるのだからこのまま進む、という大きな勘違いです。空中衝突のリスクは常在かつ遍在していて、パイロットの腕とは関係がありません。超一流のパイロットでも事故に遭います。ですから、自分も衝突事故に巻き込まれるかもしれない、と常に意識していることが、いちばん大事な心構えになります。",
 s:"4つあります。自分は衝突しないという正常性バイアス、自分は気を付けているという過信、腕がいいから事故らないという過信、そして進路権があるからこのまま進む、という勘違いです。衝突のリスクは腕とは関係なく常に存在するので、自分も巻き込まれるかもしれないと意識し続けることが大事です。",
 rel:["「技量があれば安全に飛べる」と言えますか", "進路権を有する航空機は、その進路及び速度を維持", "上空での見張りは、具体的にどのように"],
 hint:"正常性バイアスと過信という言葉を使えるか。「腕とリスクは無関係」と言い切れるか。"},

];

